/* 平成16年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h16.committeeSessions.push(...[{"id":"h16-20040120-6","meetingId":"h16-cm01","date":"2004年1月20日","dateIso":"2004-01-20","committee":"区民委員会","time":"午後１時０４分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"臨海斎場のご案内の中で、「ご注意いただくこと」の中に「心付け等の金品の授受は禁止です」と書いてあるんですけれども、今、現物を持ってきてないんですけれども、たしか葬儀屋のチラシが入ってまして、その中に、こういう値段でできますよとなっておりまして、「心付け等を踏まえて」となっていたんですけれども、この辺の、もらっちゃいけませんよということを。","respondent":"長田区民課長","answer":"臨海斎場につきましては、過日の業者説明会の中で、この部分は同じ資料を渡してありまして、業者の資料の中にも、この部分をうたってあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"嶋委員","kind":"質問","question":"私も、実はきょう午前中、初めて葬儀に行きまして、利用者の方に「どうですか」とお聞きしたら、大変に広々として、きれいで、安心しているということでしたけれども、皆さんから、交通のことはどうなっていくんだろうと。","respondent":"長田区民課長","answer":"京浜急行電鉄側といたしましては営業の部分がありますので、採算の度合いを見ないと何とも言えないということで、要望はお伝えをして、検討をしていただいているところですけれども、近い将来、いつから増便をするというような回答は、今のところいただいていない状況です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"嶋委員","kind":"質問・要望","question":"わかりました、ぜひまた、利便性等で頑張っていただきたい。信号のところに看板がなかったものですから、これから、どうなっていくのか教えていただきたいと思います。","respondent":"長田区民課長","answer":"一応、車、歩行者の想定をしまして看板を設置したところですけれども、また、そういうご意見に合わせて、もし必要な場合につきましては、また組合側と協議をしてまいります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"協定料金ですけれども、これを見た感じで、臨海斎場としても、３万円しか減額にならないんだと意識するんですけれども、３万円減額の内容を教えていただけますか。","respondent":"長田区民課長","answer":"それらの差し引きを行いまして、正確な数字を言いますと、３万１,３９０円お安くなるんですけれども、端数を切り捨てまして３万円という形で料金を設定させていただいているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"今、伺いましたけれども、３万１,３９０円下がったのを端数を切り捨てて３万円の減額というのは、これだったらやっぱり３万２,０００円減額とか。これが、新しい器になったときの葬儀社の少し私たちも下げましょうという形だと思うんです。１,３９０円業者がもうかっちゃっているという、こういう決め方というのは、何となく区民は納得がいかないんじゃないだろうか。その辺をひとつ。","respondent":"長田区民課長","answer":"そういうようなところからいたしまして、繰り上げて３万２,０００円というお話は、私どももさせていただいたんですけれども、この部分については、今までもサービスをしていて、原価を無視してやっているところもあるので、そういったところについては。","voiceIndex":13,"id":"exchange-005"},{"speaker":"松澤委員","kind":"質問・要望","question":"火葬料金というのは、一般の人はなかなか値切れないものですから、やっぱり協定料金が決まっているというと、それになるんだろうと思います。協定をつくったときに、若干、私たち下げますよ、と口では言いますよね、原価計算のことなんかはわからないわけですから。やっぱり切り上げてやっていくというのは、何となく腑に落ちないんですけれども、もう一度、しっかりとお答えをいただきたいと思うんです。","respondent":"長田区民課長","answer":"そういった中で、今回、こういった金額の設定をさせていただいたです。今後また、条件等いろいろ変わってくるときがあろうかと思いますけれども、そういった部分につきましては、松澤委員のご意見を十分頭の中に入れた交渉をしてまいりたいと考えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"松澤委員","kind":"質問・要望","question":"品川支部は１４社ということですけれども、協定に入っていない、例えば新規参入者が増えていると思うので、やはり私は、こういう協定をするんだったら、新たな新規参入業者も変えるべきじゃないのか、そういう努力もすべきじゃないかと思うんです。そういうのに変えれば、やはり市場原理の形で下がると思うんですよ。それぐらいの努力をしていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"ああいうふうに日常的じゃない動物、あるいは人間に対して危害を与えるような動物が、どこの家庭で、どういうものが飼われているかの把握はされているんでしょうか。たまたまあの蛇は毒蛇じゃなかったので大丈夫だったようですけれども、その辺の関係を思い出して、どうなっているのかなということを伺いたかったんです。","respondent":"久保田防災課長","answer":"いろいろな考え方がありますので、そういう部分について、今後、対応策について、いろいろな環境方面と一緒に考えていこうというのが趣旨ですので、その後のいろいろな課題の中の一つかなと考えています。","voiceIndex":25,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"それは下水道担当のところの責任だけじゃなくて、防災全般として見ていく必要があるんじゃないかと思いますので、その辺の関係についての、お互いの連絡の取り合いだとか、区民への周知について、ちょっと見解を伺っておきたいなと思います。","respondent":"久保田防災課長","answer":"今お話が出ていた周知とか、あるいは事前広報については、これは従来もやっておりますし、今後とも、そういうものにつきましては力を入れてやっていくという考えに変わりはございません。","voiceIndex":27,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"今やっていることは承知しているんですけれども、下水道対策と防災課としての連携というのか、その辺をやっているとは思うんですけれども、具体的に教えていただければありがたいなと思うし、安心感が増すので、その辺を再度答弁していただきたいと思います。","respondent":"久保田防災課長","answer":"防災課の役割としては、それら総合的に総括して調整するという場ですし、また、いざ災害等が起きたときに、いち早く応急対策本部を設置して、迅速な対応をするということになっていると考えています。","voiceIndex":29,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"防災地図ですけれども、地区内残留地区というのがまた増えましたよね。これは、例えば高層の建物があって、震災で倒れないというものでつくっているということですけれども、要件がどうなっているのか。当然、これから高層化、あるいは、震災対策をした耐震設計のビルができてくれば、どんどん地区内残留地区が広がる可能性があると思うんですけれども、残留地区の要件というのを、ひとつ教えてください。","respondent":"久保田防災課長","answer":"詳しく、細かくは、東京都のほうで評価しているということが前提になるんですけれども、大まかに言いますと、いわゆる耐火、耐震建築というんですか、そういうものが７０％以上市街地地域の中に存在している。","voiceIndex":31,"id":"exchange-011"},{"speaker":"松澤委員","kind":"質問・要望","question":"遠くへ避難する必要がなくなるわけですから、そういう意味では、そういう地区を広げる努力をしていただきたいと思うんです。これはどう考えても、僕は図上で線を引いたとしか思えない。実際に震災になったときにどうするか、この人たちをＪＲアパートに入れなさいというのが、戸越公園の隣ですからね、そのような意味では、まだまだここが不備だと思うんです。","respondent":"久保田防災課長","answer":"ただ、東京都のほうの回答としては、全体の中で調整した結果なので、そこの趣旨はよくわかるけれども、今の段階ではやむを得ないということで了解してくれという回答を得ているところです。","voiceIndex":33,"id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"今のような答弁しかできないんでしょうけれども、どう見ても、戸越公園一帯と品川区役所一帯というのは、大きさが同じようですけれども、地図からいうと、面積は戸越公園避難所は半分しかありませんので、これはほんとうにアンバランスですから、この点は強く、早く是正をしていただくようにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"今、最後に産業振興課長がおっしゃった円滑化、借りかえの部分で、私どもの会派で、この間の定例会で質問させていただきましたけれども、今、品川区でどのぐらいの状況なのか。３割減になるのかもしれないとおっしゃった、そこのところが、どういうふうに見ていられるのかというのを、具体的な数字でちょっと教えていただきたいと思うんです。","respondent":"市川産業振興課長","answer":"ちょっと、私どもの説明が足りなかったせいもあるんですが、厳密に言いますと、国や信用保証協会が、小規模事業者に向けてこの１年近くやってきたさまざまな緩和措置なり、負担軽減措置がある程度背景にあって、今回、私どもの利用が減ったんじゃないかという趣旨で。","voiceIndex":43,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。新しく年が明けて、いろいろな区内の関係者の新年会などに参加させていただいたときに、幾つか特徴的なのは、やっぱりこの不況の中で、ほんとうに乗り切ってここまで来たけれども、さらに今年は厳しいというふうな趣旨のごあいさつを伺ったことがありまして、区民の経営の厳しさというのが、年を明けて、改めてなるほどと思ったんです、私の印象なんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"平成１４年度でいいんですけれども、融資実行に対して、もし出ていたら、代理弁済は何件で、どのぐらいの金額か、わかれば教えていただきたい。","respondent":"市川産業振興課長","answer":"私どもの品川区で取り扱っている制度融資だけに限っての代理弁済の数ですけれども、９２件、金額にして１,９００万円。","voiceIndex":48,"id":"exchange-016"},{"speaker":"藤原委員","kind":"意見","question":"傾向として、新規の申し込みが２２％から１２％ということなんですが、下がった理由も、先ほどご説明がありましたけれども、その中に、広報といいますか、産業ニュース等でいろいろＰＲが出ていましたけれども、アピールの仕方に何かあったということとか、もしくは、もう中小企業の方が保証協会の保証する制度をほとんど使っちゃっていて、新規の申し込みよりも。","respondent":"市川産業振興課長","answer":"お客様の意向としても、今あまり無理しないで、もう少し様子を見ていたいと、こういう傾向が一番強いんじゃないかと考えております。","voiceIndex":50,"id":"exchange-017"},{"speaker":"木下委員","kind":"確認","question":"ちょっと確認でお聞きしたいんですが、ＩＣカードリーダーを使うということは、またＩＣカードリーダーを、カードを受ける際に購入しなきゃならないということですね。お幾らぐらいになるのか、わかれば教えていただければありがたいんですが。","respondent":"冨田戸籍住民課長","answer":"そのあたりは、東京都なり国のほうで、現在、調整中ということで、実施の際には、それらについては周知できるような形にしていくものと聞いております。","voiceIndex":57,"id":"exchange-018"},{"speaker":"木下委員","kind":"質問","question":"ネットショップとか、いろいろ使わせていただいたりするんですけれども、そういう認証にいちいちカードリーダーを通す必要はないですけれども、こういう個人情報の漏えいというので、それ以上に漏えいしにくくするためにＩＣカードリーダーを使うという理解でよろしいんでしょうか。","respondent":"冨田戸籍住民課長","answer":"カードリーダーを使って電子署名を読み込みをする。民間では、既に電子署名法によって、インターネットの取引きも実施されていると思いますけれども、それはそれで、こちらのほうは自治体が認証するということで、それもリアルタイムで最新の情報で交信をかけていきます。","voiceIndex":59,"id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"そういう部分に対しての対策も、もちろん並行してとられていくわけですが、こういうネットがもっと普通のことになって発展していったときにも、やっぱり、いわゆるネット弱者というんですか、社会的弱者じゃないけれども、そういう慣れない部分をきちんと尊重していくというんですか、そういう対策をやっぱりとられていかないといけないんじゃないかなと思いますので、その点についての考え方と。","respondent":"冨田戸籍住民課長","answer":"品川区で行う事務ということでは、先ほど申し上げたんですけれども、都区市町村電子自治体共同運営協議会で、今、開発中です。すべての事務をすべて受けるということがいいかどうか、そのあたりを含めて、様式も含めて、今、検討中です。","voiceIndex":61,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"弱者対策もきちんととっていくというお話だし、最初、品川区の部分も住民票から始まるという話なんですけれども、どういう事務が適切なのか、不適切なのかという判断は、一つ一つ共同で開発の中でやるのか、あるいは品川区独自の対策チームの中でやるのか、その辺はどういうふうになるんでしょうか。","respondent":"冨田戸籍住民課長","answer":"税務署の関係、例えば所得税の申告なんかは、申告書は電子で受けるけれども、添付書類が必要なものは別便で郵送するというような方法は、一応考えなきゃいけないですので、それに準じた方式をとれば、すべての機能は可能にはなると思うんですけれども、ただ。","voiceIndex":63,"id":"exchange-021"},{"speaker":"南委員","kind":"意見","question":"保育園への申請だとか、そういう類の事務については、単純に申し込み書を出せばいいというものでは済まないと思うんですよ。その辺をどういうふうに考えているかというのを、ちょっと聞きたかったんです。","respondent":"冨田戸籍住民課長","answer":"あくまでも、２４時間、いつでも、どこでも行政手続がとれる、それが一応の目標です。だからといって、対面の窓口業務を一切やめるとかというところまでは考えていないところです。","voiceIndex":65,"id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"そのときに、さっき言ったような角度で、ちょっと心配な部分が出てくると思うので、利用者の私たちの側から見たときに、そういうところどういうふうに担保したらいいのかと、ちょっと思ったので質問したんです。当面の対応なので、それはそれとして聞いておくということで、また必要なときに伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-023"},{"speaker":"三村委員","kind":"質問","question":"電子証明書が導入されることによって、具体的にどういった形で利用者側にとって便利になるか、トータルでイメージがなかなかつかめないんです。ちょっと難しい漠然とした質問になってしまって申しわけないんですけれども、利用者側にとってどういったメリットが考えられるのか、どういうふうにイメージしていくのか教えていただければと思います。","respondent":"冨田戸籍住民課長","answer":"これからは電子社会ですので、電子証明書というものを利用していくと思うんですけれども、民間で行われているのは１年に１万円とか、２年で３万円とか、非常に高額です。今回の公的個人認証サービスでは５００円を予定しております。","voiceIndex":68,"id":"exchange-024"},{"speaker":"三村委員","kind":"質問","question":"区役所に申請書類や何かを取りに行ったりするのは、結婚ですとか、引っ越しですとかというときに、ものすごく手間がかかるという印象があるんですけれども、そういったときに、利用者側にとって、電子証明書が導入されることによって、手続が楽になったりとか、そういうことも考えられるんでしょうか。","respondent":"冨田戸籍住民課長","answer":"説明が不十分で申しわけありません。行政機関のホームページに、各種申請書が載っていますので、それを引っ張ってきて記入するということになります。役所に出向かなくてもご自宅でできるようになります。","voiceIndex":70,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"中央環状線の関係ですが、１２月に説明会がありましたよね。あそこでどんな意見が出ていたのかということ。それから、品川区長としての意見を提出する時期が、この間の質疑では、１月２７日ごろとかと言われていたように記憶しているんですけれども、どんな内容で書いておられるのかということを、もし教えていただければと思います。その３点です。","respondent":"金井環境課長","answer":"住民説明会が昨年１２月に行われましたけれども、その資料が、まだ私どものほうに届いておりませんので、情報としてまだ把握しておりません。区長の意見につきましては、今、私どものほうで検討中ですので、これから文書を作成する予定になってあります。","voiceIndex":83,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"説明会の資料がまだだということですが、時期的にも、お正月を挟んでのことですから、わからなくもないんですが、区市町村長の意見ということで、そこを確認したいんですけれども、１月２７日までであれば、そんなに時間的な余裕はないので、説明会は都市計画局が承知すればいい話ですけれども、そこで出ている意見も、品川区のエリアでやっている部分ですから。","respondent":"金井環境課長","answer":"その後、説明会でどう説明されたのか、ちょっとまだ、今、要約したものがあるみたいなことは聞いておるんですが、その辺も踏まえまして、そうしなくてもいいものが何か研究されているのか、その辺はわかりませんが、いずれにしても。","voiceIndex":85,"id":"exchange-027"},{"speaker":"三村委員","kind":"質問","question":"中央環状品川線の部分に、いろいろご意見なんかが、私どものところに来たりするんですけれども、やっぱり五反田周辺の方の大気の状況、何人かからも出ていますけれども、大気の状況が悪化することについて、かなり神経質になられている方がいらっしゃるんです。五反田周辺で、ぜんそくですとか、そういった状況を持っている方というのが、やはりほかの地区に比べて多いというのは確かなんですか。","respondent":"金井環境課長","answer":"今、大気の悪化みたいなお話がございましたけれども、この環境影響評価にもありますけれども、悪化はしないという評価になっております。それから、先ほどちょっと説明しましたが、ＣＮＧスタンドですとか、自動車の排出ガスの規制が厳しくなります。","voiceIndex":87,"id":"exchange-028"},{"speaker":"三村委員","kind":"意見","question":"前回いただいたデータなんかを見ても、悪化はしない、大丈夫だみたいな表現はあるんですけれども、実際の数値データや何かがなかなか一緒についてなかったりするので、できれば細かいデータ等、数値等も、もし分析ができましたら、ぜひお示しいただければと思いますので、意見を述べします。","respondent":"金井環境課長","answer":"ここにはデータが全部入っております、データ集もあります。もしよろしければ、閲覧期間は終わりましたけれども、お貸しすること、たくさんあればお渡しすることもできますし、言っていただければ、後でも準備させていただきたいと思います。","voiceIndex":89,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2380#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":38962,"voices":92}},{"id":"h16-20040120-7","meetingId":"h16-cm01","date":"2004年1月20日","dateIso":"2004-01-20","committee":"厚生委員会","time":"午後１時０５分～午後３時２８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、次のすまいるスクール説明会の実施報告についてなんですが、質疑応答が３点についてと、ここに書かれているだけの報告だったんですけれども、かなりいろんな質問が出されていたと思うんですけれども、具体的にどんな要望があったのか、そしてそれに対してどういうふうに答えているのか、また、要望に対して、どういうふうに改善されているのか、それとまた。","respondent":"辻田児童課長","answer":"これはまだ全校実施していないので、区内の区立小学校に通っているお子さん等もまだすまいるスクールに通えないという状況がある。そういう中では、全校実施できるようになった段階できちっと対応していくというような形で質問にお答えしております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとあと、説明会のほうなんですけども、今ずらずらと説明会の中での応答みたいなところで答弁をいただきましたけれども、これはどういうふうな質問があって、それに対してどういうふうに改善されたか、今までと違うように改善されたというふうなところもあると思うんですけれども、そこら辺のところだとか、それからあと、今後検討していくというふうな部分もあるんじゃないかと思うんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、その説明会の中でも、またこういう説明会を開いてほしいという要望もたくさん出されていたと思うんですけど、それに対しても、また２月か３月あたりに持っていくというふうなことも答弁されているというふうなことも聞いているんですけれども、そこら辺の説明会、親に対してどう返していくのかというあたりもひとつお聞かせいただきたいのと、それから差し迫った問題として。","respondent":"辻田児童課長","answer":"一般的に私どものほう、児童課と指導課が一緒になってしていく説明につきましては、新たな事態を迎え、例えば来年度、またこういう形の処理をしていかなければならないわけですけど、その辺に対応するためにも説明会を開いていくということは考えられますけど、今。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須藤委員","kind":"提案","question":"ちょっと気になってきたのは、質疑応答で、さっきから改善する云々とかという表現があるんだけども、すまいるスクール、我々から提案して、第二延山でスタートをさせて、非常にいい形ができてきているので、大きく開いていこうという形だろうと思うんですが、ここで書いてくる事業内容、運営体制、児童の安全管理という形は。","respondent":"辻田児童課長","answer":"私どものほうとしては、基本的にすまいるスクールと学童保育クラブは違うものだというぐあいに考えております。というのは、すまいるスクールにつきましては、よく言われる全児童対策ですけど、すべての子どもたちに対して、その健全育成を図るための事業ということです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須藤委員","kind":"質問・要望","question":"その辺のところが区民の方々にはいろいろ難しさがあると思うんですね。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"私の地域なものですから、学童保育クラブに入れてほしいという要望も何件かあって、実際に児童課に行った場合、４９名以上入れないと言って、実際に学童保育クラブを必要とするお子さんが学童保育クラブに入れなかったケースがあるわけですよ。そういった面で、私は４０名定員で４９名がいっぱいと聞いていたところに対して、平成１６年度は６０名入れていく。地域に対してどうなのかということ。","respondent":"辻田児童課長","answer":"いわゆるこの障害を持っているお子さん１人のために、要するに平塚学童保育クラブを閉鎖しないというようなことではない。いわゆる定数から外れておりますので、いろんな形での対応をしながら、そのお子さんが困らないような形でケアをきちっとしてまいります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"飯沼副委員長","kind":"質問","question":"すみません。審査がどうなるのかというのが、そこが一番重要な質問なんです。","respondent":"辻田児童課長","answer":"審査というのは、今年の延長です。今年のこの延長、このお子さんを延長するということの審査ですか。とすれば、このお子さんにつきましては、たしか審査は終わっております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問","question":"現在も聞きたかったんですけれども、今後すまいるスクールに移行していくに当たっては、今のノウハウを踏まえている児童課がどう教育委員会のほうに送るのかというところがあると思うので、ちょっと今後のことも含めてお伺いしたんですが。","respondent":"辻田児童課長","answer":"そういう中で、人をどういう形で配置していくか、また、このお子さんをほんとうにお預かりできるのかどうか、その辺の審査はあると思いますけど、その部分とそれから人の配置、その辺が中心になってくると思いますけど、現在その辺の仕組みづくりについて。","voiceIndex":19,"id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"それが１点目で、あと２点目の説明会のことなんですけれども、お母さんの感想の中に、教育委員会の指導課のところと児童課の課長の答弁とすごく一致しないというんですかね、初めての合同の説明会だったんですけども、ニュアンスが違うのではないかという受けとめがあったんです。だから、なぜ合同でしたのかというのは、そこを一致してほしいがためのやっぱり親の声だったと思うんです。","respondent":"辻田児童課長","answer":"いろんな形のものが出ている中で、紙にしてくれという、まとめをひとつ出してくれです。これは説明会の資料等の中で、教育委員会のほうで配った資料の中では、すまいるスクールの平成１６年度の実施内容予定という形のものが一つきちっとした形で出ております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"意見","question":"一番ちょっと聞きたかった児童福祉法に明記されている留守家庭の児童の健全育成事業のところを、どこが責任を持って、どういう形で、多分連携をしていくんでしょうけれども、そこはどこが責任を負うのか。","respondent":"辻田児童課長","answer":"今、過渡期ですので、学童保育クラブは残っております。そういう意味では、放課後児童健全育成事業は指導課とそれから児童課がそれぞれ担っているです。将来は指導課のほうで、この部分については責任を持って担っていくです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問","question":"よその自治体を見ると、一緒にやっているところ、例えば教育委員会と児童課と両方で管轄していくようなところが結構多いんですよね。品川区の場合は、将来的にはといったら、教育委員会で児童福祉法に係わる部分を担っていくということになるんでしょうか。例えば法的なものの指導体制とか、予算とか、そういうことになるんでしょうか。","respondent":"辻田児童課長","answer":"先ほど外部的と申しましたけど、国とか都との関係で、必要な予算獲得等につきまして、当然私どものほうで担っていく、そういうことはあるです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問","question":"幼保一元化のところも福祉のほうと教育のほうと一体化をこれからやっていくこともいろいろ多いと思うんですけれども、例えば次世代の育成支援の制度とか、こういうのが来たときに、これを教育委員会で受けたりとかいうことがあるんでしょうか。","respondent":"辻田児童課長、小沼福祉事業部長","answer":"そういう中で、私どものほうとしては、この辺につきましては、教育委員会で十分福祉部分も担っていけるというぐあいに考えております。ただ、品川区としましては、今児童課長のほうからご答弁申し上げましたように、移行した段階での第一義的に実施するのは教育委員会の事業という形になりますので、それはその時点での責任というか、行政上の責任ですけれども。","voiceIndex":28,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"おやつがない以外は今の学童保育クラブと変わらないということでの答弁だったので確認をさせていただきたいんですけど、障害児等の子どもさんに対しての職員の配置というところでは、今までの学童保育クラブと同じ対応がされるということで確認をさせていただいていいでしょうか。","respondent":"辻田児童課長","answer":"今と今の学童保育クラブで実施している体制と同じになるかどうかというのは、私どものほう、まだちょっとわかりませんけど、困らない体制をつくるということで聞いておりますので、私どものほうは十分安心しております。","voiceIndex":31,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それともう一つなんですけど、父母の方々からすごいたくさん不安の声として出されていたのが、川崎市のわくわくプラザの事故、２階の窓から落ちて意識不明になったという、そういうふうなことが品川区でも起こるんじゃないかという不安の声がすごくたくさん出されているんですけれども、それに対しては。","respondent":"辻田児童課長","answer":"そこについての手すりがついているわけですけど、それだけで十分であろうかどうかというようなことも含めて、十分すまいるスクールの中では検討されている。","voiceIndex":33,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、川崎市の職員から出ている要望の強いところで、やはり専任職員の複数配置というところが出ているということで聞いていますので、この品川区でも、それは専任職員の複数配置というところでは、ずっと強い、最低ここにはしてほしいという要望が出されていますので、ぜひこれはご検討いただいて、複数配置ということで、これはすまいるスクールのほうになるんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとあと、４０代からの健康塾というところでは、健康に対しての関心はすごく高いですので、希望もたくさんあるんじゃないかなというふうに思うんですけども、この１０月１日の申し込みについては締め切られていると思うんですけど、どれぐらい申し込みがあったのか教えていただきたいのと、それと、これはこういうふうなコースでやるわけですけど。","respondent":"田中健康課長","answer":"それで、広報等いろいろ手は打ってはいるんですが、まだまだやはり４０代、５０代の方、内容的に言いますと、やはり女性が８０％を超える数字というのは、勤務時間等の関係もあるのかなというふうに想像してございまして。","voiceIndex":40,"id":"exchange-016"},{"speaker":"三上委員","kind":"質問・要望","question":"できないでしょう。いろんな方に協力していただいて、意見を伺っているのかわかりませんけれども、そういう意見が出されて、それが生かされるような、１人の人の意見でも吸い上げた一つのコースをつくるとかということを検討していただくということが大事なことだと思うんですけども、そういうような意見というのは、区民の皆さんは出されないんでしょうか、どうなんでしょうか。","respondent":"田中健康課長","answer":"ちょっと今のところ、まだ４教室のすべてが定員に満たっておらないんですが、たまたま現在木曜日、それから水曜日、品川と荏原でやっておるコースが両方とも実は参加が多いといいますか、定員に近い状況でごさいますので、ちょっとこの原因をもう一回調べながら。","voiceIndex":42,"id":"exchange-017"},{"speaker":"三上委員","kind":"質問・要望","question":"もう少し広い場所もあったり、いろいろあってもいいなと思っていた人間ですから。だけど、それにしても、狭い中にあって、どうするかというと、そういう健康センターのような何かネオンなんていうところまでいかなくても、やっぱりああこういうところにあるんだなと皆さんが通りかかったときに気がつくような、そういったところからの宣伝も大いにしていただきたいなとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-018"},{"speaker":"須藤委員","kind":"質問・要望","question":"健康という課があって係まであるくらいなんだけども、健康ということ自体がどういうところから来ているというのが、わかれば教えていただきたいと思います。","respondent":"田中健康課長","answer":"ただ、健康という言葉もご存じのとおり、心の健康ですとか、いろんなファクターがございまして、それぞれにまずご自分で楽しく生きられるためのご自分との調整機能かなというふうに私自身は思ってありますけども。","voiceIndex":45,"id":"exchange-019"},{"speaker":"須藤委員","kind":"質問","question":"だから、それをちゃんと承知しておかないと、見る人が見て、健康ということの表示をされちゃうと、心身ともに健康なと、健康というのは、体も心もということを全部言っているわけなんですから、ここで心身ともに健康づくりとか、健康な体づくりというような表現をしかるべき人たちが見ると、ほんとうに知っていて健康をということを考えてやっているんだろうかということにまで入ってこようかと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"大西委員","kind":"質問","question":"不動産業者からいうと、これをもし区のほうから生活保護者の方々に生活保護費をお渡しになられているんであれば、住宅費を含めたですね、そのもの自体を区のほうで責任を持ってまずお支払いいただければ、これほど安全なお客さんはいないということを不動産業者の方から言われて、ああ不動産業者の方も困らない、借り手も困らない、大家も困らないということで、私はこれはスムーズな住宅提供に関しては。","respondent":"黒田生活福祉課長","answer":"その辺のところがご本人と大家との関係がスムーズであれば、家賃の滞りはなくなるんだと考えています。今もってトラブルは減らすようには努力していますが、ときどき出ていることは事実です。","voiceIndex":52,"id":"exchange-021"},{"speaker":"大沢委員","kind":"確認","question":"別紙のほうの、よく生活保護を受けていらっしゃる方、これは民生委員が非常にご苦労されているわけなんですけれども、そこでやはり見解の相違で保安上危険、または保健衛生上危険と、非常に抽象的な表現になっておりますけれども、そこらあたりの具体的な枠組みというのは想定をされていらっしゃると思うんですが、そこのところの確認を伺いたいのが１点と。","respondent":"蓼沼高齢事業課長","answer":"悪徳な業者に対しての対応ですけれども、これにつきましては、やはり宅建支部のほうと連携を密にして、今回特にこういう高齢者・障害者の住宅に対する理解のある会員を募って、そういう協力店の登録制度を設けようということで実施もいたしますので。","voiceIndex":54,"id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"その２点、申請するほうとされる側との見解の相違が往々にして出るのがあると思いますが、この中で、具体的な枠組みみたいなのがきちんと区のほうでは決められているのでしょうか、ちょっとお伺いしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"別紙のほうの2)の住宅の保安衛生上等々の困窮度の扱いですけれども、これにつきましては、高齢者住宅、空き家入居のほうで、これと同じような条件を設定していまして、調書を受け付けのときに聴取してございまして、そこでいろいろな住居の状況について。","voiceIndex":56,"id":"exchange-023"},{"speaker":"大沢委員","kind":"確認","question":"今のこと、一応現認をされて、確認をされているということで対処されているということで理解をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この制度を使って大変助かったという声もご相談があってお聞きしているんですけれども、このときに、今回協力店を指定して、協力店名簿を品川区に提供するというふうになっているんですけれども、この協力店というのは、どれくらいあるのかをひとつ教えていただきたいのと、それとあと、その方は区のほうに相談に行ってあっ旋をしてもらったんですけど、なかなか物件がなくて、結局自分が不動産屋で探して。","respondent":"蓼沼高齢事業課長","answer":"会員数が全部で約４５０店あるということで、お話しした中で、見込みといたしましては、その半分ぐらいの２００店強の会員が集まるといいな、集まるのではないかなというようなことを宅建支部のほうではお話をしておりました。","voiceIndex":59,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとあと、この制度そのものが区民にほんとうに知られていないというふうに思うんですけど、ここのところでは、区民にＰＲを行うというふうになっているんですけど、これからどういうふうにＰＲをしていこうとしているのか、そのことを一つお聞かせいただきたいのと、またこの制度を使った方が年間どれぐらいあるのか、そのことについても教えてください。","respondent":"蓼沼高齢事業課長","answer":"今までも宅建支部、大家、それから不動産屋につきましては、宅建支部を通して入居者に関する支援ということでＰＲ用のチラシをつくりまして、普及啓発に努めていたところですけれども、今後さらに効果的なＰＲについて検討して、ホームページ等も活用して。","voiceIndex":61,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ＰＲについてなんですが、そういう関係しているところに置くというだけでなく、こういう制度そのものがあるということを区報にもぜひ載せていただきたいと思うんですが、それはどうでしょうかということと、それから、今年間の件数が平成１４年度では３７件の申請に対して１４件ということで、実際に受けられたのがかなり少ないんですけど。","respondent":"蓼沼高齢事業課長","answer":"申請があって決定を受けられない方ですけども、これにつきましては、個々具体的に追いかけてはおりませんけれども、やはり希望等、具体的には家賃の額ですとか間取りとかで、やはり見合う物件がないという方が多うあります。","voiceIndex":63,"id":"exchange-027"},{"speaker":"三上委員","kind":"質問","question":"今伺ったように、申請数とこれが現実、あっ旋事業に対して１００％に近い、限りなく１００％という言い方まではしませんけれども、そういった数字、高い数字のほうにこれがつながっていくということじゃないと、なかなかこのあっ旋事業というのは、やっぱり私は成功しているというふうには思えない部分があるんです。そこらあたりについての理事者側のお考えを伺っておきたいなと思います。","respondent":"蓼沼高齢事業課長","answer":"そういうことで、区内のそういういわば町場にありますような賃貸住宅の空き家でまずニーズを吸収できないだろうかということで、今までも取り組んでまいりましたけれども、件数的には２けた行くか行かないかというようなところが過去数年の実績でございましたので。","voiceIndex":65,"id":"exchange-028"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"平成１４年度はゼロなんですけれども、この辺で平成１４年度、平成１５年度でどのくらい申請があったのか、なかったのか、その辺も含めて教えていただきたいのと、区立のところでの障害者住宅はまだまだ大変少なくて、住宅にお困りの障害者の方は多いんですけれども、民間のところで障害者に対応したというような住宅はどれぐらい把握されているのか、わかっていたらば教えていただきたいんですけれども。","respondent":"日下部障害者福祉課長","answer":"障害者の方のあっ旋の利用の状況ですけれども、平成１４年、それから１５年、今日に至るまで申請、それから実績ともにゼロです。ここ数年間の状況で申し上げますと、平成１１年には３件ほど利用がございました。平成１２年、１３年が１件ずつと、そういう状況です。","voiceIndex":67,"id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"いい制度なので、ぜひアピールをしていただいて、お困りの方がこういう手だてがあるんだなと利用されたり、申請にいらっしゃる方が多くあるようにぜひＰＲに力を入れていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-030"},{"speaker":"大西委員","kind":"提案","question":"今、委員長の提案により、品川区にお住まいの高齢者、今後ますます増えるということで、私は今ずっと議題の中にもございましたが、まず高齢者の住宅の問題、これをもっともっと高齢者が身近に、かつ容易に住みよい環境で過ごすことができるようにということを一つ考える必要性があるということと、もう一点が、先般、西五反田さくらハイツの比較的元気なお年寄りですね、介護認定を受けていない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それともう一つ、次世代育成支援対策推進法というのが通って、２００５年３月までに２００５年から２０１５年までの１０年間の計画を立てるということが義務づけられましたけれども、この法律についてや、それからあと品川区でどういうふうにして計画をつくっていくかというふうなところについて、ちょっと学んで、また検討したいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-032"},{"speaker":"三上委員","kind":"意見","question":"全く所管から外れちゃうというふうに言われるとあれなんですけど、品川駅のそばに食肉市場があるんですけど、食の安全的な部分だとかということを考えると、ああいう一番身近なところ、私なんか昔子どものころ、そばに食肉処理場というのがありましたけど、そういったところを視察したことというのは、東京のどんな規模で、どう行っているのかというのは、これは知らないのは私だけなのかわらないけども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-033"},{"speaker":"須藤委員","kind":"提案","question":"都合４回という委員会開催で、ある程度この会期中に一つの方向性をつくっていこうというようなお考えが委員長、全部でなくても構わない、次の委員会に引き続いてというような資料づくりにもなろうかというような考え方だろうと思うんですけども、今年度からスタートした未就学児の健全育成というか、そういうスタートを品川区では新たにしたことと、それから家庭あんしんセンターで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-034"},{"speaker":"若林委員","kind":"意見","question":"やっぱりその地域の仕組みづくりをぜひ一遍、そういうことであれば、考えてみたいと、目の前のおばあちゃまをどういうふうに私たちがケアできるのか、またこの障害を持った方をどのように、あの人とあの人の力を借りながらというような光を当てていきたいなというふうに漠然かもしれませんけれども思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3068#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":39993,"voices":85}},{"id":"h16-20040120-8","meetingId":"h16-cm01","date":"2004年1月20日","dateIso":"2004-01-20","committee":"建設委員会","time":"午後１時０６分～午後２時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"続きまして、報告事項を聴取をいたします。 (1)の商店街架空線地中化事業の路線の決定","agenda":"続きまして、報告事項を聴取をいたします。 (1)の商店街架空線地中化事業の路線の決定","exchanges":[{"speaker":"山村委員","kind":"質問","question":"戸越銀座商店街のほうで質問があるんですが、戸越銀座商店街は相互通行だと思うんですが、電線の地中化後も相互通行なのかということと、そうだとは思いますが、あと工事中ですね、相互通行ができるような状態なのか、それとも一方通行に直すとか、そこら辺をどういうふうにお考えなのかというのはありますか。","respondent":"岩田管理工事課長","answer":"これが入れ終わって、線をつないで、全部終わりますと、現在あります電柱や架空線の撤去の工事が入ってまいります。これらがすべて終わって、やっと路面の化粧工事ということになりまして、工事が全部終了するという予定になっております。","voiceIndex":7,"id":"exchange-001"},{"speaker":"原委員","kind":"質問・要望","question":"この地中化事業の大きな流れをちょっと教えてほしいんですが、今、希望商店街と候補路線で１３ですか、そのうちの２路線について候補路線、事業スケジュールが出てきていますけれども、そのほかの希望商店街については、どういうスケジュールでそれを具体化しようかなと、手を挙げた商店街としては１１あるんですよね。","respondent":"岩田管理工事課長","answer":"先ほどちょっと申し上げましたが、様子見の商店街がほとんどでございまして、実際に地元負担がどれぐらいになるのかということと、工事の規模が、話では説明をさせてもらっていますけれども。","voiceIndex":9,"id":"exchange-002"},{"speaker":"原委員","kind":"質問","question":"その辺、多分、この電線の地中化というのは、いろいろな形で今後広げていかなきゃいけない事業ですよね。そうすると、その辺のスケジュールがわかるかなという気がするんですけれども、どうでしょうか。","respondent":"岩田管理工事課長","answer":"ただ、委員の地元の滝王子通りにつきましては、これは実施計画の中で、商店街の地中化とは少し切り離しまして、広域避難場所への避難道路の確保という目的で、こういったきれいな形での地中化は考えておりませんけれども。","voiceIndex":11,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと今事業費のところでお聞きをしたいんですけれども、これは地元負担というところというのは、総事業費に対して何割とか何％とか、それはもう前提として決まっているんだと思いますけれども、これを見ていますと、例えばこの北品川の商店街なんかですと、実際には商店というよりも、これはご商売をやめられて、それぞれ住まいとして利用されている方もすごく多いかと思うんですけれども、商店街。","respondent":"岩田管理工事課長","answer":"少し説明が漏れまして申しわけございません。今、地上を、空中を張っている電線を地下に入れて、電柱を撤去をして、路面を復旧するというところまでは、これはすべて行政と電線管理者の負担で行います。","voiceIndex":13,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"今、菊地委員のおっしゃったとおり、あそこは旧東海道のまちづくりとして、そのまちづくり協議会だけではなくて、残していくような街並みづくりというような、そういう視点が品川区にあるのかどうなのかということと、北品川のほうで行われていた候補地に挙がるまでの説明が、どういう形で、どういうぐらいの人数が集められて行われたのかということと、もう一つ、そのときに。","respondent":"岩田管理工事課長","answer":"それで、景観形成の話は、区としても、これからそういう景観のあり方というものを今検討をしているところでありますけれども、現在の街並みの中で、いわゆる旧東海道をイメージさせるようなつくりというのは、いわゆる裸木造の古いお宅が何軒か。","voiceIndex":16,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"そうすると、今は役員の方とか、それから近隣の方しかご存じないかと思うんですけれども、その先の周りの方たちには、どういうふうに知らせていきながら、その周知の方法とか時期とか、そういうことは、どのようなスケジュールになっているんでしょうか。","respondent":"岩田管理工事課長","answer":"こういった電線管理者との財政上の協定、協議をこれから始めていくわけですけれども、それらの幾つかの山を乗り越えて、初めて平成１７年度から着手できるですので、ある程度方向性が決まって、いざ行けるよというふうになってから。","voiceIndex":18,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"じゃあ、地元の商店街も路面も補修していこうかとか、いろいろそういう動きというのは、やはりまた出てくるかと思うんですけれども、できれば区としては、ほんとうに緊急性、またその利便性をもっと重視した方向で、地中化というのを進めていく方向にあったほうがいいんじゃないかと思うんですけれども、その辺いかがなものでしょうか。","respondent":"岩田管理工事課長","answer":"したがって、熱意と、皆さん方に私どもの心配をすべて説明した中で、それでもやろうというふうに言ってこられた商店街をまず調査をかけて、一緒にやっていきましょうというのが、この２商店街、このようにご理解をお願いしたいと思います。","voiceIndex":20,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほどちょっと菊地委員からもご指摘があったんですけれども、ほんとうに北品川のほうは広い幅員があるということで、我々が見ても、そんなに電線や電柱が邪魔になるようには見えないんですけれども、そのような選択で、今回区の方針ということなんですけれども、今後、できましたら区の予算も使うということなので、ちょっとずれちゃうかもしれないんですけれども、商店街活性化。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-008"},{"speaker":"藤田委員","kind":"質問","question":"そうしますと、このスケジュールの中で、平成１７年度以降、工事を着手をしていくということで、一方が１,３５０ｍと、それから１,１８０ｍ。やっぱり商店街としても、協力はするけれども、何年も工事をやられたんじゃ、もうたまったものではないというのがありますので、めどとしては、我々、まち場で聞かれるわけですけれども、大体どれぐらいかかるものなんでしょうかということ。","respondent":"岩田管理工事課長","answer":"ほんとうはこれは非常にお金もかかるし、技術的にもちょっと難しい問題を幾つか抱えておるので、歩道などがあってスペースがあれば、従来型の形で地中化したほうがはるかにいいんです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望なんですけれども、ぜひ、それが地元商店街の活性化でなくて衰退化にならないように、できるだけ配慮していただいて、お客さんが自由に、できるだけお店に入るのもあまりご不便をかけないように、ご配慮だけはくれぐれもよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"}]},{"id":"topic-02","title":"２番目の区部における都市計画道路の整備方針（案）","agenda":"２番目の区部における都市計画道路の整備方針（案）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"防災上の構造ですか、そういうことをかんがみますと、この１番、放射２号線と放射１８号線ですか、１番に対しては、さほど交通量は多くないと私は思うんですけれども、２番に対しても、交通量ならびに防災上の観点から優先的にどうなのかなというふうな考えを受けるんですけれども、そこをちょっと、優先順位ですか、もう都のほうから情報が入っていましたら、お聞かせください。","respondent":"藤田都市計画課長","answer":"放射１８号線のほうですけれども、放射１８号線のほうにつきましても、一つはやはり防災上の重要な道路になっているということと、あともう一つは、交通のネットワークの観点からも放射線というようなことで位置づけられている道路で。","voiceIndex":30,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"それとあともう１点、放射１８号線もそうなんですけれども、現在、道路幅も結構あると思うんですけれども、それでもやはり、さらに重点整備をしていくということなんでしょうか。ちょっとその２点。","respondent":"藤田都市計画課長","answer":"そちらの道路整備を進めていくべきというのが、私どもの交通の観点、そちらの表についても防災の観点ということで、ポイントが加算されていて、必要な道路だということになっているものです。","voiceIndex":32,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"１点なんですけれども、これはこういう優先整備路線や何かは、都のほうから区のほうにどこか優先整備する、どこかありますかというような評価基準というんですか、こちらのほうで、区のほうで逆に打診して、ここはちょっと防災上、または交通網、交通上ちょっと最優先にしたい、区の要望で、逆に都がそれを審査して決定するというような、そういう段取りなんでしょうか。そこだけ。","respondent":"藤田都市計画課長","answer":"今回、お話の中では、区としてこういう路線をやってほしいとか、そういったようなことでのやりとりは当然やってありますけれども、それが２３区皆さん集まって、皆さん言いたいことを言ってという形になると、やはりきちんとした評価ができないということで。","voiceIndex":34,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問・要望","question":"1)の放射２号線と3)の補助２６号線が、ちょうど接しているところで、全体を見て、都市軸の構想というんですか、循環、流れがよくなるような全体を見て道路を計画されているんだと思うんですが、場所場所、パーツパーツで考えていく方針になるのか、全体を見ての方針なのか、その辺をちょっと教えていただきたい。","respondent":"藤田都市計画課長","answer":"中央環状品川線の絡みですけれども、今回、五反田出入り口の関係につきましては、こちらの道路からのアクセスと放射２号線からのアクセスといったようなことも考えながら、検討を進めているものですので、そういった観点では、大きなネットワークといったものをとらえながら。","voiceIndex":36,"id":"exchange-014"},{"speaker":"本多委員","kind":"質問","question":"それと、もう一つなんですが、この案に出されている六つの計画路線の中で、五つは道路の拡幅が主だと思うんですが、６番目の交通広場、これだけが面的な計画ですので、５,７４０m2ですか、これはちょうど明電舎の再開発の絡みがあるんだと思うんですが、この辺の計画とか交渉していく進め方というのは、ほかの５路線と何か違いがあるんですか。","respondent":"藤田都市計画課長","answer":"先ほどのちょっと説明不足で申しわけございません、３ページの(2)の4)のところですけれども、「具体的な整備イメージ」というところの中の4)に「沿道の民間開発等と一体的にみちづくりに取り組んでいく路線」ということで。","voiceIndex":38,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっと放射２号線についてお聞きしたいんですけれども、この路線は、相当数の権利者の方がいらっしゃるんだと思いますけれども、実際にどれぐらいの権利者がいらっしゃるのか、ちょっと教えていただきたいのと、それから前回の委員会でしたか、本多委員のほうから２９号線の話が出ていましたけれども、実際に権利者の皆さんとの関係で言えば、地元の皆さんの放射２号線に関してのご意見というか。","respondent":"藤田都市計画課長","answer":"放射２号線ですけれども、今回の計画の中では放射線ということもございまして、東京都の施工の路線ということになってあります。今回から都施工になったというわけではないんですけれども、ずっとそういうような形になっている路線です。","voiceIndex":40,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"やっぱり実際にそこで何らかの被害を受けるというとおかしいですけれども、実際被害を受ける方も、思いとしてはいらっしゃるんだと思いますけれども、その辺は区のほうも、こうして東京都の事業とはいえ、決定をしてきているわけですから、実際に権利者がどれぐらいいて、どんな意見を持っていらっしゃるのかということは、区としても私はつかむべき話ではないかなというふうに思うんですけれども。","respondent":"藤田都市計画課長、浜脇住環境整備課長","answer":"事業といたしましては、これから具体的な整備を進めていく中で、事業認可を取得するですとか具体的な動きが出てくる段階で、またさまざまな地元調整等も出てくるのかなというふうに考えてあります。ですから、１０年ぐらい前の当時なんですけれども、当時の方は、まちづくりをする際には、やはり放射２号線のあり方の部分については関心があった、こういうふうに言われたことがあります。","voiceIndex":42,"id":"exchange-017"},{"speaker":"藤田委員","kind":"質問","question":"ほんとうに素朴な質問なんですけれども、都の施工と区の施工と分けた理由というのは、どういう理由があるのかということなんです。","respondent":"藤田都市計画課長","answer":"これまで当然道路はさまざまな国道、都道、区で管理している区道という形ですけれども、そこの役割分担の中で、１６ｍ以上の道路で複数区にまたがる道路、これについては東京都が施工していく道路というような大きな仕切りがあります。","voiceIndex":45,"id":"exchange-018"},{"speaker":"藤田委員","kind":"質問","question":"これは品川区でやりましょうというぐらいの意気込みみたいなものがあってもいいんじゃないかなというようなところがあると思って素朴な質問をしてみたんですけれども、そういう仕切りがあるというのであれば、これはもう尊重していかなきゃいけないんじゃないかと思うんですけれども、今後。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-019"},{"speaker":"原委員","kind":"質問・要望","question":"私もちょっと個人的なことでお伺いしたいんですが、前にもちょっといろいろ伺ってはいるんですけれども、この1)から6)ですよね。今、5)、6)については区施工でやると。したがって、一つ路線を拡幅させていこうよということになったりとか、あるいは1)なんかの場合は、どういう要望が出てきて、これも拡幅なんでしょうか、あるいはどういうふうに整備しようとしているのか。候補はどうなんですか。","respondent":"藤田都市計画課長","answer":"2)番についても、都市計画道路といたしましては４２ｍあるいは１８ｍの道路ですので、そういった部分の中で適切な配置をしながら、具体的な検討をこれから進めていくところです。","voiceIndex":48,"id":"exchange-020"}]},{"id":"topic-03","title":"の違反建築物の指導経過","agenda":"の違反建築物の指導経過","exchanges":[{"speaker":"山村委員","kind":"質問","question":"違反建築物のことでちょっとご質問したいんですが、これはもう完全に建てられた後でも通報があった場合は、こういうふうな処置をとるのかということと、今までに行政代執行ですか、されたことがおありなのかどうか。","respondent":"片田建築課長","answer":"一応国土交通省のほうでいろいろ調べた中では、最近では、平成１３年に仙台市、これが一応代執行をやっているといったような状況です。２３区の中につきましては、平成６年でしょうか、これは中野区、これが共同住宅で実施した。","voiceIndex":54,"id":"exchange-021"},{"speaker":"山村委員","kind":"質問","question":"違反建築なんですが、建てた後に屋上にまた物を建てるという事例は結構あると思うんですが、そういうのは、私が１件聞いたことがあるぐらいですから、結構品川区全部でいえばあると思うんですけれども、調査というか、そういうことはなされているんですか。","respondent":"片田建築課長","answer":"ただ、それについては、逆に言うと構造を強化してもらいたいとか、そういう個別個別の案件に沿った形での行政指導をして、なおかつ相手方についても区の行政指導に十分反省して、合意していただけるといった中で、そういった対応をやっているといったような状況です。","voiceIndex":56,"id":"exchange-022"},{"speaker":"山村委員","kind":"質問","question":"それで、違反建築の場合というか、やはり責任の所在というのは、建築主なんでしょうか。それとも工事を執行された会社のほうでしょうか。","respondent":"片田建築課長","answer":"いろいろその建物のできている状況、あるいは完成したものの所有権の問題、いろいろございまして、９条の１項で、工事停止命令の権限がありますけれども、その中では、建築主だけではなくて、工事をやっている際には工事施工者、あるいはそこにいらっしゃる建物の占有者等々。","voiceIndex":58,"id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"初歩的なことなんですけれども、最終的に命令をするということで、どこを目指しているんですか。","respondent":"片田建築課長","answer":"これは、やはり私どもの防災の問題として、もし仮に善意の入居者あるいは善意じゃなくても入居者が入って万一火災になったときに、多大なる生命の危険にも影響するだろうということで、ご本人が住むのであれば、やっぱり自分の責任かもしれませんけれども。","voiceIndex":60,"id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"撤去という命令をして、撤去をしなかったら、ずっとそのままいくわけですか。","respondent":"片田建築課長","answer":"その猶予の中で、いわゆる履行しなかったりとか、あるいは他の手法で履行を行うことがなかなか担保が難しいといった場合、やはり公益に反するといったような判断の中で、行政側がどういうふうにしてやるか、あるいは第三者機関のほうに執行を委任するといったような話があります。","voiceIndex":62,"id":"exchange-025"},{"speaker":"原委員","kind":"質問","question":"代執行なんですが、この警告を発して、どのくらいでやるんですか。品川区なんかの場合、代執行があったのかないのか調べていないので申しわけないんですけれども、どういう形でやるのか。それから、その費用を多分請求するんだと思うんですが、その辺のところをもう少し教えてください。","respondent":"片田建築課長","answer":"代執行のスケジュール的な話ですけれども、逆にちょっとはっきり言って、私どものほうも手探りの段階で、他区、他市の事例をいろいろ下敷きしながら、今検討していますけれども、先ほど事例として申し上げました仙台市なんですけれども、やはり既存建物のほうの上に。","voiceIndex":66,"id":"exchange-026"}]},{"id":"topic-04","title":"４番目の平成１６年２月都営住宅募集","agenda":"４番目の平成１６年２月都営住宅募集","exchanges":[{"speaker":"藤田委員","kind":"質問・要望","question":"この単身者用なんですけれども、我々よく要望として受けるんですけれども、東京都としては、今後単身者向けについての、こういう１,７００というと、かなり大きな募集になっているわけですけれども、これは、拡大していくという方向なのか。そういうまた逆のケースがあるとよく言われるんですけれども、これはどういうふうに我々は受け答えしていけばいいのか。","respondent":"田村住宅課長","answer":"ですから、障害とか生活保護を受けていれば別ですが、一般の方よりも５０歳以上の方ということで、通常単身者向けのは、もう募集で、最初からもうそこで世帯を持つ前提じゃありませんから、特にそこで世帯を持つということになると本来の入居資格がないわけですから。","voiceIndex":72,"id":"exchange-027"},{"speaker":"藤田委員","kind":"質問・要望","question":"これに限らず、区営でもあれだけ広いところになぜ１人でいるんだ、我々もそういうおしかりを場合があるんですよね。ですから、その辺、住み替え等を十分作動してもらって、都営じゃなくて、区営もやはり念頭に置いて、ぜひこれは考えてもらいたいというふうに思います。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3772#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":31412,"voices":87}},{"id":"h16-20040120-9","meetingId":"h16-cm01","date":"2004年1月20日","dateIso":"2004-01-20","committee":"文教委員会","time":"午後１時０６分～午後５時０６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"その対策をどうするかということが一つ。それから、今、学校の安全のことでいろいろ言われていますので、これだけ空間をつくって、メディアセンターもある、おそらく最新技術を使ってつくっていくんでしょうから、子どもの安全なりセキュリティ対策をどう盛り込んでいるかということを説明に入れていただければありがたいんですが、いかがでしょうか。その二つです。","respondent":"鷹倉庶務課長","answer":"ゾーニングを仕上げるというのがなかなか難しゅうありますけれども、このことは、今申し上げた形で、今後もう少し新しいセキュリティ対策ということがいろいろ言われてありますけれども、そういうことも踏まえながら、検討していきたいと考えています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"だから、今、課長が説明されたようなゾーニングをやるんであるならば、つくった後のコストについても対処していくことを考えるならば、建設費が増すことになっていくんでしょうけれども、そういうことを具体的に考えていくんでしょうかということを一つお願いしたい。そういうところまで考えて、安全対策をしているんでしょうかということを、もう一つお伺いしたいんです。二つです。","respondent":"鷹倉庶務課長","answer":"芝生広場の件です。実は、先ほどこれを踏まえた形で第１回目の検討をしたという話をしました。実は、これを実際にどういう形で使っていくのかという、使うという部分と、それから安全対策をどうするのかという話が必ず出てまいります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、今までのように、例えば校長先生が校門に立ってあいさつをするとか、それもやっていただきたいんですが、今の問題は、日中とか、不審者の侵入をキャッチをする、機械的なシステムを検討してくださいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"二、三、質問したいと思います。初めに、改築検討会の構成メンバーはどんな方がいるのかなということ。それから厨房のことなんですけれども、昨年の本会議の中で、学校改築に伴って学校給食の調理代行の方向が出されたんですけれども、この図面では厨房としか書いてないんで、見えない部分があるので、第二延山小学校では、調理代行の計画がどうなっているのか、この２点を、まず質問します。","respondent":"鷹倉庶務課長","answer":"改築検討会のメンバーですけれども、先ほど申し上げましたとおり、学校関係者、そして地域です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"構成メンバーの中で、学校関係者の方がいらっしゃると伺って、あと厨房の件も、新しい手法でとおっしゃったんですけれども、厨房に関しては、校舎の形をどうするかとか、校庭とか、そういう話とはまた別に、安全な給食、食糧費区分をどう進めていくか、また別の分野が出てくるとは思うんです。今後、新しい厨房の姿というのは、どのように検討されていくのか、その方向を少し伺いたい。","respondent":"鷹倉庶務課長","answer":"現在のところ、給食関係の方は入っていただいていないわけですけれども、ほかの学校の改築検討会の進め方の場合もそうですけれども、この改築検討会の進行状況に合わせて、それぞれの学校の内部でそれぞれ調整をしていただくというふうになります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"料理室の設計の基本の部分ができてくると思うので、ぜひ、示していただきたい。別の問題なんですけれども、解体、建築に伴って周辺住民にどのように説明しているのか。やっぱり工事に伴ういろいろな振動とかも出てくると思うので、現段階の周辺住民への工事説明会の現状を知らせていただければと思います。","respondent":"鷹倉庶務課長","answer":"工事説明会は、まだ当然先の話ですけれども、基本的な情報提供の仕方を、具体的にそういう話も出てありますし、この場合は、先ほど申し上げたとおり、いろいろな形で使われてありますので、いつ、どうなっていくのかという情報をできるだけ早く町会の代表者だけではなくて。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか質問をさせていただきたいと思います。基本設計委託プロポーザルの流れがあるんですけれども、この中で、選定するときの基準というのが何かあったのか。それから、今回、１件に決められたと思うんですが、その決め手はどうであったのかというところを、まずお聞きしたいと思います。","respondent":"鷹倉庶務課長","answer":"今回、大井小中一貫校につきましても、第二延山小学校につきましても、非常に困難な敷地ですので、そこにいかにきちっと配置し、配置されたことの利便があるかということが大きなポイントになってまいりますので、そういうことが厳しい駆け引きになってくるのかなと。","voiceIndex":17,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"限られたスペースの中にいろいろ要望を入れていくという形になると思いますので、希望は希望でたくさん入れ込みたい気持ちはあるかと思うんですが、ただ現実的な問題として、こういうふうに図面は出てきているんですけれども、ほんとうにこれが子どもたちの環境にとっていいものかどうかというのは、判断の仕方で、なかなか素人では難しいかなという部分がある。","respondent":"鷹倉庶務課長","answer":"先ほど、ベースにはプロポーザルの部分があるけれどもと申し上げましたが、その部分でございまして、ゾーニングという形で配置はこういう形で決まっているわけですけれども、先ほどの芝生の部分もそうですけれども、具体的にこういうふうにしてほしい、ああいうふうにしてほしい。","voiceIndex":19,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"それについては、また、後ほどちょっと要望等がありますので、これで終わりにしたいと思うんですが、あと大きく二つ確認したいことがあります。小学校の近くですから、ある程度の子どもたちの声は仕方ないと理解はしていただけるものとは思いますが、そういう部分がありますので、ここら辺にどういう影響が出てくるのか、ご存じのところがあれば教えていただきたいと思います。","respondent":"鷹倉庶務課長","answer":"どういう影響が出てくるだろうかということですけれども、実際に、今、私ども、荏原第五中学校、第二延山小学校という形でいろいろ説明をしていますけれども、なかなか難しい部分があります。具体的に申し上げますと、第二延山小学校は既存校舎という形で建物があるわけですね。","voiceIndex":21,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"小学校ですから担任制になっていますので、自分のクラスに常時いるという形ができるかと思うんですけれども、ある程度行き来ができるような環境づくりも、ぜひお願いしたいなと思います。そう考えると、むしろもったいないという部分もありますので、ほんとうに仮校舎が建てられる場所が、第二延山小学校の周りにはないという理解でよろしいんでしょうか。これで最後です。","respondent":"鷹倉庶務課長","answer":"したがいまして、建物的にも結構なスペースということと同時に、当然も校庭も考えていく。ということになりますと、大体、今あるスペースと同じようなところを借り求めていくということになります。そうしますと、果たして、この近隣にあるのかなと。","voiceIndex":23,"id":"exchange-010"},{"speaker":"本間委員","kind":"質問","question":"芝生広場、ルーフガーデンというところをどういうふうにとらえたらいいのか尋ねてみたいと思いますが、野外による目的広場的なものではないかと思います。詳細については、大体、体育館の上ですから、体育館ぐらいの広さを想定するわけですが、その辺のことについてお尋ねします。どのような時点で、どのようなものを採用したのかということをお尋ねしたいと思います。","respondent":"鷹倉庶務課長","answer":"熱エネルギーにつきましては、先ほど伊藤委員にお答えしたとおり、これから省エネ的なことを踏まえながら、どういう形で全体の熱検討をやっていくか、今後の課題ということでやらせていただきたいと考えています。","voiceIndex":25,"id":"exchange-011"},{"speaker":"本間委員","kind":"確認","question":"ちょっと今、同じような名前の大きな場所と小さな場所、メディアセンターというのがありまして、ちょっと聞き取りづらかったんですが、そのほかに図書とかおっしゃいましたね、図書館みたいな形のもので、今度は逆に、勉強したり、計算したりできるような部分だと確認していいのかどうかということです。","respondent":"鷹倉庶務課長","answer":"学校の希望も当然、天然芝ですけれども、どういう形で落ち着いていくかというのは、まだまだ検討していく必要があるのかなと考えているところです。","voiceIndex":27,"id":"exchange-012"},{"speaker":"本間委員","kind":"質問","question":"芝生広場のところ、絵と、下の文章を見たりすると、何か屋上緑化によると部分が、庁舎の屋上みたいな感じの部分で、自然芝みたいな形なのかと思ったものですから、その部分はこれからということですので、質問させていただきました。それから、ここには駐車場というのがあるんですけれども、駐輪場がその中に含まれているのか、どうかをお尋ねしたいと思います。","respondent":"鷹倉庶務課長","answer":"第１点目の、駐輪場の部分。今、具体的にこれだけの駐車場のスペースでいいのかという課題があります。敷地はなかなか難しい条件なわけですけれども、駐輪場を、もう少しどこかにスペースが必要なのかなという課題があります。","voiceIndex":29,"id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"あるいはないとすれば、今後、どういテンポといいますか、やろうとしているのか、ちょっと全体像をお尋ねしたいこと。それから、ちょっと私もこれを見てみますと、すまいるスクールの解体から新校舎に入るのが１９カ月目と、１年半。せっかくの機会だから、私は入れたほうがいいんじゃないかと思うんですが、そのことをお伺いいたします。","respondent":"鷹倉庶務課長","answer":"とは言っても、小学生の場合に、外に出て行くというのはなかなか難しい現実もありますので、一定規模内の中に、そういう施設があるという前提になってありますけれども、そういうことは努力してまいりたいと考えています。","voiceIndex":31,"id":"exchange-014"},{"speaker":"沢田委員","kind":"意見","question":"聞くところによると、学校は普通の一般の建物よりかなり頑丈にできていて、現状のものを解体するという点でもなかなか大変だし、かなり騒音、振動があるということを考えますと、プレハブ構造というのは、やっぱりいろいろ伝わりやすいですし、ぜひ空調もそうですけれども、二重サッシなり、防音のサッシをしっかりと、それから壁にも断音材というのがあるのかどうかよくわからないけれども。","respondent":"鷹倉庶務課長","answer":"今、申し上げたのは、当然、全体の省エネという形の考え方をきちっと整理した形で、空調問題をとらえていくです。次は、当然、全館空調に軍配が上がる可能性が高いと思われるわけです。","voiceIndex":33,"id":"exchange-015"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は、普通教室には空調が必要だけれども、特別教室には要らないということは、それはちょっと無理があると思うんです。せっかくのこれだけ立派な計画ですし、全館空調ということを考えたというニュアンスはわかるんですけれども、ぜひこの際ですから、全館でやれば入るわけですけれども、特別教室にも空調を怠りなく設定していただきたいということだけ要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先ほどの説明の中で、メディアセンターの図書の話がありました。学校から言われたからというニュアンスに聞こえたものですから、その確認だけいただきたい。それから、メディアセンターという名前ですけれども、ここは、一般開放をするんでしょうか。そうでしたら、そこで当然授業をするわけですから、ここでの安全確保。それをどう考えているんでしょうかということをお伺いしたいんです。","respondent":"鷹倉庶務課長","answer":"子どもたちのいない時間帯に開放していくという前提が考えられますし、従来の学校等の関係もあるわけですけれども、新しい学校については、先ほどお話がございましたような、可能な安全対策機器を備えることによって、安全対策も十分図れるのかなと考えております。","voiceIndex":36,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問","question":"各委員のお話に共通しているところがあるんですが、今の時代ですから、一般にしてみれば、地域に開放しなさいと、そう言っていることは当然だと思います。ですから、矛盾する話になるかもしれませんけれども、その間を埋めるためには、先ほど話が出て、課長がおっしゃったようないろいろなセキュリティの仕組みをつくっていただいて、安全確保を十分にしながらも、一般に開放していく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほど、すまいるスクールのことで、２２カ月、かなりの期間、なかなか使用しにくい部分があるということなんですが、先ほどのご答弁の中で、学校の中で今のものを維持するような形でというお話をされているんですが、安全性を考えていくと、むしろ、学校の中だけじゃなくて、例えば近隣の、今回、閉鎖する学童保育クラブもありますので、この辺の利用も含めて、暫定的にそこの場所を借りるとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-019"},{"speaker":"石田副委員長","kind":"質問・要望","question":"基本的に新しい校舎を建てていく中で、さまざまな制約の中で３階になってきたんだろうけれども、３階でも何でも、学校側の今のお話を聞きながら、例えばそういうふうに仕切っていくのか、パソコンとメディアと一緒にしていくのかということなんだけれども、今後、開放していくということであれば、ある一定の考え方を持っていかないと、もちろん学校があるのはわかるけれども。","respondent":"鷹倉庶務課長","answer":"学校のお話を聞きながらやっていくわけですけれども、基本は、先ほどもちょっと説明の中でお話し申し上げましたが、私ども、学校改築を進めていく上での教育委員会としての一つの考え方、学校改築計画指針というのをお示ししています。","voiceIndex":40,"id":"exchange-020"},{"speaker":"石田副委員長","kind":"質問・要望","question":"図書の問題は、今、おっしゃったとおりで、区立の図書館というものがあって、学校の図書室を開放していくとなると、それぞれの連携が必要でしょうから、これから校舎改築が進んでいくんであれば、新たな考え方をしっかり盛り込んでいただきたい。教育委員会は、もちろん考え方があるでしょうし、区立図書館の考え方ももちろんあるでしょうから、それをかみ合わせた中で、ぜひ、考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"小中一貫校のほうの質問ですけれども、この問題はいろいろ、この前も意見を述べさせていただきましたが、改めて、地域住民と保護者、説明会と合意形成がどのように進められたのかという点を、初めに伺いたいと思います。教育内容を含め、建設の計画、また説明会を今まで行ってきたと思いますので、これまでの経過を説明していただきたいと思います。日程および回数を教えてください。","respondent":"鷹倉庶務課長","answer":"今後、きょう、こういう形で報告していますので、どの段階で地域の中に入っていくのが適切かという部分、改築検討会の中にＰＴＡの方々もいらっしゃいますので、その辺の意見を踏まえながら、ＰＴＡだけじゃなくて、地域にどういうタイミングでお話申し上げていくのが。","voiceIndex":44,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"今の説明ですと、まず、大井地区における保護者および地域の方々への説明は、昨年１回行ったと。大崎地区では、先行して出ていますけれども、個別というのは学校ごとでしょうか、数回行っているという説明でしたけれども、今回、決定からまだ短い期間の中で、ここまで計画の全容が進められている。では、大井地区はどうかというと、昨年に１回きりで、今後の日程すらまだ決まっていない。","respondent":"鷹倉庶務課長","answer":"きょう、この委員会で説明しているとおり、きょうこの後また、大井地区の施設検討部会というものがあります。これは、先ほどに申し上げているとおり、今、このゾーニングを踏まえつつ、いろいろ検討しています。","voiceIndex":46,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのものに対して、結果だけを押しつける、こういう姿勢こそを、教育行政として改めるべきではないのかなと思うんです。やはり、計画決定以前の情報こそ、住民が求めているわけですから、その辺に真摯に耳を傾ける、そして、きちんと回答していく、そうやって積み重ねた上で、新しい区民参加の学校づくりを進めていくべきではないかと思いますけれども、いかがでしょうか。","respondent":"古川教育次長、堺委員長","answer":"したがいまして、本日は文教委員会で、この間の経過と、そして現状についてのご報告を申し上げ、今後、施設検討部会、そして周辺の方々、学校関係者等も踏まえたご説明に入っていく、このように考えてあります。今まで、関連するということで、私も発言を許可しておりますが、タイトルについては、小中一貫校の建設計画についての説明をしていただいて、この部分についての質疑という形で、きょうは進めしていますので、その辺に関連して。","voiceIndex":48,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"建物の高さがどのぐらいになるんでしょうか。は解体から始まるわけですから、騒音の問題も出てくる、振動の問題も出てくる。もしかしたら風の問題も出てくるかもしれない。教育内容には触れませんけれども、建設が平成１９年４月をめどに、これは何としても維持しなければいけないと、こういう姿勢ではやっぱり、とても住民参加とは言えないと思いますので、その点について回答していただきたいと思います。","respondent":"鷹倉庶務課長","answer":"一つの事業といいますか、施策をしますときに、当たり前の話ですけれども、１Ｈ５Ｗですか、いつ、どこで、何をどうするのか、このお話がないと、それこそお話にならないんじゃないかと思います。","voiceIndex":51,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、もちろん行政が開設のめどをつけて進めていくというのは、方向としてはあり得ると思います。教育長に、これからの進め方の姿勢について、ご意見を述べていただきたいんですけれども、ぜひ区民参加で、こういう学校づくりを進めていただきたいと思いますので、教育長の認識を聞かせていただきたいと思います。","respondent":"鷹倉庶務課長","answer":"私ども教育委員会として、当然のこととして、開かれた行政という形で、区民の方々の声を聞くと、当然の姿勢を持って進んでいるです。","voiceIndex":53,"id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"多い人は、１日５時間以上もご主人を介護している人が１階で日影になる。去年の１２月にやられて、きのうで３回目で、もう期日があるからこれでお終いだと、話し合いはしませんと。だけどそれなら、去年の６月に出た基本計画の段階で、なぜ住民にその問題の意見を聞こうとしなかったのか。今、この段になって、平成１８年４月開校だから、もう期限切れですというふうに、結局なっちゃったわけじゃないですか。","respondent":"鷹倉庶務課長","answer":"先ほども、ちょっと中塚委員のお話の中でも申し上げましたとおり、建物、学校改築ということで、基本設計をして実施設計をして、最終段階で、紛争防止という形で近隣に説明していく、こういう流れが組まれるわけです。","voiceIndex":55,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"私も見たんです。ちょっと大きなゴシックで、せいぜい５行ぐらいです。例えば大井地区小中一貫校のときに、プロポーザルで示したコンセプトとはどんなことなんでしょうか。ここに書かれていることの中に、それがあらわれているんだと思うんですが、どういうコンセプトを示して、これで設計しなさいと、いわゆる条件といいますか、それがあったら、ちょっと説明願いたいと思います。","respondent":"鷹倉庶務課長","answer":"先ほどの資料の中で、改築検討部会の中で条件整備をしたということ、これがプロポーザルの設計業者の提案条件ということをお示ししているわけです。","voiceIndex":57,"id":"exchange-028"},{"speaker":"沢田委員","kind":"質問・要望","question":"これで終わります。きのうちょっと微妙な問題が持ち上がって、申しわけないんですが、きのうも、例えば西側に建てる案、南側に移す案、幾つか考えられるんだけれども、「それは考えたのか」と言ったら、「考えました」と。ちょっと関係ないところで大変申しわけないんですが、ぜひそれを今後の中で生かしていただきたいということだけ言っておきたいと思います。","respondent":"古川教育次長","answer":"今まですべてやってきた事柄を、これからのさまざまな取り組みの中で、十分に課題をとらえ、それをまた改善していく、この気持ちは持ってありますので、これからも大井地区、さらには他の地区についても、そのような考え方を持ちながら。","voiceIndex":59,"id":"exchange-029"},{"speaker":"山路委員","kind":"質問・要望","question":"言葉の表現で気になるところがありますので、ちょっと教えていただきたいと思います。建設計画の中で、先ほどの第二延山小学校の施設計画の説明の中で、下から３番目に、〔「第二延山小学校ですか」と呼ぶ者あり〕ですから、ちょっとそこの説明をしていただきたいということなんです。多分違いがあると思うんですけれども、どういう違いがあるのか説明をちょっとしていただきたい。","respondent":"鷹倉庶務課長","answer":"ただ実際問題として、具体的に各学校のどの部分がどちらに該当しているのかということになってきますと、例えばトイレの段差解消はどっちなんだとなってきますと、なかなか難しい部分があるのかなと思いますけれども、概念の部分では、そういう関係にあるのかなと思ってあります。","voiceIndex":61,"id":"exchange-030"},{"speaker":"山路委員","kind":"質問・要望","question":"大体説明はわかりましたけれども、バリアフリーというのは、あくまでも既存のものが存在するという条件のもとにバリアしていくわけですね。学校というのは新しい建物で、この建物自体が子どもにとって何かバリアがあるのかなと想像しちゃうんですね。それでこの言葉が使ってあるのかなと。そこのバリアとは何だろうと疑問に思うわけですよ。そこをちょっと説明していただきたい。","respondent":"鷹倉庶務課長","answer":"ご指摘のとおりだと思います。用語の使い方として、ここでこういう形で使っているということで、設計業者が違いますので、こういうふうに理解しています。","voiceIndex":63,"id":"exchange-031"},{"speaker":"山路委員","kind":"意見","question":"設計の会社が違いますので、こういう言葉を使ったのか、無難に書いているのかと思ったんですけれども、将来、この辺を間違わないようにきちっと、一般にだんだん広まっていく言葉ですので、そこをお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"二つ教えていただきたいと思います。仮校舎なんですけれども、敷地内に仮校舎を建てるという方向だということなんですが、ほかに近隣に仮校舎を建てられる敷地がほんとうになかったんでしょうか。ですけれども、これだけのことをやるんであるならば、それなりの敷地等々を含めて、かなり十分に検討した上で、敷地内にという形だったのか。そこら辺の経緯を、もう少し詳しくお答え願います。","respondent":"鷹倉庶務課長","answer":"今回、中学校ですので、先ほどの小学校よりは少しエリアを広げながら考えることは可能なのかなと思いますけれども、実際に敷地的に必要な面積というのは、先ほど、第二延山小学校で言ったとおり、ある程度のまとまったものが必要になってくる。","voiceIndex":66,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"なかったというお話なんですが、でもあそこに西大井広場があると思うんです。有効活用ですね、たしか西大井保育園も仮園舎として使わせていただいた。その西大井広場というのは、どうして候補に上がらなかったんでしょうか。","respondent":"鷹倉庶務課長","answer":"したがって、あそこ全体を借りていくということは、広さ的にも課題があろうかと思いますけれども、全体をというのはなかなか、現実問題として難しいというふうに、私どもは考えております。","voiceIndex":68,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"西大井広場というのは敷地的に狭いということで、仮校舎ですから、例えば給食施設とかというのはほかのところを借りるとか、近隣の学校施設等々を含めて考えたときに、かなりいろいろ削れる部分があると思いますが、それでもやっぱり狭いということなのか。実際にこの敷地内で仮校舎を建てるとなりますと、実際に校庭が１,８００m2ですね。実際はどうでしょうか。工夫はないでしょうか。","respondent":"古川教育次長","answer":"したがいまして、それぞれ学校の置かれている状況によって、一概には言えませんが、改築をするに当たっては、その学校の中での一定の仮設校舎の切り回しというものを、今後前提にしつつ、周辺環境をいかに利用するか、こういう方法をとらないと。","voiceIndex":70,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、多少歩くことになるかもしれないけれども、工事の現場で子どもたちが教育を受けるということはやっぱりよくないし、避けたいことだと思いますので、それは今後とも有効利用ができるかどうかということを、住民の方たちの理解も必要かもしれませんけれども、なるべく理解していただくように、ここのところを配慮していただきたいなと思います。そこら辺のお考えをお聞きしたいと思います。","respondent":"鷹倉庶務課長","answer":"単に安全管理だけではなくて、子どもたちとの触れ合い、接触というものを確保していくことを考えてありますが、そういうことを参考にしながら進めていく必要があろうかと考えています。","voiceIndex":72,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな面で、スペースを有効活用していただいて、教師と生徒、それから地域と、いろいろ相反するところはあるんですけれども、この辺がうまく調和できるように考慮していただきたい、うまく利用していただく方法を取り入れていただきたいと思っています。第二延山小学校にはあるんですが、ここにはないなと思って、今度は一緒になってしまいますので、ＰＴＡ室はぜひ確保してほしいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-037"}]},{"id":"topic-02","title":"続きまして、予定４その他","agenda":"続きまして、予定４その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"学力テストの変更に関しての質問なんですけれども、７月１０日に要綱が変更して、若干内容が変わったんですけれども、この中に、中学校１年生を対象とすると書いてあるんですけれども、今回の実施は、小学校６年生になったというところで、要綱が変更したのかなと思っているんですね。もし変更したんであれば、その辺のところをちょっと説明していただければと思います。","respondent":"中島指導課長","answer":"ご指摘のように、対象学年等が変わっておりますので、要綱の変更はしています。","voiceIndex":85,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜかというと、このときに問題になったのは公開の内容ですか、やっぱりいろいろ問題になりまして、今現在、僕も新要綱を持っているわけじゃないので、変更になったのかどうか全く知る術がないんですけれども、２月２４日の実施ですけれども、文教委員会に説明が足りないんじゃないかなと思うので、新要綱を出していただきたいとともに、変更事項を報告していただければと思います。","respondent":"中島指導課長","answer":"情報提供はさせていただきたいと思います。","voiceIndex":87,"id":"exchange-039"},{"speaker":"西本委員","kind":"確認","question":"一つ確認させてください。先ほどの学力定着度テストの件なんですが、小学校６年生全員で、その結果が小学校の評価になる、反省材料にするわけですけれども、中学校は、もちろん私立に行かれている方もいらっしゃるので、その人たちを除いた子どもたちでまとめた形で中学校で使っていくという、そういう理解でよろしいんでしょうか。","respondent":"中島指導課長","answer":"そのとおりです。","voiceIndex":89,"id":"exchange-040"},{"speaker":"石田副委員長","kind":"質問・要望","question":"すまいるスクールの件で、今、３月に要綱ということなんですが、もちろんご意見を踏まえてやっていただくのは結構なんですが、これも要望にしておきますけれども、本来のすまいるスクールをスタートするときのお考えがあったはずだと思うんです、それを忘れずにぜひある一定の考え方を持って、当初、それを立ち上げたときに、我々もさんざん意見を言わせていただいたわけですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-041"},{"speaker":"沢田委員","kind":"質問","question":"ただ、これは全体の定数そのものを増やすということではないですから、内輪の中でこっちへやるあっちへやると、習熟度だとか、ＴＴだとかの部分を削ってやるみたいなところがあるので、１００点満点ではないと思うんで、少なくとも３０道府県が少人数学級をやっているし、区はないんですけれども、市町村ではもっと独自にやっているところが増えるわけなので、ちょっとそこら辺の状況だけ聞きたいと思います。","respondent":"若月教育長","answer":"この前、その件につきましてはお伺いをしたところです。あそこでお答えをしたとおりでありますが、これから教育長会があります。そこで、多分議題に上ってくるだろうと考えておりますので、その中での議論を見ていきたいと思っています。","voiceIndex":93,"id":"exchange-042"},{"speaker":"沢田委員","kind":"質問・要望","question":"せっかく国が、腰は引けているけれども、３０人学級を実施することの調査をやろうとしているときに、私は、積極的にそこを進めていく方向で発言をしてほしいと思います。一応、要望だけにとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-043"}]},{"id":"topic-03","title":"に戻りまして、所管事務調査","agenda":"に戻りまして、所管事務調査","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"それは、東京都の業務なんでしょうけれども、もしおわかりなら、どういうふうにされているかということを聞きたい。でも学校の先生は、多分そうじゃないと思うんですが、意見交換ですから言うんですけれども、できればタイムカードで管理をして、品川区の職員というわけですから、そんなことをやっていただきたいという思いで質問しますので、その三つを質問しますので、答弁をお願いいたします。","respondent":"鷹倉庶務課長","answer":"その部分について、私どももその意見を踏まえながら、今後、検討していく必要があるのかなと、今現在、考えているところです。","voiceIndex":102,"id":"exchange-044"},{"speaker":"伊藤委員","kind":"質問・要望","question":"要はこういういろいろな手当についてきちんと、Ａ職員がやりましたよ、働きました、だから支払うのは当然であって、それを客観的にどういう立場で担保をしているんでしょうかということをお伺いしたいのが一つ。そういう方々の出退勤の管理はタイムカードでやっているんでしょうかということをお伺いします。","respondent":"鷹倉庶務課長","answer":"第１点目の、給与の支払いの関係で、確かに都の関連ですけれども、給与支払い事務の手引き等、きちっと詳細にマニュアル的にまとまったものがあります。それに基づいて各学校の事務についても、教員、あるいは自分たち自身の給与手当、そういうものをやっている。","voiceIndex":104,"id":"exchange-045"},{"speaker":"伊藤委員","kind":"確認","question":"東京都というのはとても大きい自治体ですから、監査のことを考えたら、それはそんなことはできないと思います。学校現場で、私もいろいろ聞いていきますと、タイムカードはない、出退勤の確認は判こですよね。だから、そういう本当の根本の部分まで変えていくのは、意見交換だから言うんですけれども、東京都の条例を変えていくしかないでしょうかということをお伺いしたいんです。","respondent":"古川教育次長","answer":"区の職員ですので、区の職員と同様に勤怠についても、私どものほうで決められます。もちろん２３区の一定のものの考え方を、どう区が押さえるかというのは、一般論としてはあるかと思いますが、区の考え方で、服務規程等々の改善等も対応できる範囲です。","voiceIndex":106,"id":"exchange-046"},{"speaker":"伊藤委員","kind":"質問・要望","question":"どう言ったらいいんですか、品川区立の小学校、中学校に勤務されているわけですから、そこに通っている親御さんとか、保護者の皆さんが、例えば学校の先生は都の職員とわかっている人もいるでしょうけれども、一義的にはやっぱり品川区の職員と思う人が多いと思います。確認したいのが、品川区にあっては、そういう学校長の権限が自由に発揮できる仕組みは、十分勤務体系の中でされているんですかということ。","respondent":"古川教育次長、中島指導課長","answer":"それを平成１２年４月以降、いかにして品川区の職員としての一体性を確保し、先ほど、お話がございましたように、勤怠についても、当然、そのようにあるべき、すべきだと考えています。ちょっと前段の部分ですが、品川区の職員です。校長の権限が自由に発揮できるのかという部分ですけれども、一応、品川区立の学校の校長は、基本的に４管理２監督と言われる権限を与えられる中で、例えば教育課程の管理をしておりますので、来年度。","voiceIndex":108,"id":"exchange-047"},{"speaker":"伊藤委員","kind":"質問","question":"もうこれで終わりにしますけれども、そういう体制はわかったんですが、広島の例ではありませんけれども、そういうことを含みながら聞いていますのは、校長とそういう各種団体との取り決めが過去にあったと思われますが、そういうふうなことが、もし今仮にあって、これからプラン２１とか、さまざまな教育改革を具体化していく中にあって、もし校長の権限が阻害される仕組みがあったとするんだったら。","respondent":"中島指導課長","answer":"そういったような取り決めはないと考えています。","voiceIndex":111,"id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校職員の休暇についてお聞きしたいんですけれども、年次休暇のところは、管理者と教員と分けて、先ほど説明があったんですけれども、特別休暇の夏季休暇は全体９割が利用ということですけれども、管理者と教員で、もしそれぞれ出ていれば説明していただきたいと思います。","respondent":"中島指導課長","answer":"そちらのほうのデータは、今手元にございません。必要であればご提示したいと思います。","voiceIndex":113,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"年次休暇で、２０日間が限度なんだけれども、率直に見て思ったのは、管理者が５日間と２時間、限度の約４分の１しか取れてないんだと。教員も１３日と７時間ということで、およそ半分。なぜ制度の２０日間が取れないのか。その理由がもしわかれば教えていただきたい。それから、夏季休暇に関しても、管理者も含めて１割の教員が取れていないこの現状、何か理由があるのか、教えてください。","respondent":"中島指導課長","answer":"２００日毎日子どもが来ているような状況の中で、例えば校長が、自分の管理監督する学校を、経営、運営していくといったときに、病気とかいう場合は別かもしれませんけれども、そこである程度プライベートな時間を取るというのは。","voiceIndex":115,"id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"教員とはいえ働いているわけですから、必要な休暇はきちんと取得されなければいけないと思うし、一方で学校の教育というところで、ほかの仕事と単純に比べることができない部分も、当然あると思うんです。そのため、現場も含めた教育委員会の努力も、一定必要になってくるのかなと思います。これは意見として述べします。休暇の実態というのを、他区と何か比べるものがあれば、教えていただきたいんです。","respondent":"中島指導課長","answer":"つけ加えさせて言わせていただきますと、先ほど、ちょっと説明がありました給与体系の中でも、教職調整額といったような部分で、これは一応勤務時間外の部分を想定している要素が強いんですけれども、額面で４％という形で出てきているようなところに。","voiceIndex":117,"id":"exchange-051"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、学校職員の任用体系というところで、今、校長先生を民間から採用するということがよく行われているんですが、東京都の実態と品川区の考え方と、なかなか採用権というのが区のほうにおりてこないということがあるかとは思うんですが、ただ、今後どうなるかわからないという現状もある中で、広く人材を確保するという意味では。","respondent":"中島指導課長","answer":"ちょっと私のほうの情報が、今手持ちの資料がなくて申しわけないんですが、民間人校長につきましては、東京都の教育委員会の中でも、都立高等学校のほうで採用が実施されている状況があります。","voiceIndex":119,"id":"exchange-052"},{"speaker":"西本委員","kind":"意見","question":"ただ、やっぱり必要性があるということは、議論をある程度詰めていくべきところがあるかなと思います。これは、すぐに何かをしようということでは、できないかもしれませんけれども、議論をしていきたいなと、意見として申したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-053"},{"speaker":"石田副委員長","kind":"質問・要望","question":"幾つか伺いたいんですけれども、資料もいただきたいんですが、給料の部分の何とか手当というのがたくさんありますよね。非常に手当が多いんだけれども、４％手当されているというのも含めて、調整手当だとかわけがわからないのがあるんですけれども、例えば、これは４項目に分かれていますとか、項目がわかれば、後でもいいんだけれども、教えてほしいというのが一つ。","respondent":"鷹倉庶務課長、中島指導課長","answer":"なるべくわかる部分があれば、提供していきたいと考えております。現在では、自宅における研修というのは基本的には認めないという形の方向で、すべての学校で実施をされている状況があります。研修ではありますけれども、基本的に職務は職場で行うという形が、学校でも基本です。","voiceIndex":122,"id":"exchange-054"},{"speaker":"本間委員","kind":"意見","question":"これもやっぱり、現実にイギリスのロンドンで聞いた話なんですけれども、教員のなり手がいないというか、教員が少ない、なり手がいないという部分もあろうかと思いますが、それはロンドンの市内でなぜそうかといいますと、結局、教員の給与では、住宅費も含めて、なかなか生活できないというようなことがあるように聞きました。","respondent":"鷹倉庶務課長","answer":"調整手当というのがございまして、これは、我々一般の行政職にもついているんですけれども、これが、物価および生計費が特に高い地域に在勤する職員に対して支給する手当である、これが都市部の手当ということになります。","voiceIndex":127,"id":"exchange-055"},{"speaker":"本間委員","kind":"質問","question":"ちょっと待ってください。アスタリスクの教職調整額は、その下からと全然別の話の部分なんですか。","respondent":"鷹倉庶務課長","answer":"ええ。","voiceIndex":129,"id":"exchange-056"},{"speaker":"本間委員","kind":"質問","question":"ああ、そうですか。わかりました。そうすると、そのような部分も考慮されているというふうに判断してよろしいんですか。","respondent":"鷹倉庶務課長","answer":"そのとおりです。","voiceIndex":131,"id":"exchange-057"},{"speaker":"石田副委員長","kind":"質問・要望","question":"ちょっと、品川区の教員の平均給料を出していると思うんですけれども、それを教えていただきたいのと、逆に４％は別として、その以外で出している手当の総額でも、平均１人当たり幾らでもいいけれども、どれぐらいの割合があるのかなと。","respondent":"鷹倉庶務課長","answer":"平均年齢は、４４.７歳ということになっています。これに、所定の期末・勤勉手当を足し込んでいきますと、平均的な年収が８５７万円ということになってあります。","voiceIndex":133,"id":"exchange-058"},{"speaker":"石田副委員長","kind":"意見","question":"単純に計算しちゃっていいのかどうかわからないけれども、５１万８,０００円と４１万７,０００円でしょ、そうすると１０万円だと。５１万円から４％は、それに含まれていると。そうすると約２万幾らだと。の七、八万円は手当だと、こんな感じでいいのかな、考え方は。","respondent":"鷹倉庶務課長","answer":"大方、そういうことになろうかと思います。","voiceIndex":135,"id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4494#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":67271,"voices":142}},{"id":"h16-20040120-5","meetingId":"h16-cm01","date":"2004年1月20日","dateIso":"2004-01-20","committee":"総務委員会","time":"午後１時０４分～午後３時１９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１５年陳情第１３号、臨時職員などの公正な賃金等の確保に関する陳情","agenda":"平成１５年陳情第１３号、臨時職員などの公正な賃金等の確保に関する陳情","exchanges":[{"speaker":"本田委員","kind":"質問・要望","question":"１点お聞きします。３番目の人事委員会給与勧告の説明で、陳情で言っている臨時職員等の時間単価の決定に人事委員会が関与していないと思っていたんですけれども、今の説明ですと何か関与しているのかなと誤解を受けるような感じなんですが、その点がどうなのか、もう一度ご説明いただきたいと思います。","respondent":"桑村人事課長","answer":"説明不足で申し訳ございませんでした。これは参考に区の正規職員の賃金の流れということでご説明したわけです。賃金の額自体は特別区人事委員会は関与してございません。","voiceIndex":6,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"４番の交通費のところなんですけれども、品川区は別途支給となっていますが、具体的に例えば世田谷区みたいに１日１,０００円限度の実費とか、そういうのがあったら教えていただきたい。","respondent":"桑村人事課長","answer":"基本的に実費を支給するということで、限度につきましては職員の限度額ですけれども、それに合わせて、それ以上は出せませんけれども、大体１日２,２００円ぐらいになろうかと思いますけれども、その辺まででしたら実費がかかれば支給するという考えです。","voiceIndex":10,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"参考送付されたものが主たる陳情の意図で、こっちは何か品川区にはつけ足しで、各区に出されているというような話が出ていたけれども、出しておこうというようなことなのかなというように感じます。ちょっと言葉がよくわからないので、「均等待遇の実現プログラム」とか出ているんだけれども、この均等待遇というのは固有名詞なんですか、普通名詞なんですか。","respondent":"桑村人事課長","answer":"私もよくわかっていないので、文面を読めば、正規の職員、臨時職員の方、あるいは非常勤の方も変わらない待遇というんでしょうか、そういう計画をつくれというふうな意味なのかなというふうに使われているだけです。","voiceIndex":14,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"待遇で均等ってあり得ないでしょう。年功序列がいいか悪いか別としても、年齢で違うだろうし、職種で違うだろうし、勤務時間で残業が増えれば違うでしょうし、均等待遇というのは、この人はどう訴えているのかよくわからない。何を訴えたいのかよく伝わってこないんですよ。具体的に書かれている地方自治体、国家公務員も含めて最低賃金が１,０００円というところはあるんですか。","respondent":"桑村人事課長","answer":"全国で見ると６３０円とか、青森あたりですと６０５円ですとか、相当低いのは事実です。そうしますと、東京都の公務員の調整手当等の率が一番高いわけですので、それ等を考えますと１,０００円以上を最低にしているような自治体はないんではないかというふうに推測しています。","voiceIndex":16,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"ちょっと乱暴な、さっき言った最低賃金が物価だとかいろいろ調べ、それから地方というか、それぞれの地域によるいろんな物価などを調べて、較差をつけながら決めているところへ、ぽんと来るというのはちょっと信じがたい陳情というふうに、僕は受け止めるんだけれども、ちょっと信じがたいなという、乱暴な陳情だなという印象を受けました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"資料が出ましたので、参考に伺います。品川区臨時職員・非常勤職員と書いてありますが、年齢構成、中身がわからなければ最低と最高まで教えてください。","respondent":"桑村人事課長","answer":"ちょっと、今年齢は持ってございませんけれども、まず臨時職員のほうですけれども、年齢を区切っているわけでございませんので、普通で言えばやはり５０歳前後ぐらいになるのかなと考えています。","voiceIndex":19,"id":"exchange-006"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、一応何らかの形でほかの就職を辞めて家庭に入るか、別の事情があるか別として、入った方が再就職というようなことで考えていいか。それから、最高というのは５０歳前後なんですか。","respondent":"桑村人事課長","answer":"言い方がまずくて申し訳ございません。平均という意味で、最高は多分７０歳ぐらい方までいらっしゃるんじゃないかと思います。","voiceIndex":21,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"何点か伺いたいと思うんですけれども、今年度も区長の施政方針のところでも正規職員を減らしてという発言があったんですけれども、いわゆる行革をやって２０年になるんですけれども、この間、１,３００人ぐらい職員を減らしたということを述べていたと思うんです。","respondent":"桑村人事課長","answer":"それからもう一つは、臨時職員は大幅に減っている部分があります。これまで保育園等で臨時職員の方で２時間あるいは朝、会議等のアルバイトという形でやってきていただいた方を非常勤という形で、１年間継続して雇用していこうというような政策を変えた部分があります。","voiceIndex":23,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"私が質問したかったのは、本来常勤で配置しなければいけないところが非常勤とか臨時で配置しているところがないのかどうかという問題意識があったんですけれども、今のご説明で、例えば保育園のところでは朝・夕方の短時間で、かなりそういう方が多いかと思うんです。具体的に、例えば保育園ですとどういう勤務時間というのがあるんでしょうか。","respondent":"桑村人事課長","answer":"保育園の場合ですけれども、４時間から大体２時間ぐらいです。","voiceIndex":25,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"図書館のところでは、かなり土曜、日曜、祝祭日に開いていますね。こういうところでの正規職員と非常勤職員のシフトの考え方というのはあるんですか。要するに、開館時間もかなり延長しているというところで、正規職員の配置と非常勤職員の配置の考え方、それと実態はどういうふうに配置されているかというのが説明できれば。","respondent":"桑村人事課長","answer":"一定、開館時間を増やすべきだというようなこと、それに対してサービス水準を維持するというようなこと。その中で効率的な仕事ができないのかということがございまして、正規職員は大体３人を削ったぐらいのところで非常勤５人というような形で問題を絞りました。","voiceIndex":27,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"図書館ですと、かなり非常勤職員の方がまず土曜日だとか、あるいは日曜日だとか、時間外だとか、かなり優先的に配置されるような実態があるやに聞いたんですけれども、実際にそういう考え方でやっておられるんでしょうか。","respondent":"桑村人事課長","answer":"そういう意味で、カウンター業務がどうしても手薄になるようなところに非常勤の方をお願いしたり、夜どうしても何名か残らなければいけませんので、その中の１人を回したりというようなことをやっているものだと思います。","voiceIndex":29,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると実際上、開館時間が増えれば増えるほど非常勤職員が配置されていくということが多くなってくると思うんですけれども。一つ聞きたいんですけれども、この賃金のところでは、例えば普通の職員ですと時間外とか休日出勤の場合は１.２５倍とか１.５倍とか、そういう考え方があるんですけれども、非常勤職員の方の場合は、どういうふうになっているんでしょうか。","respondent":"桑村人事課長","answer":"基本的には、非常勤という形態にもありますので、時間外と考えてございません。ただ、現実には一定の時間残ってもらったり、あるいは振りかえてもらって、繁忙期にはやってもらっているような事例があるかと思います。","voiceIndex":31,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、例えば図書館の場合、非常勤職員の賃金は時間単価で１,１５４円ということになっているんですけれども、日曜日だとか夕方、いわゆる通常の勤務からいくと時間外に入るケースが多いということになると、仮にそれが通常の勤務との比較でいくと、１,１５４円という単価は大体それに見合っているのかどうなのかというのがよくわからないんですけれども、この陳情では１,０００円以上ということで。","respondent":"桑村人事課長","answer":"その意味で、いつ休むかについては、もちろん月１３日ですので、もちろん非常勤職員ですので残りの日はほかの仕事をやっても構いませんし、そういう意味で正規職員より兼業は禁止されているとか、そういった種類のものではございませんので。","voiceIndex":33,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"私は、ちょっとそれはおかしいんじゃないかなと思うんです。そこのところはどうでしたか、込みですよね。２３区はかなりしているところが多いんですけれども、そこの考え方というのはどうなんでしょうか。先ほども公募の条件だというお話がありましたけれども、交通費のほうはどういうお考えでしょうか。","respondent":"桑村人事課長","answer":"通勤手当というのは、遠距離の方をいい人材を集めるというのは基本の考え方で、いわゆる高度成長期に整理されて、国、自治体でも整理されたということがあって、今回臨時職員と非常勤職員では制度が違うというのは、臨時職員は緊急時の対応で、例えば明日から何日間。","voiceIndex":35,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"確認","question":"先ほど、遠距離の場合でもいい人材を採っていくと、そういう考え方もある。それは当然だというふうに思うんです。確か人事委員とか総務省では、それを出していいというふうになっていたと思うんですけれども、今のご説明ですとどうも違うようなご答弁なんですけれども、そこのところを確認しておきたいんですけれども。","respondent":"桑村人事課長","answer":"私どもとすれば、事業の理解を得るんだとすれば、広報紙等で一般的な公募をして、区民の方にお勤めいただいたほうが、事業自体が円滑に動くというふうに考えてありますので、今のところそのようにやらせていただいているというだけです。","voiceIndex":37,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"その考え方はそういう考え方ということで、今の区の考え方ですけれども。もう一つ、今、私も区民の方からいろんな相談を受ける中で一番困るのは就職の相談なんです。大体、平均的に非常勤職員の方々の月の収入といいますか、あるいは年収というか、その辺がどういうふうになっているのか調べているものがあったら教えていただければと思います。","respondent":"桑村人事課長","answer":"かなりばらばらな数字でございまして、例えば図書館ですと月１３日で１２万円という数字です。保育園ですと、週４日の勤務ですけれども、これが１４万２,５００円、週５日で２時間ですと５万１,０００円という金額です。","voiceIndex":39,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"大体状況はわかりました。私も以前若い方々と話をずっと伺って、十四、五万円というのは私が勤め始めた頃と収入があまり変わらないんですよね。そもそも交通費は、実際に費用弁償ということでやっているところもあるということですので、やれないということではないわけですから、これは考えていくべきじゃないかというふうに思います。今日はこの内容については、私は趣旨採択でということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"},{"speaker":"築舘委員","kind":"質問・要望","question":"その辺のことをお話いただきたいということが１点。","respondent":"桑村人事課長","answer":"ご質問のあったように、時間が非常に長くなってきているというようなこともありますし、また一定の事業の部分がどうしても人数がいたほうがいいというようなこともあります。そういう意味では、非常勤職員という形で、そのときだけ１年間をお願いするというようなことです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"築舘委員","kind":"意見","question":"それと非常勤職員の単価ですけれども、民間から比べるとものすごくいいんじゃないかなと私は思うんですけれども、民間はさまざまなあれがありますけれども、そういう意味では民間が厳しくなっていて、数字的にも公務員の非常勤職員単価のほうがいいんじゃないかと思うんですけれども、その辺の資料があったらお願いします。要するに、非常勤職員を受けるときにどの程度の倍率で採用されているのか。","respondent":"桑村人事課長","answer":"そういう意味では、一点何倍というような数字があります。図書館ですと、ある程度倍率がありますので３倍とかそんな内容で、これもご希望になっていただく職種の条件によってちょっと開きがあるかと思います。","voiceIndex":44,"id":"exchange-019"},{"speaker":"築舘委員","kind":"意見","question":"品川区内から採っていただいているということもあったり、そういう意味では非常勤職員ということで、ある意味で１年ということで、将来的なことも含めた上での方針を立てていただいての雇用ということですので、私は決して安いということはないと思うんです。もっとすごいのは、ボランティアで一銭ももらわないでやっている人はいっぱいいらっしゃいますね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-020"},{"speaker":"本田委員","kind":"質問・要望","question":"これを採択するということについては、反対いたします。ただ、だからといってこれでいいということではなくて、市場の動き等を含めて、人事委員会の勧告は一切受けない各区の独自の采配ができる性格のものですから、働いていただく方々に十分な対応ができるという姿勢は、行政としては今後取っていっていただきたいということを要望はしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"先ほど来、築舘委員からも指摘があって、数字的な問題、それから陳情者の意図がよく酌み取れないところもありますし、品川区の対応が、この陳情者はどう受け止めて陳情しているのかよくわからないというところもある。それから、数字的に我々は品川区がきちんとやっているということですから、この陳情は我々としては受け止められないということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問","question":"先ほど言いましたけれども、私は趣旨採択をすべきだというふうに思います。区内、区内というふうにおっしゃいますけれども、正規職員の場合は確か２km以内と２km以上と、確かその辺で線を引いていると思うんです。やっぱり区内だということであれば、例えばそういう問題もあるわけですから、やっぱり正規職員と同じ考えということだと思うんですね、当然すべきだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-023"},{"speaker":"土井委員","kind":"質問","question":"陳情者が極めて具体的な金額等を示されて出されているというところに、ちょっと違和感を覚えるものがあるということと、それから今お話を伺ったように、品川区においては一定程度以上というか、レベルの対応をしているという状況にあるし、時代の変遷の中でこれからどうなるのか、この何年間かどうしてきたのか伺うところによると、ここのところ何もしなきゃ下げもしていないというふうに伺っておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"先ほど年齢構成を伺いました。先ほどの説明の中で最低で１４万円、若い人がマンション、単身アパートを借りて暮らせるかどうかという問題は残りますけれども、やはり今の年齢構成、４０歳から募集して５０歳前後、ときには７０歳以上まで、職種や時間によっては働けるという道をやはり大切にしたいというふうに思います。そういう意味で、この陳情についてはとりあえず不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-025"}]},{"id":"topic-02","title":"第２回「はばたけ！しながわ未来債」の発行","agenda":"第２回「はばたけ！しながわ未来債」の発行","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"参考に、金融機関で販売しているものでは、大体この条件ですと利息というのどのぐらいでしょうか。","respondent":"市岡企画財政課長","answer":"ちなみに高過ぎると、これは逆に区の資金調達の負担が大きくなるんですが、１２月に豊島区がやっぱり発行しているんですが、このときは０.８４でやっていますから、それに比べれば０.７６は高いんですが、いいところかなです。","voiceIndex":63,"id":"exchange-026"},{"speaker":"林（宏）委員","kind":"質問","question":"今の金利なんだけれども、第１回の人に説明をする気はありますか。１年ぐらい前のがあるんですかね。相当下がるでしょう。マンションの買値じゃないけれども、相当な差を、今みたいな説明で終りですか。","respondent":"市岡企画財政課長","answer":"というのは、多分今回非常に早く売れたというのは、条件もそうですけれども、前回で非常に区民の方々に浸透していたので、これはわかりませんけれども、多分前回買われた方の中でもう一度買われたという方がいらっしゃると思いますので。","voiceIndex":65,"id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問","question":"流通するわけですよね。そうすると第１回のものと第２回のものでは、そうじゃなくても第１回の流通価格というのは相当最初に出てきている。もう一つは、発行額が２億５,０００万円ということなんだけれども、この公園に限ってという目的が絞られた発行の仕方なんだけれども、この先、品川区はどういうふうに品川区の公募債としては考えていらっしゃるんですか。","respondent":"市岡企画財政課長","answer":"というのは、そのときの発行時点で５年満期一括償還というふうに満期をなるべく短くしたということもあって、ご判断されるのは定期性の預金と品川区債で比較されているので、私どもとしては「５年まで持っていただくのが一番有利だと考えています」というご説明をしています。","voiceIndex":67,"id":"exchange-028"},{"speaker":"林（宏）委員","kind":"意見","question":"もう一つは、樹木は寄附を募っているよね。片や金利を払ってまでもお金を集めるのと、片や金を出すよ、木を植えてやる、ちょっと言葉は乱暴すぎるけれども、そういう全く正反対の、資金を集めたわけではないんでしょうけれども、木を植える部分についてはボランティア的な部分も、お休み石みたいな考え方もあってしたんでしょうけれども、その辺はどうとらえますか。","respondent":"市岡企画財政課長","answer":"ちなみに、こちらは金利をもちろんお支払いするんですが、やはり昨年度も含めて買っていただいた方に何らかの意義深いものにしたいということで、オープニングのときにご招待できるようなご案内を考えておりまして。","voiceIndex":69,"id":"exchange-029"},{"speaker":"本田委員","kind":"質問","question":"確かに、区民がこういう公募をして、自分も資金提供して、もちろん利息はあるにしても区政に参加しているんだという新しいとらえ方というのはあると思うんですけれども、自治体として住民のインフラ、ハード、ソフトを基本的にやっていかなきゃならないものをそういう形でやるというのは、何かラインを引いているのか、流れがあるのか、その辺の考え方をお聞きしたいと思うんです。","respondent":"市岡企画財政課長","answer":"ただ、そのときに政府債はいいんですけれども、銀行債なんかを多額に発行しますと当然金利がかかるし、それから割引料その他の手数料もかかるんですが、それは結局金融機関に資金コストとしては当然のことですけれども払うわけですけれども。","voiceIndex":71,"id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"財調を１.２％プラスするということなんですが、まだ詳細はあれなんでしょうけれども、あらあらわかっていることだけでも教えていただけますか。","respondent":"市岡企画財政課長、鈴木（真）委員長","answer":"その中で報道のとおり対前年で交付金ペースで１.１％の増、具体的に言いますと平成１６年度のフレームは伸びておりますし、それから平成１５年度も再調整で、法人住民税を中心に景気回復の反映をしてかなり数字が出てきておりますので。ほかになければ、その他をこれで終了いたします。","voiceIndex":78,"id":"exchange-031"}]},{"id":"topic-03","title":"財政調整制度「都区検討会」における検討状況","agenda":"財政調整制度「都区検討会」における検討状況","exchanges":[{"speaker":"本田委員","kind":"質問・要望","question":"１点、大都市事務の検討会のほうですが、東京都の姿勢に対して、もっと誠意ある対応を求めたと。つまり、都がやっているといっても、大都市問題として基本的は２３区に係わっているわけですよね。ここで東京都に誠意ある４８％の中身の説明を求めているんですけれども、逆に２３区のほうから組んでいくような、そういう論戦というのはできないんですかね、ちょっとその点をお聞きしたいと思います。","respondent":"市岡企画財政課長","answer":"東京都は大きな予算の中の財調というのは一部だという認識で、また多摩の各市からすると、２３区に限定された制度なのでなかなか見えにくいということもあろうかと思うんですが、本田委員がおっしゃるとおり財調をめぐる議論というのは、なかなか区民。","voiceIndex":85,"id":"exchange-032"},{"speaker":"本田委員","kind":"質問","question":"そういう点では、互いの違いは２３区の中にあるとしても、どこかでパワーを一つの大きな力、８００万都民、区民のパワーをというものを発揮した、それにふさわしい地方自治といいますか、流れといいますか、新しい東京の都市建設といいますか、都市像といいますか、そういうのがあってもいいんじゃないかというふうに、最近思っているんですけれども、大変抽象的な質問にもならないんですけれども。","respondent":"中尾根企画部長","answer":"これをどうやって打破していくのかということですけれども、これはやはりトップの区長会等での議論が煮詰まってやらないと、実務的な面で真剣に東京都と２３区でどうあるべきかと、この議論は事務レベルの中ではどうあるべきかというのは非常に真剣にやっていますが。","voiceIndex":87,"id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問","question":"相手側はどういう立場の方が出てきているのか、それを一つ教えてください。","respondent":"市岡企画財政課長","answer":"この検討会は当初は区政課長を中心メンバーとして、メンバーとしては財務局の財政課長もいるんですが、財政課長は直接はほとんど出てきませんで、急遽かどうかわかりませんけれども、東京都は戦線を補強しまして、このための担当副参事をつけております。","voiceIndex":89,"id":"exchange-034"},{"speaker":"林（宏）委員","kind":"意見","question":"せっかく区側は部長クラスで何とか答えを引き出そう、解決の糸口というか、何か都側は手抜きというか、さっきの金額にしても６兆円を切っているから１００分の１ではないけれども、ちょっと場に出ていればいいんだというような感じではない。ここで議論して、区側の強い主張をすべきところとか、そういうのは都のどこまで伝わっていっているのかというのをちょっと聞かせてください。","respondent":"市岡企画財政課長","answer":"それで、東京都は委員おっしゃられるような懸念が全くないわけではないですが、多分私が見ているところでは、東京都はここのところ財源見通しが非常に不透明で厳しかったために、平成１５年の検討会の中で。","voiceIndex":91,"id":"exchange-035"},{"speaker":"林（宏）委員","kind":"質問","question":"市都という関係からいって、例えば警察にしても、警察庁と警視庁というようなことにもなってくるだろうし、他道府県と市という関係と、都と２３区という関係はもう変わりようがないというふうに、いろんな面で細かく言えば比べられる部分と、そういうのに当てはまらない部分とあるから問題になっているんだろうけれども、よそを例えとして使えないものなんですか。","respondent":"市岡企画財政課長","answer":"そういう政令指定都市と特別区はどこが違うかというと、都心区を含めて、品川区もだんだんその域に入ってきましたけれども、本来でしたら自分で調整税を取って大都市事務を賄える財源があるところと、今の制度のままでやったのでは財政が破綻してしまう。","voiceIndex":93,"id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"１点だけ、最初のほうで説明された、僕の聞き違いかどうかわかりませんが、４４％から５２％になった数字というか割り振り、配分、いわゆる清掃事業をスムーズに移管をし、移管後もスムーズに仕事ができるように、とりあえずという言葉を使ったかどうかわかりませんが、スムーズにいくために都のほうは５２％を妥協したみたいな形、区のほうも５２％ならばという。","respondent":"市岡企画財政課長","answer":"もちろん密接な関係にありますけれども、今回検討会でやっている議論というのは、財政制度によって例えば清掃事業をどうしようという議論をしているわけじゃなくて、少なくとも今行っている一組方式ですけれども、平成１２年に決めたときに、平成１７年までやっている処理形態が。","voiceIndex":95,"id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問","question":"議会のほうもどういうふうに考えたらいいのかというのがよくわからないんですけれども、今まで都区制度改革のときには、住民の皆さんと一緒に運動をやってきて制度は変わったんだけれども、肝心な財布は向こうに握られたままですから、ある意味では同じような運動が必要になってくるんじゃないかなという気もするんですけれども、その辺のところはどうかなと思っているんですけれども。","respondent":"市岡企画財政課長","answer":"１番目のお話ですが、今やっているのは毎年やっている財調協議とは別に、特に課題を抜き出して集中的にやりましょうという検討会です。本来の財調協議が整わなかったらどうか。","voiceIndex":97,"id":"exchange-038"},{"speaker":"土井委員","kind":"質問","question":"もともとは区民共通のお金なんですから、その中から我々的な立場からいけば、大都市事務のある部分については都に委託してやってもらっているんですよ、そのための金なんですよということになるとするならば、都に具体的に説明する、「あなたはこれをやれ。一致点、相違点という中にそういうものが入っているのかどうなのかなんですけれども。","respondent":"市岡企画財政課長","answer":"都議会に説明しているからいいんだというと、東京都の２３区に住んでいらっしゃる住民の方というのは、都民と区民が別々にいるような議論でして、都民であり区民である実際にそこに生活をされている住民の方がいて、その中で納めるのも一緒に納めていて。","voiceIndex":99,"id":"exchange-039"},{"speaker":"築舘委員","kind":"意見","question":"先ほど、大都市事務検討会は参事が出られているということなんですけれども、ほかのところは品川区としてはどういう形でタッチしているのか、それから東京都のほうはだれが担当しているのか。","respondent":"市岡企画財政課長","answer":"基本的には三つの検討会に各区の財政課長、区によっては部長がやっているところもありますけれども、そういうことも含めて財政課長レベルが三つに分かれて出ていますから、１区で２人は出ていないんですが、区側はこの３検討会で作戦本部をつくらなければいけないので。","voiceIndex":101,"id":"exchange-040"},{"speaker":"築舘委員","kind":"質問","question":"そうすると２３区はそれぞれの検討会に入っているわけですね。それと東京都の答えるほうは、大都市事務検討会は課長が対応しているけれども、ほかのほうは専門の清掃と学校の関係の方が担当しているわけですか。","respondent":"市岡企画財政課長","answer":"東京都は三つの検討会に、基本的に区政課長と担当課長は全部出ています。出ている係長は若干三つの検討会によって違いますけれども、基本的には両課長は全部に出ています。","voiceIndex":105,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1638#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":37874,"voices":112}},{"id":"h16-20040122-12","meetingId":"h16-cm01","date":"2004年1月22日","dateIso":"2004-01-22","committee":"清掃制度特別委員会","time":"午後１時０３分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"清掃制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査、東京二十三区清掃一部事務組合に関すること","agenda":"特定事件調査、東京二十三区清掃一部事務組合に関すること","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"個別なことで申し訳ないですが、流れとして説明をいただいた中で、少し内容のところで質問をさせていただきたいんですが、三つほどあります。一つ目は、１番のところですけれども、品川区として具体的な改革の内容を、今現在例えばどういうものなんだということがとらえられている部分があれば教えていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"ただ、この会議はようやく下命を、おそらく今年度も含めて検討が進められていくですけれども、品川区はどういうスタンスで臨むのかという部分については、助役会の検討の中ですから、明確に今具体的に申し上げられる部分はございませんが、区長の報告書にもありましたとおり。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"意見","question":"そうすると、家庭ごみの有料化というのは、減量を踏まえながら検討する課題であるという方向もいろいろなところで見えているんですけれども、そういうところでは平成１８年以降の報告というか、品川区としてどう考えていくのかという先のことなんですけれども、どういうイメージを持っているのか。これだと平成１８年までに向けて、全部が報告事項ではないということにもなりますか。","respondent":"中山清掃リサイクル課長","answer":"要するに、各区で当然基本は考えていくことですけれども、その際に２３区の地域性とか沿革を踏まえた検討を整理していこうですから、品川区の方針としては、以前からいずれ費用負担の問題というものは避けて通れない検討課題という認識は持ってございまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田委員","kind":"質問","question":"幾つかお伺いをしたいと思うんです。１２月にまず区長会より下命があったということです。助役会の身分ですけれども、さまざま１番から９番までになるんですが、一度平成１５年７月に助役部会から報告書が出て、これがお蔵入りになった。下命事項が違うんだよ。それは安定的な処理体制が可能となる地域ごとの設定というような形のものが出されお蔵入りになってきた。","respondent":"中山清掃リサイクル課長","answer":"今後のスケジュール的なものは明確に認識してございませんけれども、月に状況によって何回開いて、これは平成１６年度のできるだけ早い時期に、少なくとも検討部会としての方向性は出していくということだというふうに伺っております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田委員","kind":"意見","question":"そうしますと、私も資料を持っていますが、これがある程度検討課題であると。その辺のところも、下命事項のところで特に１番なんかはあるわけだけれども、その辺の意味合いというのはどういうふうに考えて下命されて進んでいくことになるのかという考え方の問題です。","respondent":"中山清掃リサイクル課長","answer":"その際、清掃一部事務組合の抜本的な改革を行い、効率的・効果的な運営を図るべきであると考える」ですので、これは当分の間という注釈がつきますけれども、一部事務組合による共同処理を行うにあたり検討整理していく課題がこれだけあるですので。","voiceIndex":11,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"基本的にいただいた資料は、品川区の中山課長が整理してつくられたものなのか、どこにあって今我々に見せてくれているのか、全体的なものを教えてください。","respondent":"中山清掃リサイクル課長","answer":"これは区長会より平成１５年１２月８日ですけれども、助役会清掃事業検討部会に下命された資料そのものを、資料の表示だけ清掃制度特別委員会の資料に変えさせていただいてお配りしたというものです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そうすると、１８番以降の協議会に下命したというのはおかしい話じゃないですか。協議会というのは区長がメンバーでやるもので、区長から協議会に下命ということはおかしい話で、その辺の説明をしていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"したがって、今申し上げたのは、まず最初の助役会のスケジュールの１２月の資料で、その内容で同じ助役ですけれども、協議会幹事会長という名前においてもう一度清掃部長会長、それから今度はしばらくおいて部長会より清掃課長会に下命されているという手順を取ってあります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"ということは、協議会の中の下部組織と言ったらいいのか、実務レベルに検討しなさいと幹事会長から来たあるいは管理者なり何なりから来た、そういう形なの。それならわかりました。それで、個々の話はやっていくと切りがないから、２４番の覚書と規約附則の取扱いについて検討を協議会で始める。これもまた下命するのかな。区長たちは何にも考えないで、みんな任すのかね。","respondent":"中山清掃リサイクル課長","answer":"２４番につきましては、先ほどもご説明したとおり、これは組織体に下命することなく、本来は２３区の区長と清掃一組の管理者たる区長、２４の構成体の代表である２３区長が２３区長出席の協議会において検討するということで、これは下命されません。","voiceIndex":17,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、まず覚書ということは、もう既にとらわれないということになっているわけでしょう。それを今さら何を取扱いを協議するのかと。それから、規約附則の取扱いについては、平成１７年度末というのを抹消するという意味なのか、それとも平成１７年度末というのは、あくまでも附則だからここにつけておいて、そのままいくというようなことを検討しようとしているのか、推測で結構ですから。","respondent":"中山清掃リサイクル課長","answer":"まさに今林委員がおっしゃった後段の、今回の区長会決定は附則第２条の表現からいいますと、一つ新たな方法の決定をしたということで、そこで従来の覚書と附則と今回の決定を踏まえたものを、ある種の方向性の転換された部分についてどのように扱うか。","voiceIndex":19,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"去年の１１月、１２月にそういう判断をしたというのは、この２４番を協議会で議論をした後に出てくる、どういう結果かわからない、今回みたいに平成１８年度以降も引き続きやるという結論を導き出すための会議検討が、まさにこの２４番じゃないのか。本末転倒で、延ばしておいて、さあ、やりますよというのは順序が逆だと思うんだけれども、思わないですか。","respondent":"松本環境清掃事業部長","answer":"難しいお話なんですけれども、現実的には区長会としては方針を出された。ただ、これは正式には協議会の扱いの事案です。そういう意味で、ここでもう１回整理するというお話ではないかと私は思っています。","voiceIndex":21,"id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"じゃ、協議会から区長会に抗議をすればいい。まさに、清掃一組のことを協議する。冒頭に出てくるのは「平成１３年３月に助役会に対しもろもろ検討を下命した」と書いてあるんだけれども、じゃ助役会は平成１３年４月以降、安定的処理について助役会として会議が開かれているとしたら、いつ何月に開かれたかを、もしわかるなら教えてほしい。わからなければ、助役に聞けばいいと思うんだけれども。","respondent":"中山清掃リサイクル課長","answer":"ご質問は区長会よりも助役会に地域処理を検討する下命がされて、それについてまた指定会議体たる部長会、課長会で検討を挙げていろいろな案を持ち上げた部分です。その後の助役会における検討の……。","voiceIndex":23,"id":"exchange-010"},{"speaker":"林（宏）委員","kind":"確認","question":"区長会がやったのは、ほんの３カ月、平成１５年の何月からが、今度７月に上げたわけだから、課長会、部長会、それから助役会で上がってきた会議の開催された日取りを今日は無理だろうから、次までに資料として出してください。この言葉使いでいくと、永久に平成１８年度以降、解散しないほうがいいというふうに取れる。これは区長会の事務局から出ているんだけれども、この文章について確認してくれますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"そうなってしまうと、最初の自区内処理の原点は一体何だったのか。さらにおいては、地方分権一括法で決められた、本当の地方分権というのは何だったのかということ。なぜ、この覚書が崩れてきてしまったのかということ。基本的なことかもしれないんですけれども、教えていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"これを自区内処理というふうに定義されてきたわけです。今回の地域処理を報告するにあたって、前提は自区内処理が実現できるまでの計画としての地域処理、ブロック処理の検討ということで、先ほど林委員からもご説明のあった報告、その後の動きとなってきたわけです。","voiceIndex":28,"id":"exchange-012"},{"speaker":"大沢委員","kind":"質問・要望","question":"そうしますと、原点に戻るんですけれども、先ほどの林（宏）委員がおっしゃった当分の間ということは、非常に抽象的なあいまいな言葉で、こうなっちゃうと平成１２年に地方分権一括法で地方自治を確立するという意味合いで、清掃一組の解散によって初めて、し尿等という部分的な処理のあれはあるんでしょうけれども、何かそこの部分からだんだん時間を置くごとに紆余曲折してしまって。","respondent":"中山清掃リサイクル課長","answer":"その中でも温度差と申しますか、各区におけるその辺のとらえ方の問題を感じつつ、とりあえず少なくとも下命を受けた課題についての検討作業を進めようということで、幾つかのブロック案の作業を挙げていったわけです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"大沢委員","kind":"質問","question":"そうすると温度差ということで、非常に主観的になっちゃいますけれども、２３区のうち２２対１ぐらいの感じで、清掃制度に関する意識の差が他区と本区では違う部分があるんでしょうか。","respondent":"中尾根企画部長","answer":"したがいまして、もう一度転換がある。先ほど言った自区内処理の問題ですけれども、このときには、その議論の中では明確に各区に一つずつ工場があって、きちんとできるのが自区内処理だという認識はまだ固まってはいなかったんです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"本田委員","kind":"質問","question":"これから逐次当委員会では報告を受けながら、また議論もするんだろうというふうに思うんです。１１月の区長会の決定以降、新たな進展がないということでありますけれども、これから大変大きな問題、項目もありますけれども、詰めていく中で、そこのところはぶつかり合いになっていくんじゃないかなと思うんですが、その辺のご認識をお聞きしたいと思うんですけれども。","respondent":"中山清掃リサイクル課長","answer":"ですから、東京都がここの部分について何かをしなくても、私どもの耳に入る中で、動きをしてきている結果としてこうなっているということはないというふうに認識していますが。","voiceIndex":34,"id":"exchange-015"},{"speaker":"本田委員","kind":"質問","question":"その辺は、すごくお答えできないんですよね。都と２３区特別区との対立よりも、今のようなお話ですと、２３区間の中の隘差がいろいろとある。確かに、工場のない区にとってみれば、安定してごみ処理を続けていくためには、間違いなく処理してもらえるんですねと、工場を持っているほかの区に依存をしなくちゃならないわけですから、いろんな不安はあるのは理解できますね。","respondent":"中尾根企画部長","answer":"これは確実です。ところが、お金の問題は、財調を中心とした議論で、２３区側がはっきり主導権を取らない限り、都の内部的団体から独立できない。","voiceIndex":36,"id":"exchange-016"},{"speaker":"本田委員","kind":"質問","question":"しかも、平成１８年度から新しい体制になっていくわけですから、そんなに時間的な余裕があるわけではない。先ほど、第３ブロックは大体意見は一致だというような抽象的なお話がございましたけれども、２３区が課題は同じですから、課題に対してどういう対応、意見を持っているのか、その辺は明確にならないんですか。","respondent":"松本環境清掃事業部長","answer":"そういう意味で、その部分が２３通りを一つにまとめることがなかなか難しいのが現在の状況です。","voiceIndex":38,"id":"exchange-017"},{"speaker":"本田委員","kind":"質問","question":"そういうものも議会に提供していただいて、理解と議論がよりスムーズに行くようにお願いしたいなと。今お話しを伺って課題はよくわかりましたので、そのようにお願いしたいと思うんですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問","question":"本田委員の話に係わった後で、今の２３通りというのは間違いだと思う。だから、はっきり工場のない６区については、特に新宿区あるいは文京区、真ん中の区は存続ですから。でも、さっきから言うように、はっきりその区は現段階では存続を主張しているわけですからね。そういうふうに変わったのは、どこが議論して清掃一組の政策で２３区に通達をされてきたのか、ちょっと古い話なんだけれども。","respondent":"中山清掃リサイクル課長","answer":"しかし、これは委員会の視察のときにもご説明申し上げましたけれども、区としては、そうは言ってもスラグがすべて市場に流れ、公共工事等に使われ、全く埋められないという保証は現段階でないので、もちろん最大限努力はするわけだけれども。","voiceIndex":41,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、清掃一組を平成１７年度末に解散に向けての一つの大きい準備が、安定的処理という言葉の中に灰溶融施設の整備というのがあった。平成１７年度末に向けて大井工場も灰溶融施設をつくる。それが平成１７年度末へ向けての大きいハザードだったわけですよ。平成１７年度末というのを見直すなら、あの土地問題ももう一度元へ戻してほしい。あれは絡んでいたわけですから。","respondent":"中尾根企画部長","answer":"ただし、役割そのものはいささかも軽んじられてはならないと思うし、もしそういうことになれば、まさしく同じように元に戻せという主張も本当にしなきゃならないかと思いますが、認識はそのようにしています。","voiceIndex":43,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"確認","question":"いわゆる１０分の１以内が１００分の１以内と、その容量が減る。だからもう一度、がらがらぽんというわけにはいかないだろうけれども、それは江東区長に厳重に伝えるべきだと思うんです。あのときの品川区の譲る精神を無視したような、突然の区長会の１１月の確認発表というのは、非常に心外だというふうに思いませんか。","respondent":"中尾根企画部長","answer":"まさしく私も非常に心外でありますし、当の交渉していた一人からすると、これは一体何なんだという思いはあります。やはりそこのとろはどういうものの機能と今後どういうふうになるのか、これは冷静に見る部分は冷静に見ていきたいと、このように思ってあります。","voiceIndex":45,"id":"exchange-021"},{"speaker":"土井副委員長","kind":"質問・要望","question":"確か今年から区が採用して派遣をする。しかし、その間にも採用がどうなったかということで伺ってみると、具体的にはあまり新規採用という形のものはなかったやに聞こえてきているんですけれども、そのためには例えば新規採用という形で今やろうとすると、この課題の中の１０番に書いてあるところが決まっていないものは採用しようがないということになりますね、条件が決まっていないんですから。","respondent":"桑村人事課長","answer":"区の職員は区の給料の決定をしていくわけですけれども、現実は同じところで働くということで、給料の金額的なものが違いが出てくるのではないだろうかということを検討することがあって、正直言いまして、平成１５年度と書いてありますけれども。","voiceIndex":47,"id":"exchange-022"},{"speaker":"土井副委員長","kind":"質問・要望","question":"あっちでいいのをとったよ、こっちはまずかったよとか、そういう話になかなかならないだろうと思う部分もありますから、したがってその辺の２３区全体の足並みというようなものは、あるいは交渉するというか、話し合いをする相手方というものは統一された形でなっているんでしょうか、情報がありましたら聞かせてください。","respondent":"桑村人事課長","answer":"その意味で、正直言いまして、今統一で交渉をやると、来年９月までの一定の結論を待って、各区も対応したいというのがほかの区の考え方じゃないかと思ってあります。","voiceIndex":49,"id":"exchange-023"},{"speaker":"土井副委員長","kind":"意見","question":"今、お話があった中の、最終的には区の職員になるわけだからという部分と、区の職員の団体というのが入っている人、入っていない人、あるいは二つあるところがあるのかどうかわかりませんけれどもさまざまな状況がある。品川区の場合は、前々からいろんな意味での話し合いのルート等を含めてあるのかもしれませんけれども、ほかのところはどうなっているのかなと。同じように足並みがそろっているのかなと。","respondent":"桑村人事課長","answer":"そのベースがある程度話し合いがないと、区の職員から清掃業務に従事したときの勤務条件が決められたのがないというのが一つの考え方の一定のベースになってまいりましたが、その意味では両者と交渉するというのが各区のスタンスになっているだろうと思います。","voiceIndex":51,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5630#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=12&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":27636,"voices":59}},{"id":"h16-20040122-16","meetingId":"h16-cm01","date":"2004年1月22日","dateIso":"2004-01-22","committee":"街づくり特別委員会","time":"午後１時０５分～午後２時１１分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今回の土地取得のための裁決申請というもの、この中身をもうちょっと詳しく教えていただきたいなと思います。土地収用法に基づき、裁決申請および明渡申立裁決申請を行ったということがあるんで、この具体的な、どう進んでいくのか、期間的なものも含めて内容を教えていただきたいと思います。","respondent":"中島街路事業担当課長","answer":"その後、その結果、もちろん審議の内容等も加味しまして、現在の予定では、６月の末から７月の上旬にかけて裁決申請がされるというふうに、スケジュール的にはこのくらいのスケジュールでいくんではないかというようなことで収用委員会から説明を受けてあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４年間工事が遅れているというところでは受けとめますけれども、私はこの間の地権者の皆さんと区との話し合いがもっと十分にできなかったのかなと。土地とか建物、物件に関しての調査が行われたわけですけれども、その後の経緯をちょっと詳しく、調査に入った後、この間の申し立てまでの間にどういうことが起こったのか、双方でどういう話し合いが行われていたのか、ぜひお話をしていただきたいと思います。","respondent":"中島街路事業担当課長","answer":"先ほど申し上げました収用委員会に裁決申請を出しまして、とにかく裁決が出た後、出たとすれば、その後明け渡していただくというようなこともありますので、その辺の期間を考えると。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"幾つも案が出されていた。これは去年の５月なんですけれども、こういうことが具体的にどうやりとりがされているのかというところをまず一つお伺いしたいんですが。ここのところを地権者の方が希望されているということもあって、今のようにここを取得するために最善を尽くしますとまちづくり事業部長が答えていらっしゃるんですが、この辺は現在どうなっているのかというのをまずお伺いしたい。","respondent":"中島街路事業担当課長","answer":"現時点で少しずつ、少しずつですけれども、進んできてあります。具体的に東京三菱銀行の再建、要するにここを処分した後の今借り入れをしていますけれども、その後の再建策について、東京三菱銀行は具体的な検討に入ってあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"少しずつ進んでいる。可能性があるということは、まだ話し合いの余地があるというふうに受けとめていいのでしょうか。私はここの地権者の方たちは出なくてはいけないのに、なぜここの東京三菱銀行のところだけが残されてもとのまま営業ができるのかなという不信は、この地域の方はだれも持っていらっしゃると思うんですが、その辺のことと２点、お答えをいただきたい。","respondent":"中島街路事業担当課長","answer":"それと先ほどちょっと裁決申請のお話をさせていただいたときに、ちょっと説明不足だったところがあるんですけれども、私ども裁決申請を出しましたけれども、これは事業の関係でぎりぎりのところで申請したわけですけれども。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"意見","question":"そういった面では、地権者の方から区長あてとまちづくり事業部長あてに意見書が出ていますよね。その中身といったら、今言った２点なんですよ。それに対して回答が来ていないというお話だったんです。だから、その点、その大事な２点に対してどういう見解を持っていらっしゃるのかというのと、なぜ回答が出ていないのか、ちょっと疑問なんですけれども。","respondent":"中島街路事業担当課長","answer":"１点目の代替地の問題と仮営業の場所等につきましては、今私どもで代替地という部分では、具体的に検討できているのは、この東京三菱銀行の跡地、これが一番有力です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すみません。営業ができる場所を求めていますよね。これは同じような文章なんですけれども、実際的には、「私たちが現在営業し、居住し、所有している土地および建物を速やかにお譲りできるように、現在の場所に見合った代替地と担当者の心ある対応を願っています」と書いてある文書を区長あてに出されているので、やはりこれは当然回答が必要であるかと思うんですが、いかがでしょうか。","respondent":"中島街路事業担当課長","answer":"そういった部分では、その場で直接区長あての文書とまちづくり事業部長あての文書とは同趣旨だと基本的には考えてありますので、その場でお答えをしているということで、文書での回答はしてこなかったです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でも、今までどういう状況だったのかなと詳しく出てこなかったわけですけれども、何か示されたのが上野駅とか、五反田駅とか、とても移れない状況であったということと、とにかくそこを明け渡してほしいんだという地権者の皆さんにとっては代替の案がほんとうに乏しい中に、とにかくどいてほしいんだという、言ってみたら、強制的なところをすごく受けているというところで。","respondent":"中島街路事業担当課長","answer":"駅前広場事業の変更ということでしょうか。武蔵小山駅前事業の変更ということでございましょうか。","voiceIndex":17,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"平成１３年と１５年の変更内容、事業計画変更、認可の内容というのは何なんでしょうか。","respondent":"中島街路事業担当課長","answer":"平成１５年ですか。","voiceIndex":21,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"これは全体のことなんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"意見","question":"都市計画事業の認可の告示の年月日というところに、平成７年１１月２０日、その後、平成１３年７月１６日と１５年３月３１日に事業計画変更認可が出ているので、この中身、今日は駅前広場のことなので、駅前広場と係わっているのかどうかということと、駅前広場の計画の詳細はこれから図面が引かれますよね。だから、詳細がこれからということなんですけども、その中身の変更がどれくらい可能なのか。","respondent":"中島街路事業担当課長","answer":"平成１５年３月３１日の事業変更は、これは昨年もご説明させていただきましたけれども、事業認可期間が平成１５年３月３１日までです。この事業期間を４年間延長するということで、これは連続立体交差事業もあって４年間延長したわけですけれども、その事業期間の変更です。","voiceIndex":28,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど東京三菱銀行の跡地の問題が出しましたけれども、ここは引き続き地権者の皆さんがもし要望されたときは可能性が残されているのかどうかが１点と、あと、引き続きほんとうに切なる願いである代替地の確保、先ほど和解という言葉が出されたので、ぜひその辺を追求していただきたいというか、引き続き誠意を持ってやっていただきたいと望みますけれども、その点について。","respondent":"中島街路事業担当課長","answer":"そういった意味では、少しずつ代替地取得に向けて動いて、地権者の方が満足していただける内容になるのかどうかは、東京三菱銀行がはっきりしないところはあるわけですけれども、そういった代替地の取得に向けて引き続き努力してまいりたいと考えています。","voiceIndex":30,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"より一層のご努力をお願いして、いい方向に進みますようにお願いして質問を終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-012"},{"speaker":"藤田委員","kind":"質問・要望","question":"買収の件につきましてはよくわかりました。ぜひご努力いただきたいと思います。昇降機のほうなんですが、これは利用者の切なる願いでずっとやってきましたけれども、いよいよ１月２７日に上り、２月７日が下りということで設置されました。駅を私見てきているわけじゃないんですが、要するに稼動しますよという何か皆さんにお知らせみたいなものは駅に張ってあるんでしょうか。","respondent":"中島街路事業担当課長","answer":"できますというお知らせはしているかもわからないですけど、設置日が若干少しずつずれてきているところがありますので、東急電鉄としても日にちを、何日というのはまだ言えない部分もあるのかなというふうに考えてあります。","voiceIndex":33,"id":"exchange-013"},{"speaker":"藤田委員","kind":"質問・要望","question":"ぜひお願いしたいんですが、２７日ですから、あと四、五日ぐらいですね、今日２２日ですから、もうここまでやってあるのであれば、あとは書いて張るだけですからね。これは簡単なことだと思うんですよ。ぜひ連絡をしていただいて、皆さんに、とにかく稼動しますよというお知らせをドーンとやっていただきたいと、こう思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"要望じゃないんですけど、これはまさに報告事項にあったように、武蔵小山駅周辺の「用地買収の進捗率は６３％」となっているんですけど、「７４％」ですよね。その確認をぜひお願いします。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、これは東京都に対しての要望ではないんですけど、品川区に対してなんですけど、防水板の設置助成が新築の住宅は除くということになったと思うんですけど、それに対しても、わからないで購入するという方もたくさんいらっしゃいますし、また、この間、防水板で浸水被害を食いとめられているという方もたくさん出てきている部分もありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"それで、一応原則は今それはできていないということで、ただ戸別によっては置いている方もいるみたいなんですけど、そういうことも、希望者には配付するようなことを考えていただいたらどうかなということを要望として、その２点、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自民党として意見・要望は後ほどまた伊藤委員のほうから話しますが、そのちょっと確認なんですが、他区で「洪水ハザードマップ」というのを出しているところがあると思うんですが、品川区の対応というのはどういうふうに考えているのか、そういうのを品川区の中で考えていらっしゃるのかどうか、そこら辺からまず教えていただければと思います。","respondent":"矢部下水道河川課長","answer":"その場で、今進捗状況がどうなのか、今後のスケジュールはどうなのか、その辺の話があるかと思います。それを受けて、品川区がどういうふうに対応するか考えていきたいと考えています。","voiceIndex":44,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ハザードマップ自体は、どこが水害に遭うかというのが出てくるような書類になっているんですか。","respondent":"矢部下水道河川課長","answer":"東京都のほうで浸水予想区域図というのをつくりまして、これは平成１２年の東海豪雨、ございましたね。名古屋のほうで何万世帯という形で浸水が起きた。","voiceIndex":46,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"主としては、被害が出るというより避難経路が中心になっていくというふうに、こういうものをつくった場合に、これからつくるかどうかちょっとまだわからない状況だと思うんですが、避難用ということが目的、まだわからないけど。","respondent":"矢部下水道河川課長","answer":"最初にハザードマップ、浸水予想区域図、ハザードマップをつくるという経緯は、今河川にしても下水道にしても、浸水対策を進めております。","voiceIndex":48,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もし、つくるとしたら、そこら辺までできれば、そういうものが出てこないと、ただつくっただけ、避難は避難ということでいいんですけど、変なあおりにならないようにということを考えてもらいたいなということです。もし検討してくれれば、そこら辺も考えてもらいたいなと思う。今度の要望のまとめに入れるかどうかというのは、また、ちょっとこれからうちのほうでも考えなきゃいけない部分だと思います。","respondent":"矢部下水道河川課長","answer":"鈴木（真）委員ご指摘の部分につきましては、これまで新宿区とか文京区とか、いろんな区で公表してきておりますけれども、公表に当たってのやっぱり検討課題でありました。","voiceIndex":50,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"それぞれ地域の中で具体的な事業を今展開されることも必要でしょうし、さらに前進していく必要があるというふうに思っておりますので、私たちのほうとしては、品川区議会の特別委員会として、どの地域を優先しようとかではなく、むしろ品川区全域のことを考えて、それぞれの地域のすべての皆さんが区民なわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"提案","question":"計画を早くしろとか促進せよと出されるのは簡単だと思うんですよ。ですから、表現の仕方の問題、これは正副委員長にお任せいたしますけど、ある意味では世界的な例えば地球温暖化とか、そういう時限になっていくような話だと思われますので、これを例えば品川区でどうするんだとか、東京都に対してどうするんだという思いがありますので、文言の調整をぜひお願いしたいという指摘が昨日ありました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-023"},{"speaker":"藤田委員","kind":"質問・要望","question":"その点、よろしくお願いしたいと思います。ですから、今その坂を通じて、下のほうはかなり被害があります。周知とともにやっぱり対策ですね、排水口というんですか、あれをつけるなり何らかの対策があってしかるべきではないか。ですから、坂道、急傾斜地、この対策をぜひ図っていく必要がある。そのほかについては、１年間よくやってきましたので、これをベースにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6268#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":19820,"voices":60}},{"id":"h16-20040123-14","meetingId":"h16-cm01","date":"2004年1月23日","dateIso":"2004-01-23","committee":"行財政改革特別委員会","time":"午後１時０５分～午後３時１１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査を行いたいと思います。 行財政改革に関することのうち、議員定数に関すること","agenda":"特定事件調査を行いたいと思います。 行財政改革に関することのうち、議員定数に関すること","exchanges":[{"speaker":"川西副委員長","kind":"意見","question":"聞き漏らしたことかもしれませんが、この２３区議会費比較というところで、一般会計の割合といいますか、これが非常に高いところは何か特徴的にあるのかどうか。","respondent":"福田区議会事務局長","answer":"例えば政務調査費を含まないというようなところもありますが、豊島区などにつきましては、含むところとほぼ同数の０.６％の割合というようなことも見られますので、ご質問の趣旨にかなうような分析が、なかなかこの数字からは読み取れないかなというふうに考えております。","voiceIndex":7,"id":"exchange-001"},{"speaker":"塚本委員","kind":"確認","question":"はっきりと特徴が読み取れると思います。それで、そういう答えが正しいんだろうと思いますが、品川区の場合は、平成１５年度で０.６と０.５、大きな違いのように見えますけれども、これは予算規模が膨らんだのと、おそらく欠員の関係ではないかと思って見ていますけれども、それを確認です。","respondent":"市岡企画財政課長","answer":"予算の段階では欠員は折り込んでおりませんでしたので、これはやはり塚本委員がおっしゃったように相対的に財政規模が大きくなったので、０.１ポイントですけれども、小さくなったということだろうと思います。","voiceIndex":9,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"先ほど講師の先生が議会の不信ということを言われたんですけれども、品川区の世論調査みたいなもので、何かとったものはあるんでしょうか。議会に対して区民がどう考えているのか。もしあったら教えていただきたいというふうに思うんですが、ないでしょうか。","respondent":"中尾根企画部長","answer":"記憶にある範囲の中で、議会について世論調査等の対象にはちょっとしておりませんので、ずっと古いのは記憶にはないんですけれども、この段階ではありませんので、後で調べておきます。","voiceIndex":11,"id":"exchange-003"},{"speaker":"塚本委員","kind":"質問","question":"ただいまいただいた資料の組織職員数比較のところでお尋ねしたいんですが、品川区と比べて、宮崎市とか明石市とか、同規模、予算規模もそう変わらないところで職員の数が著しく違っておるところが市（区）長部局というところが相当違うんですけれども、これは、これだけ違うというのは、何か特徴的な分析というのがなされてると思うんですが、いかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"ここで委員ご指摘のように、おおよそ１,０００人ほどの違いがあります。","voiceIndex":13,"id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"ということは、宮崎、明石のほうが一般的で、品川区のほうが突出してそういう事業に人を配置しているというふうに理解していいですか。","respondent":"榎本行財政改革担当課長、市岡企画財政課長","answer":"児童センター関係に関しても、かなり数が違いが見られるということで、そういった意味で、サービス全般が高水準にあるという形が言えると思います。サービス水準そのものがどうかというのは、なかなか比較が難しいんですが、一つ言えることは、例えば保育所ですと、公立保育所ではなくて、私立保育所が主流で、むしろ公立保育所はそれを補完する程度の数しか設置をしていない。","voiceIndex":15,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"私が質問したのは、地方の中核都市ですよね、比較して例に出しているのは。それは、こういうあり方が一般的で、品川区がそれと比較して違っているのは、こことここが違うんだよと先ほど指摘されましたけれども、品川区の特徴であるのかということを聞いているんです。","respondent":"市岡企画財政課長","answer":"品川区だけではありませんが、大都市型の行政サービスの自治体の特徴だということは言えると思います。","voiceIndex":18,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"無理なこじつけなのかもしれないですけれども、一時的に区民の皆さんの関心が若干でも高まったのかなということが１点と、それから第２に、この間でも平成７年、平成１１年に不幸にもお亡くなりになられた方とか辞職された方がいましたけれども、現状、現在の４２名にこだわらなくても議会としては運営できるのかなというような、そういう実績を踏まえましたら、今回、議員定数が削減ということで。","respondent":"福田区議会事務局長","answer":"しかしながら、昭和３４年対３８年を比較をしてみますと、定数４の増に対して、再選数につきましても５２％から５８％へ６ポイントの増ということでありますので、この表からは、直ちに両方の要因を関連づけることは難しいかなというふうに考えております。","voiceIndex":21,"id":"exchange-007"},{"speaker":"中島委員","kind":"質問","question":"であるならば、その中でいかに自分が議員として区民の方の役に立つかということも一つの視点であるし、それから、こうして今さっきいろいろ挙げられた、確かに個人企業であるけれども、私たちは区民の皆さんのためにここへ来ているわけですから、これを活性化するにはどうしたらいいのかということもそれぞれ検討の中に入れていくべきじゃないかなと、そこには定数削減という一つのものをおきながら、じゃあ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"できれば、日を改めた機会でできるならば、自分の意見を率直に言ってもらう。そういうような機会があると、また別の意味で勉強になるんじゃないかというふうに思います。ちょっと制度的にそれは無理なのかどうなのか。予算措置だけの問題なのか、地方自治法上、そういう参考人みたいな人にお越しいただいたときに、一定のかかった交通費、経費ぐらいは払えるような、そこらはいかがなんでしょうか。","respondent":"福田区議会事務局長","answer":"これは、例えば議員研修会にお招きをする講師の先生にお支払いをするというような形での支出は可能でありますので、そういう意味で、委員会活動に対してそれを充当するかどうか、こういう問題はありますけれども、私どもの気持ちを示すような財政的。","voiceIndex":25,"id":"exchange-009"},{"speaker":"高星委員","kind":"提案","question":"ただ一方では、僕はやっぱり一番心配しているのは、議会が本来は区民サイドに立ったチェック機能をきちんと有していなきゃならないのに、逆に行政執行部のほうが対区民との間の一つの仲介業みたいであるというようなこともなきにしもあらずというふうに思うんで、僕はこの際、やっぱりトータル的に、マクロ的に考えて、やはり議員定数削減と。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですけれども、その前に、議員として皆さんが今大変な局面にある中で、１事業者として考えましても、やはり我々が率先して、品川区は議会として議員定数を減らしましたよ。これは議員定数の削減ということで私も委員会に出席していますので、その辺をもう一度皆さんに考えていただきたいなと思います。","respondent":"中尾根企画部長","answer":"先ほど沢田委員からのご質問で、最近世論調査等で議会のことを調べたことがあるかということで、記憶にないとお答えしましたけれども、今調べてもらって、平成６年、ちょうど１０年前に世論調査を議会に関してやっております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"私の意見としてなんですが、先ほど高星委員のご意見の中で、ちょっと私は違う受けとめ方をしてしまったんですが、助教授が委員会の数を現状のままで、委員会の数を増やすことで一つの委員会に出席する議員数を減らして、そこで、より専門性をその中でということなんですが、私が受けたのは、まずはトータルの議員定数を削減して、それで削減した中で、委員会の数は維持していれば。","respondent":"福田区議会事務局長","answer":"品川区もそれと同じように５常任を設置をしているということであります。したがいまして、議員の総定数との関連は、法的には見受けられません。さらに申し上げれば、品川区が条例で５常任を４常任にする、あるいは６常任にする、いずれも可能だというふうに考えております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"品川区の議会費が０.６とか０.５のパーセンテージ、これが２割増減しても、ほとんど数字にあらわれないような全体の数字なわけですから、予算規模に対しては。ですから、その相関関係はほとんどないというふうに私は考える。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"山村委員","kind":"質問・要望","question":"基本的に助教授も選挙の受かる、受からないというところまでは考察しないでお話をなされていると思うんです。それは、先生は確かに助教授ですから、机上の理論としては寸分違わないところがあると思いますが、また我々は議員のプロでありますので、机上の理論ではなく、それに補完する知識ですとかそういうものを考慮してから、議員定数どうこうということも考えるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"南委員","kind":"提案","question":"さっき平成６年にとったアンケートの紹介がありましたけれども、それを伺っていてちょっと感じたんですが、やはり区民というか、住民の方たちの政治参加、政治意識、議会への信頼性を高めるという努力をみずからしていかなくちゃいけない部分もあるんだろうというふうに思うんですよね。委員長への委員会運営のお願いも含めて意見として申し上げたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"委員長が補足してくれるかと思ったんですけれども、現状で委員会の開催時間を夜間型にすることが可能かどうか、確かめておいたほうがいいんじゃないかなと思って、老婆心ながら質問します。","respondent":"福田区議会事務局長","answer":"それで、大変失礼な申し上げ方かもしれませんけれども、そういったことについての検討について、議会の中でのご議論が必要だろうというふうに、かよう思っております。","voiceIndex":37,"id":"exchange-016"},{"speaker":"三上委員","kind":"意見","question":"そういう昼間だから、夜だからということではなくて、こちら側のどういう働きかけをするかということが、これが大事なんです。それが活性化じゃありませんか。それから、そういう議員定数の問題とかという、減らす、減らさない、これはただ減らすということについて決めればいい話であって、活性化とかと何とかということと切り離すということだったら、それはもう全く切り離して考えるべきである。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-017"},{"speaker":"沢田委員","kind":"意見","question":"そうなれば、議会がほんとうに１,３００億円のお金を区民の願いに沿って出して、区民の意向が反映されたものになっているかどうかという、このチェック機能が果たせているのかどうなのかという観点が議員の定数を考えるときに大事なので、私は経済的に厳しいからというだけでやっていけば、際限なくこれを削ることになれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-018"},{"speaker":"須藤委員長","kind":"質問・要望","question":"その他の項で何かご発言ございませんでしょうか。なければ、私のほうから次回の予定についてご案内をさせていただきたいと思います。次回は３月４日ですが、電子区役所に関することにつきまして、既に皆様方からいただいておりますご意見を正副でまとめさせていただいたものをご提示させていただいて、ご意見をちょうだいしてまいりたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5744#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":18286,"voices":42}},{"id":"h16-20040227-3","meetingId":"h16-c-budget","date":"2004年2月27日","dateIso":"2004-02-27","committee":"予算特別委員会","time":"午後４時５１分～午後５時０２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"共産党の鈴木ひろ子です。ここでは、自分では質問ができませんので、皆さんにぜひとも活発な審議がいただけますように努めてまいりたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=818#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":2839,"voices":19}},{"id":"h16-20040301-6","meetingId":"h16-cm03","date":"2004年3月1日","dateIso":"2004-03-01","committee":"区民委員会","time":"午前１０時０４分～午後２時４３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１４号議案、品川区印鑑条例の一部を改正する条例","agenda":"第１４号議案、品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"ちょっと勉強不足なんですけれども、性同一性障害者ということは、どういう方を言うんでしょうか。","respondent":"冨田戸籍住民課長","answer":"これにつきましては、品川区だけではなくて、全国の各自治体におきましても、同様なご要望なり、ご要請があって、それなりの対応をしてきているのが実情と聞いております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"今回、条例のここの部分での改正ですけれども、区政全般に対して、性同一性障害者に対する対応というのは、どういうふうな見解で臨もうとしているのか、全般的なことをちょっと伺いたいと思うんです。教育行政の部分ですから、ここではお答えにくいと思いますけれども、品川区が全体的にどういう対応をするかというところだけでも、区民生活事業部長がおいでですので、ご答弁をいただきたいと思います。","respondent":"太川区民生活事業部長","answer":"今回、条例の改正に至ったことにつきましては、いわゆる性同一性障害者の性別の取扱いの特例に関する法律というのが、国のほうで可決されまして、区もいち早くそれに対応するということになろうかと思います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"品川区は男女共同参画社会を進めていくということで、かなり高らかな考え方を持って行政を進めている区ですから、そういう区として、やっぱり細部にわたった対応がきちんと示されなきゃいけないと思いますので、あえて、ちょっと問題として取り上げて、全庁的に進めていけるようにはからっていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中副委員長","kind":"確認","question":"今回、印鑑条例の改正でこの対応をとるわけですが、今、区民生活事業部長のご答弁で少し触れられておりましたけれども、今後の条例対応といいますか、他の部分でも、申請の際に男女を明記しないようにされるものもあろうかと思いますが、区民生活事業部長のご答弁にもありましたけれども、ほかにある中で、なぜ今回は印鑑条例だけを取り上げられたのかというところを確認したいんです。","respondent":"冨田戸籍住民課長","answer":"そのうち、法律政令等で表記が必要なもの、あるいは、事業の実施の上で性別の表記が必要なものを除くと、約６０件ほどが削除可能であろうということで、新年度に向けまして、今、各所管で準備を進めているところです。印鑑条例はその一つということです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中副委員長","kind":"確認","question":"そういう意味で、今後のほかの部分での対応の考え方を、改めて確認をしたいと思うんですが、まさにこういう障害を持たれた方の人権に、当然配慮しなくてはいけないわけですが、全国的に２,２００人から７,０００人の障害者がいらっしゃるということで、当然、そういう方のお気持ちに配慮していかなくちゃいけないと思いますが、こういう登録申請をするような手続のものに対しては、例えば場合によっては。","respondent":"冨田戸籍住民課長","answer":"本人確認をする際に、男女の別というのが必要かどうか、そのあたりは、私ども検討させていただきましたけれども、ご本人の確認は、原則的に言えば、申請をいただいて、その場での本人確認ができれば、即時交付しますけれども、できない場合については。","voiceIndex":13,"id":"exchange-005"},{"speaker":"田中副委員長","kind":"確認","question":"今、法律で対応が必要とならないものが残り約６０件あるということですが、最初のご説明では、機械的対象外が６０件ですから、すべて自動的にこの項目を削除するというニュアンスで受けとめてしまいましたが、決してそうではなくて、その中でもまたさらに、ほんとうに必要なのか、必要でないのかを確認した上で、それぞれ個々に対応していくという考え方だということでいいんでしょうか。","respondent":"冨田戸籍住民課長","answer":"先ほどもちょっと触れさせていただきましたけれども、１,０００件弱の申請書等の書類の中に、性別の表記を求めているものが２４０件ほどあります。そのうちいろいろ検討いたしまして、必ずしも性別の表記が必要ないであろうと思われるものが６０件ほどあるです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"木下委員","kind":"質問・要望","question":"先ほど、性同一性障害で悩んでいらっしゃる方が２,２００人から７,０００人というお話をされたと思うんですけれども、ちょっと人数的に大分差があるので、知識として教えていただきたいんですが、カウンセリングに来た方が７,０００人で、実際に治療を受けている方が２,２００人だとか、そういう違いなのか、どういうことなのかと思いまして。","respondent":"冨田戸籍住民課長","answer":"大変恐縮なんですけれども、出所は法務省のほうで、先ほど、区民生活事業部長のほうで触れさせていただきましたけれども、施行は本年７月の予定ですけれども、戸籍関係の特例法が昨年７月に成立したわけです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"簡単なことなんですけれども、こういうふうに直すと、すべて必要書類といいますか、申請書類をつくり直しですよね、男女の枠を取るわけですから。区民の方からよく言われるのは、何々局長が変わると、全部その書類を直して、先にもらっている申請書が使えないとか、むだじゃないかとか、結構言われるんです。そんな数字的には細かいことは出ないでしょうけれども、考え方をちょっと教えてください。","respondent":"冨田戸籍住民課長","answer":"ただ、戸籍の届、あるいは住民異動届につきましては、法律で性別の記載が明記されておりますので、これはそのまま使い、削除はしませんけれども、その他につきましても、例えば区民カードを昨年実施したわけですけれども、これにつきましては。","voiceIndex":19,"id":"exchange-008"},{"speaker":"嶋委員","kind":"質問","question":"昨年７月に一定の特例が出て、また３年後に見直しということになっておりますが、そういう意味では、品川区がいち早く、このように取り組まれたということは、すごく評価したいと思います。悩みがたくさんあるというのはこういうことだったんです。そういう意味で、品川区は、その方たちの受け入れを、これからどのように進めていかれるのでしょうか。","respondent":"太川区民生活事業部長","answer":"その辺につきまして、男女共同参画のほうと、いろいろな部分で方針を詰めていかなきゃならないかと思いますので、それは早急に対応して、いろいろと協議してまいりたいと考えています。","voiceIndex":21,"id":"exchange-009"},{"speaker":"嶋委員","kind":"意見","question":"ぜひ、当事者の方たちが同じ品川区の中で普通に暮らせるということで、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"}]},{"id":"topic-02","title":"引き続きまして、(2)第１５号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"引き続きまして、(2)第１５号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"一つは、一番最後に説明をいただいた品川区国民健康保険運営協議会で、原案を適当と認めるという答申が出たという説明がありましたけれども、具体的にどういう質疑がされたのか、それをちょっと教えていただきたい。低所得者ほど重たくなっているというのは、計算上、そういうふうになっちゃってやむを得ないという認識なんかも含めて、ちょっとその辺を教えていただきたいと思います。","respondent":"太田保険年金課長","answer":"１点目です、品川区国民健康保険運営協議会での質疑の内容ですけれども、年金受給者の制度改正ですとか、あるいは、昨年ご提案を申し上げて、合議決定いただいています徴収方法の変更による１２期割から１０期割等になるということから。","voiceIndex":30,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"もう１点、品川区国民健康保険運営協議会のいろいろな質疑について意見が紹介されたわけですが、それについての、区としての見解というか、それも合わせて伺いたいと思います。その理由をどういうふうに見ているのかということ。現状をどういうふうにとらえているのかということを、ちょっと伺いたいと思います。","respondent":"太田保険年金課長","answer":"１０期割等につきましては、負担感が出てくるということは確かですが、昨年度、当委員会の中でもご説明申し上げましたように、支払いになる方が、無理なく均等にお支払いいただけるような月割りにもなるということから。","voiceIndex":32,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"滞納部分ですけれども、１カ月でも滞納していることをカウントしているので、増えているんだという話なんですが、現実的にずっと１カ月も含めてカウントしていて、それが増えているということですから、それはやむを得ないんだと、あまり社会の状況だとか、区民の生活が厳しいというところとは無関係だという趣旨なのかなと思うんですが、そういうことではないと、私は思います。なるほどなと思いました。","respondent":"太田保険年金課長","answer":"平成１６年度据え置くのは、社会状況を勘案してという趣旨で、話をされていますが、私どもはこう考えます。国民健康保険は、社会保険であると考えています。社会保険ですから、先ほど申し上げましたように、保険料と、基本的には国の負担金でまかなわれるべきだと。","voiceIndex":34,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"担当している課長として、これだけの滞納が出て、さまざまな手を打っていらっしゃるとは思いますけれども、しかしそれはくいとめることがまだできない状況で、不十分だということを言うつもりではなくて、区民生活の実態がこれだけ厳しいから、１カ月でも滞納しちゃうというところを、担当の課長としてはどういうふうに見ていらっしゃるのかなということを、ちょっと伺いたいと思います。","respondent":"太田保険年金課長","answer":"今、２４時間納めることができるコンビニエンスストアでの収納も６月から始める予定でおりますので、ＰＲ等を通じながら、収納率の向上については従来からやってありますけれども、さらに努めてまいりたいと考えております。","voiceIndex":36,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、区長会なり、この部分の課長会のところで、国に向けての意見書なども出して、要望書として出していると思っていますけれども、ぜひそこを強めていかないといけないし、出していても、それは万年同じことの繰り返しだけで、全然改善されずに、しかし一方では賦課割合を変えていくんだということで、重たい負担が区民のところに来ているのが現実ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"そういうような形でのコメントというものは許されるのか。あるいは実際にだれが言ったのかというのを、この委員会で、しっかり南委員から聞いて、あるいは、担当課長が言ったのか、助役が言ったのか、区長が言ったのか、そこまでやる必要があるんじゃないかという気がするんですけれども、どうなんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"それぞれの委員が、事前に出された議案に沿って、情報を収集して、調査を行って委員会に臨み、ここで審査をするというスタンスですから、私は私なりのところで調査をしてきたわけです。そういう範囲で言っているわけですから。ですから、必要だったら、委員長のほうに、２３区全体の状況を知らせる情報を出してくださいとか、そういうふうにお願いすることが正しいんじゃないかと思うんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-017"},{"speaker":"松澤委員","kind":"意見","question":"２年連続して値上げはいかがなものかとなっているんですけれども、ちょっとその辺が。実際に、これからいろいろな私たちの審議の中でも、今の問題ではなくて、保育料の問題等々があるわけですけれども、もしそういう話をされるなら、どういうしかるべき人が答えたのか、できれば聞いておきたい。私たちもそれは問い合わせしたいんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"今回、値上げを見合わせている区は二つの区だそうですから。それはさっき、保険年金課長もおっしゃっていたと思います。そこは特定できると思うんです。それで、ご自分でお確かめになったらどうですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"４月号の広報「しながわ」で、これに関してどのぐらいの枠をもらえるかというか、全ページじゃないわけですけれども、そこの一番の改正理由といいますか、その辺がちょっと気にかかるんです。どういう書き方をなさるかわからないんですが、あまりパーセントとか数字等を並べても理解されないんじゃないか。それよりも、改正理由について、何で上がるのかと。その辺については、いかがでしょうか。","respondent":"太田保険年金課長","answer":"広報「しながわ」につきましては、やはり他の掲載予定のものとの関係がありますので、例年、そんなにはスペースを取れません。基本的には、改正された後の金額を中心にやらざるを得ないと考えています。","voiceIndex":50,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"品川区国民健康保険運営協議会なんですけれども、諮問をして、答申をいただいたんですけれども、議会とこの協議会との関係といいますか、もし不適当という答申が出た場合に、やっぱり委員会等の議決のほうが優先されるんでしょうか。具体的に言うならば、この答申をどのぐらい考えて、委員会において可決とか、そういうことを委員の一人としてやっていくようになるんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-021"},{"speaker":"藤原委員","kind":"意見","question":"はい、了解しました。先ほどの保険年金課長の答弁で、滞納ということが出たんですけれども、今、払うべき方が払っていないで滞納率というのは、どのぐらいあるのか。","respondent":"太田保険年金課長","answer":"私ども、滞納率を出すのは、最終的には出納閉鎖時での率で把握しています。今現在、進行形ですです。","voiceIndex":54,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"滞納ということで、今、すごく思っていたんですけれども、私の前の前の会派、２人で組んでいたときによく話していたのが、区民のいわゆる権利と義務ということです。権利だけ主張して、義務を果たさないのはと、よく２人で１期生のときに話し合ったことを、今、ふと思い出したんです。１カ月でも保険料を払わなかったら、保険証というのは即座に回収しちゃうんでしょうか。","respondent":"太田保険年金課長","answer":"その後、区のほうへ、７割、あるいはそれぞれの負担割合で請求をすると、こういう仕組みになってあります。ですから、１カ月ということでは、保険証を返していただくということには、現在はなってございません。","voiceIndex":56,"id":"exchange-023"},{"speaker":"木下委員","kind":"質問","question":"ですから、先ほど来のお話で、生活保護をしなくちゃならない部分と、相互扶助の部分がごっちゃになっちゃうんで、この景気を考えれば、上げないにこしたことはない、上げないでくれるのにこしたことはないという部分はあると思うんですけれども、国民健康保険の場合は相互扶助ですから、やっぱりある程度はご負担はしていただかなきゃならないなと、私個人は理解したんですけれども、やはり。","respondent":"太田保険年金課長","answer":"滞納部分ですけれども、仕組みは当然ですけれども、現年分があります。その分で、昨年でいけば８６.５％が現年の収納率で、その部分で、２年の時効等がありますので、未収納分が、翌年に滞納金額として繰り越されるということがあります。","voiceIndex":60,"id":"exchange-024"},{"speaker":"木下委員","kind":"質問・要望","question":"さっき言いましたけれども、２１万人、２４万人は自己破産です。健康保険の部分というのは行政サービスの基本的な部分でもあるといいますから、行政としてサービスを受けられないようにするというのは難しい部分があるかもしれないんですけれども、強い態度でこれからの回収に臨んでいただきたいという要望をいたしまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"今、木下委員のご質疑を聞いていて、ちょっと改めて聞き忘れちゃったのを思い出したので伺いたいんですけれども、４ページに収入の部分で、国庫負担金とか、国庫補助金とか、都補助金とかありますよね。それで、国から来る負担金、補助金がどういうふうな推移になっているのか、増えているのか、あるいは減っているととらえていいのか、その辺をちょっと知りたいんです。","respondent":"太田保険年金課長","answer":"今、金額ベースでは、私ちょっと手元に資料ございませんが、基本的にはこうなっております。医療費については、医療総額の４０％、これが国の国庫負担ということで、これは定率です。東京都については、東京都が実施している単独事業の部分での補助ということになってあります。","voiceIndex":65,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"今の答弁だと、私が知りたかったことが全然わからないんです。国が本来出さなきゃいけない４０％が、今現状は、４０％でそのまま来ているのか、あるいは、これがやむを得ない事情で減っているのか、その辺だけでも教えていただきたいんですけど。","respondent":"太田保険年金課長","answer":"国のほうは４０％で、減っているわけではございません。","voiceIndex":67,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"４０％というのは、何に対する４０％なのか、分母のところで。基本的に国庫負担金と国庫補助金というのは、国が出さなきゃいけない責任はちゃんと持っているというふうに判断していいんですか。","respondent":"太田保険年金課長","answer":"ただ割合については、何といいますか、ちょっと細かな部分に入ってしまうんですけれども、若干の微調整等がありますので、結果的には３７％等になる部分があるということでご理解をいただきたいと思います。","voiceIndex":69,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"本来、要望してなければいけないぐらいの状況ですから、きちんと国が責任を持って、要請をしなくても国の責任分が来るというのであれば、要請する必要もないですけれども、毎年、区長会等々で関係部署のところでやっているということですから、やっぱりそれは、国の負担をきちんとさせるということがまずあって、そして区民への負担ということで、両極をよく見ていかないと判断を誤っちゃうなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"もちろん、先ほども申し上げたように、努力は大変なことだと思いますけれども、こういう滞納者を出さないためにも、５０対５０に機械的に移行していくということだけをとらえないで、区民の生活の実態をよく見て対応していかなきゃいけないんじゃないかと思いますので、今回の条例改正については、賛成はできません。したがって、そういうふうに採決を諮っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-030"},{"speaker":"田中副委員長","kind":"確認","question":"もう質疑が終わった後の話なので、委員会運営のことでちょっと触れたいんですが、先ほど、松澤委員からもお話がありましたけれども、こういう公式の場で出た話が事実として一人歩きすることのという部分で、先ほどの話は、南委員がご自身で聴取された内容を披露されたということでとどめられておりましたけれども、今、ここで出た議論の中で、先ほど、本来、国が４０％負担しなくてはいけない部分を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-031"},{"speaker":"南委員","kind":"確認","question":"しかし、金額的には３７％ということは、３７％しか出してないということになるんじゃないかと、私は判断したので、さっきはそういう発言をしました。それはそれぞれの取り方ですからやむを得ないし、自分がそこで確認したかったら、やっぱりその場面でやるべきですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-032"}]},{"id":"topic-03","title":"第３０号議案 保険診療報酬の返還に関する民事訴訟の提起","agenda":"第３０号議案 保険診療報酬の返還に関する民事訴訟の提起","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この医院は、診療科目はどういうあれなのか、ちょっと出てなかったのでわからないんです。直接会って交渉もしたけれども、結果的に支払いを拒否したために民事訴訟を起こして返還を求めるということですよね。ちょっとそんなことがあったということだけで、別に質問することではないんですが、診療科目がどうなのかなと、説明にあったのか、聞き落としちゃったのかわからなかったので、伺いたいと思います。","respondent":"太田保険年金課長","answer":"診療科目は内科ということです。","voiceIndex":86,"id":"exchange-033"}]},{"id":"topic-04","title":"請願審査","agenda":"請願審査","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"請願第６号について、２点お伺いしますが、まず、国連社会権規約委員会というのは、どのような委員会なんでしょうか。","respondent":"太田保険年金課長、高星委員長","answer":"私どももそこまでは調べてございませんので、申しわけございません。冒頭に、保険年金課長がおっしゃいましたように、説明に関しては目いっぱい説明していただきますけれども、わからないということですので、よろしくお願いいたします。","voiceIndex":97,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"もう１点、わかればでいいんですが、同じ請願なんですけれども、政府に請願・陳情していただく事項の２番の、無年金者というのは、どういう理由から年金をもらえないんでしょうか。","respondent":"太田保険年金課長","answer":"受給されない例としては、ご案内のとおり、２０歳から加入をされるという仕組みになってありますので、加入届けをしない、あるいは加入届けをしても、保険料をお支払いにならないという未納状態が続いているというところで。","voiceIndex":100,"id":"exchange-035"},{"speaker":"藤原委員","kind":"意見","question":"同じことを繰り返しちゃうかもしれないんですけれども、最低でも２５年間払わなくちゃいけないという部分を実行できなかった方がもらえないわけですね。２５年間というルールを守れなかった方が、結局もらえなかったということでよろしいですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"国民年金の受給者というのは、品川区の場合、どのぐらいいるんでしょうか。そして、月額がどのぐらいになるのか、ちょっと改めて伺いたいと思います。","respondent":"太田保険年金課長","answer":"それから老齢基礎年金でいきますと、概算ということでご理解をいただきたいと思うんですけれども、平均は月額５万５,０００円前後です。","voiceIndex":103,"id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"あまりよく国民年金のことはわからないので、教えていただきたいんですけれども、今、説明してくださったのは、老齢基礎年金の部分、受給者の数は、障害基礎年金等も含まれていますけれども、国民年金というのは、最低保障ということで４万６,０００円と言われていますけれども、よくわからないんですけれども、今まで納めた期間というか、金額によって３万円程度の人とか、５万５,０００円とかと。","respondent":"太田保険年金課長","answer":"ただ、現行の制度としては、老齢基礎年金という形になってありますので、これについては、平成１５年度では年額７９万７,０００円、それに加入可能月数で実際にお支払いになった納付月数と、免除であれば免除月数、そういうことで計算をするという形になっております。","voiceIndex":105,"id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"厚生年金も含めて、今回、年金改正は全部対象になって、見直しという形になっていますけれども、国民年金で見てみると、先ほどおっしゃったような金額で生活をしていらっしゃるわけで、例えば年金をもらう以前に、あるいは年金をもらった後でも、それなりの労働をして貯蓄をするとか、何かしらほかの所得がないと、現実的にはなかなかこれだけは暮らしていけないというのが、私などの感覚なんですが。","respondent":"太田保険年金課長","answer":"そこの部分で、国のほうの説明としては、２０２５年ごろまでの被保険者数の推測をしたと。そうすると、この間の平均が毎年０.６％ずつ減っていくということが一つ。それから一方では、高齢者の平均余命が伸びているということもある。","voiceIndex":107,"id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"だから、なるほどと、そういう表現がある程度信頼できるなと、私は思っているんです。生活保護を受けないで、自分の年金でつつましく暮らしていけば、何とか保護を受けなくてもやっていけるという高齢者だって大勢いらっしゃるわけで、そういう方たちを、さらに生活苦に追いやっちゃう制度になっちゃうんじゃないかと、私は思うんですけれども、この点については、どういうふうにお考えでしょうか。","respondent":"太川区民生活事業部長","answer":"ですから、お話しされるお考えというのは、そういうお考えも当然あろうかと思いますので、それはそれとして、私どももお聞きしておきたいと思いますけれども、この部分につきましては、生活保護との関係、それから年金制度の関係、私どもが、これをああしろ。","voiceIndex":109,"id":"exchange-040"},{"speaker":"南委員","kind":"質問","question":"大事な問題ですから、これからの国民の暮らしにかかわってくる問題ですので、十数分かかっても、やっぱり述べなきゃいけない部分はありますので、それは頑張って発言をしていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-041"},{"speaker":"南委員","kind":"質問","question":"意見も含めてですよ、請願に対する意見ですから、いいわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"ぜひ、意見も含めて述べたいと思います。それで、簡潔にまとめます。このほかに家賃とか、食料品、水光熱費が入ってくるわけですから、やっぱり国民年金で暮らしていらっしゃる方については、ほんとうに厳しい年金改悪そのものだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-043"},{"speaker":"松澤委員","kind":"質問・要望","question":"自民党は、年金制度の改悪反対、拡充を求める請願、いろいろ述べられておりますけれども、私たちとしてはこの意見には同意できないということで不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-044"},{"speaker":"嶋委員","kind":"意見","question":"平成１６年請願第６号ですけれども、政府に請願・陳情していただいく事項という中に、「安心できる年金制度を確立すること」ということがありますが、だからこそ、今回、将来についての年金改革をしっかりやってもらいたいということがありますので、私としても同意することはできませんので、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-045"},{"speaker":"松澤委員","kind":"意見","question":"２番目、「基礎年金の国庫負担割合を３分の１から２分の１へと早急に引き上げること」、これは今、平成１６年度から着手して、平成２１年度までに段階的に完了するんだという制度になっています。それから、３番目、「行政サービス・事務執行の効率性向上に向け、住民に身近な社会保険行政は、地方自治体で実施すること」。そんなことで、私たちとしては、早急に結論を出すべきじゃない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-046"},{"speaker":"嶋委員","kind":"意見","question":"この請願書を、公明党としても、いろいろ見させていただきました。年金制度の確立を図ることも、国庫負担割合を引き上げることもわかりますが、しっかりと今の国の動きを見守っていきたいということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-047"},{"speaker":"南委員","kind":"質問","question":"請願項目は、平成１６年請願第６号とは若干違いますけれども、でも請願の趣旨そのものは、公的年金制度を、ほんとうに安心して老後の生活がおくれるような内容にしてくれという、そういう意見を出してくれという趣旨の請願ですから、基本的に私は同じだと思うし、委員長も同じような趣旨だということで、一括して質疑をと、私は思っていたので、今までのご意見というのは、ええ、そうなのかなというふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-048"},{"speaker":"三村委員","kind":"意見","question":"内容的には同意できる部分が、項目については、それぞれ国が行うことにより事務執行の効率化が多少やっぱり落ちている面があると思っていますので、私もちょっと、もう少しきちんと審議をしていきたいと思いますので、継続ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-049"},{"speaker":"南委員","kind":"確認","question":"今の委員長の確認なんですけれども、平成１６年請願第１４号は継続扱いにすると、たけど意見書は出さないというのは、今回は出さないことであって、これから継続されて審査されていく中では、意見書提出もあり得るという、そういう意味ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"そういうことで、要するに私も、今ちょうど国会で審議している最中ですから、それに全国的な国民としての声を届けるということは大事なので、今回、採択して意見書を出していきたいと、さっき主張したんですけれども、継続でも、国会審議に間に合うという状況もあるんじゃないかと思いますので、意見書採択がそういう扱いで延びていくということでは、継続で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-051"},{"speaker":"三村委員","kind":"質問","question":"平成１６年度の予算で、ペットボトルの集積所回収実施ということが予定されておりますけれども、容器包装リサイクル法に基づくこちらの資料によるペットボトルの収集量が、平成９年度から平成１４年度にかけて、大体１０倍近くになっているかと思います。今後の推移ですとか、それにかかる費用の推計をどのように考えていらっしゃるのか、教えていただければと思います。","respondent":"中山清掃リサイクル課長","answer":"国の事業ですので、この場では詳しいご説明はまだしていない部分も若干ありますけれども、平成１６年度は年度の後半から実施していますので、おおむね、現段階では、資料にもありますけれども、３５０ｔほどの回収を予定しておりまして。","voiceIndex":146,"id":"exchange-052"},{"speaker":"三村委員","kind":"質問","question":"今回、容器包装リサイクル法に伴っての一番大きな問題点というのは、ペットボトルではないかと考えています。容器包装リサイクル法施行までは、事業者側が自主規制をしていたペットボトルが始まるということになって、新たなごみ問題ですとか、リサイクル問題が発生してきています。エコスポットで、そういう機械を使っていると思いますけれども、どのようにお考えなのか、教えていただければと思います。","respondent":"中山清掃リサイクル課長","answer":"ただ現在、デポジット制度をシステムとして活動しているのは、私の知る限りでは、八丈島というような離島においてのみということで、要は価格に転嫁していないものがそのまま返されて、お金を返す、返さないの問題が出てくるとなかなか難しいということで、そういう意味では。","voiceIndex":148,"id":"exchange-053"},{"speaker":"三村委員","kind":"質問","question":"今、八丈島のお話が出ましたけれども、ほかの小さい市町村においては、ごみの有料化ということが何件かされていると思うんですけれども、この前、大都市においても、ごみの有料化ということを始めるというニュースを見たんですけれども、ほかの市町村の有料化の取り組みについても、よろしかったら教えていただければと思います。","respondent":"中山清掃リサイクル課長","answer":"国レベルでも、少しこの辺の検討を開始しているということですが、まだまだ完全な全体な仕組みとしてはいっていない状況です。それから、有料化の報道というのは、多分、福岡市で、政令指定市としては初めて有料化の方向性を出してきているという報道だったかと思います。","voiceIndex":150,"id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"その点についての認識がどうなのかということ。同時に、事業者への指導というのか、規制をかけていくのは、品川区の行政範囲じゃないと思うんですけれども、しかしそれなりに、品川区としては結構最近、事業者責任をはっきり打ち出してきていますので、その辺の取り組みがどういうふうになっているのかというところを、ちょっと伺いたいと思うんです。","respondent":"中山清掃リサイクル課長","answer":"事業者の回収ルートの確立を、できるだけ行政も求めていく姿勢は、ご指摘のとおりだと認識しています。ただ、こういう法律の役割分担の中でどこまで指導できるのかという限界があります。","voiceIndex":152,"id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"こういう点からすると、日本のリターナブルびんというのは、今、どのぐらいの状況なんでしょうか。品川区とドイツの比較は単純にはできないということは百も承知なんですけれども、インターネットの検索ですから限界があるんですけれども、それにしても、ドイツでは回収率が８０％になっているというここを、少しでも目標にして取り組んでいく必要があるんじゃないかなと思うんです。","respondent":"中山清掃リサイクル課長","answer":"２３区においても、あるいは東京都も含めた持ちかけとしては、こういった事業者の責任をより明確にしていくような取り組みということを要請するというのは、例えば家電リサイクル法の不法投機について、事業者の負担を求めるであるとか、パソコンリサイクルの際にも。","voiceIndex":154,"id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"リターナブルびんというのは減る傾向があると、いみじくもおっしゃったけれども、事業者に、ちゃんとリターナブルで、こういうふうなサイクルが組めるような、そういう設備をきちんとするようにというのは、極めて国レベルの問題なんでしょうけれども、それをぜひ強めていただきたい。したがって、この請願の扱いに入っちゃいますけれども、趣旨としては非常に賛成できる請願だと読んでおります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-057"},{"speaker":"松澤委員","kind":"質問","question":"９０％に限りなく近いかもしれませんけれども、残りの自治体はどうされているんですかね。市町村が絡まないで、直接一般家庭からの分別を特定業者、酒屋さんとか、そういうところに持ち込むような方法をとっているんでしょうか、その辺をちょっと。","respondent":"中山清掃リサイクル課長","answer":"そういうほんとうの例外的なところというのは、おそらくあえて容器包装リサイクル法によらない処理だけで足りる市町村ということで、これは想像ですけれども、例えば離島のようなところで、あえて法の仕組みを行うにしても、なかなか処理に持っていくルートがないとか。","voiceIndex":158,"id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどもちょっと申し上げましたが、消費者に新たなお金を高めにかけて、デポジットという意味なのかどうかわからないんですけれども、その分高くして、高いから買うのをやめて、こちらの安いほうを買おうとか、そういうことになるのかちょっとわからなかったので、そこが非常にひっかかるから、趣旨はわかるけれども、消費者に新たな負担をかけるという中身であれば、私の意図するところではないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-059"},{"speaker":"松澤委員","kind":"質問・要望","question":"容器包装リサイクル法の見直しを求める意見書提出を求める請願について、審査しました。平成１７年度にリサイクル法の見直し議論が行われる中で、そういう意味では、請願そのものはいいんではないかということが大勢だったんです。ただ、意見書を出すということについては、意見書そのものがどういうものかと、自民党の中でも、意見書という部分に対する議論が分かれるようです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-060"},{"speaker":"嶋委員","kind":"意見","question":"私どもも、この請願趣旨は大変よくわかって、大変大事な点であると思うし、生産者の責任を明確にするということはとても大事なことだと思います。考え方としては賛成ではありますが、やはり、一番上のいわゆる収集、分別、保管費用を製品の価格に含めるということに対しては、消費を損なうということもあったりしますので、意見書に対しては、出さないということで、請願に対しては趣旨採択ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":171,"id":"exchange-061"},{"speaker":"南委員","kind":"意見","question":"容器課徴金というところが、経済的なところも盛り込んで、価格に附加をするという、そういう清掃リサイクル課長のお話がサジェスチョンになったので、そういうこととあと１番、製品の価格に含めるとなってくると、なかなかちょっとあれかなと思うんです。だから、非常に迷うところなんですが、趣旨としては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-062"},{"speaker":"南委員","kind":"質問・要望","question":"私の発言は終わってないんですから、最後まで聞いていただきたいなと思うんです。発言の途中で、委員長が切らないで、よろしくお願いします。そういうふうに、いろいろと正確に取り扱おう思えば思うだけ、非常に矛盾するところがあります。気持ちとしては、趣旨採択ということにしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-063"},{"speaker":"木下委員","kind":"意見","question":"価格に含めて、その価格をどうするのかと。含めて、業者が最後の回収だとかの費用は行政に任せて、つくり得みたいな部分もあるのかなということを思ってしまいますし、もうきちっとこうだという形で書いてないので、意見書は、これでは出せないかなと思いますので、趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":178,"id":"exchange-064"},{"speaker":"三村委員","kind":"質問・要望","question":"私たちとしては、意見書提出をしていただきたいんですけれども、皆様のご意見を伺っていますと、なかなか意見書の内容が難しいのかなと思いますので、趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-065"},{"speaker":"南委員","kind":"質問・要望","question":"どういうことなのか、全容を。八潮の連合自治会の中で、環境課長がおいでになって説明をされていると聞いておりますので、そのときの内容も、ちょっとかいつまんで報告をいただきたいと思うんです。きょうのことなので、あしたの部分で可能であれば、あしたでもいいんですけれども、そのことをちょっとお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-066"},{"speaker":"南委員","kind":"意見","question":"私もちょっと直前に委員長にお諮りしないで出しちゃったから悪かったなと思うんですけれども、改めて正副委員長にちょっとお話を伝えて、みんなで必要であればということで、そうとりはからっていただけるようにお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":190,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2382#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":53245,"voices":192}},{"id":"h16-20040301-7","meetingId":"h16-cm03","date":"2004年3月1日","dateIso":"2004-03-01","committee":"厚生委員会","time":"午前１０時０３分～午後４時５９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を106件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今まで学童保育クラブと児童センターが一体的な運営ということで職員配置もされてきたと思うんですけれども、これから学童保育クラブが廃止となると、児童センターの職員体制がどうなるのかについて、１つ教えていただきたいと思います。","respondent":"辻田児童課長","answer":"そういう中で、今、過渡的な形で定数は推移しております。現在、児童センターの改革検討委員会というものをつくりまして、その中で児童センターの定数がいかにあるべきかということを今後長い間にわたって耐えられる定数等を、今、検討しております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで言えば、学童保育クラブの子が移動した後にどういうふうな影響になっているのかというふうなところを教えていただきたいんですけれども、例えば、ごっそりすまいるスクールのほうに移行してしまって、学童保育クラブのほうがすごく定員が少なく、かなり少ないというような状況の学童保育クラブだとか、また、学童保育クラブが周りでなくなってしまったために、今回。","respondent":"辻田児童課長","answer":"そういう中でご理解をいただいて移っていただいたところもあります。それから、新入会の方については、あんまり少ないところにお子さんを入れても、事業として成り立ちませんので、この辺につきましては、第２希望のところに入会させていくというような形での対応をしております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１人とか、２人とか、３人というところで、近隣の学童保育クラブに移動というふうなところの可能性ということでお話がありましたけれども、そうすると、今回、１０館ですけれども、さらに閉鎖される学童保育クラブが増えるという可能性もあるということでしょうか。","respondent":"辻田児童課長","answer":"ただ、現実に子どもたちがいなくなったところの学童保育クラブ、いわゆる分館部分です、児童センターはそのまま機能してまいりますので、分館部分につきましては、今後その実態を見ながら、例えば、休止するとか。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これが大体おおよそどれぐらいの、何館ぐらいあるのかだけちょっと教えてください。","respondent":"辻田児童課長","answer":"現在まだ調整中ですので、最終的な部分での館数というのはまだ出ていないということです。ちなみに、１０人以下については７館あります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問","question":"個々の対応ということで調整をしているという話を今初めて聞いてびっくりしたわけなんですけれども、この間、学童保育クラブがあるうちは残りたい、すまいるスクールがあってもそっちに通わなくて、学童保育クラブがせっかくあるんだから、そこに残してほしいという希望もあったと思うんですけれども、この間、子どもたちの措置状況をつかむに当たって、そういった声を聞いているのかどうか、その辺と、今。","respondent":"辻田児童課長","answer":"ただ、私どものほうも、生木を割くような形で子どもたちを向こうにやるということではなく、相談あったケースにつきましては、個々的にすまいるスクールと学童保育クラブの職員、それから本課の職員も入りまして、どうすればいいかということを具体的な話の中で。","voiceIndex":14,"id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"経過的にそういうことができるのではないでしょうか。そういった経過措置がぜひ必要と思うんですが、その点が１点。児童センター自体に子どもの動きというか、流れに変化が来ているのではないかなと思うんですが、その点１点と、児童センターの職員の配置がどのようになっているか教えていただきたいんですが。","respondent":"辻田児童課長","answer":"経過措置ですけれども、私ども、この間、移行を発表して、その後それぞれの状況の中で最善の努力をしております。そういう中で、説明会もいたしました。そして今、保護者会を開いても、そういうお話は出てきておりません。","voiceIndex":16,"id":"exchange-006"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"中高生が増えてきている児童センターの利用がということなんですけれども、すまいるスクールができて、小学生がすまいるスクールを利用するようになっての変化のあたりも聞かせていただきたいのと、今ちょっと児童センターの状況を見て考えるというような、状況によって考えるという最後のお言葉がちょっと気になったので、そのところをもう少しお伺いしたいと思います。","respondent":"辻田児童課長","answer":"当初は情報等も少なかったためになかなかご理解いただけなかったものが、この間の説明会とか、いろいろなものでそれなりの理解を得ているという状況で私どもは判断しております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問","question":"１つは、児童センターの、今、検討会をしていますけれども、この検討はいつぐらいにまとめになるのかをお聞きしたいのと、あと、４月からの子どもたちの措置状況の把握というのは、いつぐらいまでにできるのかお聞かせください。","respondent":"辻田児童課長","answer":"大体７月ぐらい、８月ぐらい、来年度の予算等に合わせた形に中で、いわゆる検討委員会と違いまして、改革委員会はより具体的な形での中身になっておりますので、そういうものを出していくということで考えております。それから、最終的な調整というのをまだやっている段階です。","voiceIndex":20,"id":"exchange-008"},{"speaker":"須藤委員","kind":"質問・要望","question":"この各館の１０館の広さは、もしおわかりになれば教えていただきたいと思っていますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"須藤委員","kind":"質問・要望","question":"結構です。広さはあとでまた教えていただければ、我々も勉強したいと思うので。ここで閉館した後の跡地利用ということについては、どういうふうに考えていらっしゃるのか。ちょっと広さをお聞きしたのは、我々もこうしてというようないろいろな絵が出てこようかと思うので、児童課のほうでお考えがあったり、行政のほうで、理事者のほうで何か考えがあればお話を聞かせていただきたいと思います。","respondent":"辻田児童課長","answer":"西品川の分館につきましては、西品川保育園の拡充で待機児の解消を図っていくというようなことで考えています。それから、荏原南につきましては、高齢福祉課、健康課が、高齢者のための介護予防拠点として事業を実施するということになっています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回、すまいるスクールが始まった１９校には、自分が通っている学童保育クラブがまだ閉鎖されなくても、すまいるスクールのほうに移らなくてはいけないということになりますけれども、前、この厚生委員会にも、審議にはかからなかったんですけれども、清水台小学校で旗の台学童保育クラブに通っているお母さんから、清水台小学校ですまいるスクールは始まるけれども。","respondent":"辻田児童課長","answer":"ただ、個別的にどうしてもすまいるスクールのほうに行けないような状況があれば、それは私どもも個別に聞いて、そして具体的な対応をしているです。","voiceIndex":30,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区のほうとしては、それがいいというふうに思っても、親はいいというふうに思わないわけですから、親としてはやっぱり選べるという選択肢がやっぱりたくさんあるというほうが、増やしてほしいという要望をしているわけですから、区の思いをそういうふうに押しつけるということがおかしいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今までも学童保育クラブをなくすということに対しては反対という態度で来ましたので、今回のこの条例に対しても反対という態度を表明させていただきたいと思います。それと、おやつの問題でも、それから、ほっとできる場、こういうふうなところでも、すまいるスクールの中に学童保育クラブが継続できていないので、学童保育クラブとして存続をさせるべきというところで、この条例に対しては反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"}]},{"id":"topic-02","title":"引き続き、第１７号議案 品川区保育の実施等に関する条例の一部を改正する条例","agenda":"引き続き、第１７号議案 品川区保育の実施等に関する条例の一部を改正する条例","exchanges":[{"speaker":"若林委員","kind":"質問","question":"保育料、なるべくなら値上げはしなければいいなという目線でちょっと何点か質問します。それから、細かくなりますので、３番の2)ですが、在宅の家庭の方や他の納税者とのバランスというのを考慮するという考え方ですが、子育て支援に対してこういうバランスをとるという考え方が果たして整合性があるのか、どういう意味のバランスなのか、ここら辺、何点かお尋ねをいたしました。","respondent":"金子保育課長","answer":"そこで改定しまして、すぐ４月実施というよりは、最低半年程度の期間を置いた上で実施していくということが、私ども利用者に対する説明責任も含めてあるのかなというふうに考えているところです。","voiceIndex":40,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"大方わかりました。それから、済みません、もう１回、もう１点追加で、国基準支弁額の約２.５倍が大きく膨らんでいるという言い方でいいんでしょうか。保育サービスの充実ということで２.５倍までなっていると。むだがあるとすれば、この保育料、今回、上げないでもほかの部分でカバーをできるのではないかという考え方も当然あると思いますので、そこら辺、もう１点伺います。","respondent":"金子保育課長","answer":"調理代行はおかげさまで今年の４月から全園実施の予定になりますが、これを全園実施して、本会議のご答弁の中でも申し上げているとは思いますが、全園実施することによりまして、単年度で７億６,０００万ほどの改善を、削減を実現しているということから。","voiceIndex":42,"id":"exchange-015"},{"speaker":"大沢委員","kind":"意見","question":"素朴な疑問かもしれないんですが、なぜ今、国基準という基準がこの保育に関して出ているのか、品川区独自の顔を持った保育方法も、福祉に関しては最先端を行っている本区という私は認識を得ておりますので、なぜ今、国基準で、国基準が定めた徴収金基準額の４７％に過ぎないという文言が出てきて、なぜ国基準に追随していかなければならないのかという部分の理由をお聞かせ願えればと思います。","respondent":"金子保育課長","answer":"確かに委員がおっしゃるとおり、この間、私ども、先ほど申し上げました特別保育事業、全く他の自治体と横並びで実施するということではなくて、品川区としてどこまで保育のサービスを充実できるかということで相当充実してきた経過があります。","voiceIndex":44,"id":"exchange-016"},{"speaker":"大沢委員","kind":"質問","question":"一応、私の理解するところでは、国の三位一体の改革の流れの中でこのような方向になってきたということで理解してよろしいでしょうか。","respondent":"金子保育課長","answer":"ただ、この所得譲与税の詳細部分というのがまだ明確ではありませんので、具体的にはお示しできないということが１つと、先ほどちょっと申し上げましたとおり、私立の保育園の部分については、認可保育園の私立の保育園ですけれども、この部分については。","voiceIndex":46,"id":"exchange-017"},{"speaker":"須藤委員","kind":"意見","question":"というのは、前に０歳児、６０万ぐらい１人かかっていたというようなときに、町の人たちから、そんなにかかるのでは親御さんにお金を払って育ててもらったほうがいいんじゃないか、というぐらいの町の人たちの考え方が出てきている。実際は努力によって、きょうは５３万幾ら、０歳児という形なんですが。","respondent":"金子保育課長","answer":"平成１６年度につきましては、先ほど申し上げたとおり、調理代行が全園実施になりますので、その意味では、この部分ももう少し下がってくるかなというふうには思っております。新聞はこの辺のある時点でのものを取り上げたのかなというふうに今考えております。以上です。","voiceIndex":48,"id":"exchange-018"},{"speaker":"須藤委員","kind":"意見","question":"ちょっと違っているのは、外部評価事業、委託をしたときに、そのところの１つが保育園の経費がかかり過ぎるというような形で出ていたんですけれども、その辺はどういうふうに。理事者のほうがそういうことを受け取っているのかな。区長のこの間の所信表明の中に外部評価委託を今度反映してというような表現が所信表明の中にあったんですけれども、そのあたりは理事者のほうは聞かれていますか。","respondent":"金子保育課長、小沼福祉事業部長","answer":"私の記憶によりますと、外部評価委託で経費がかなりかかっているのは、つい最近見たような気がします。それは品川区ではなくて、２３区のどこかの自治体だったかと思いますが、どこの区だかは覚えていないので……。以上です。私のほうとしましては、先ほど冒頭申し上げましたけれども、８０億余の事業経営をまとめるものとしましては、当然のことですけれども。","voiceIndex":50,"id":"exchange-019"},{"speaker":"須藤委員","kind":"質問・要望","question":"私どもは、ずっと前からそれぞれ各年度で対応しなさいよというお話をさせていただいていた。ただ、値上げ値上げという面だけではなくて、こういう状況であるという区の財政全体を見ながらの話、それからいろいろな事業を拡大してきているという面、そういったことも一緒に説明をしていただきたいというふうに要望をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"６０％に近づけていくというふうなことなんですけれども、私たちが予算説明を会派のときに受けたときには、９％ずつ３年間値上げを続けて、合わせて２７％値上げをするという説明を受けたんですけれども、ここいら辺のところがどのようになっていくのかを１つ教えていただきたいのと、それから、６０％の根拠なんですけれども、これ、全国の多くの自治体が６０％くらいなので６０％にしていくということで。","respondent":"金子保育課長","answer":"つまり、品川区と同じようなレベルのところが多いかと思います。現在、じゃあ、他の区についてはどうかと申しますと、私の見るところですけれども、他の区も今現在、研究あるいは検討をしているという段階だろうというふうに思っております。","voiceIndex":54,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"実際、大変な状況になるのは父母の皆さんなわけですから、これをやはりこういうふうな保育料値上げも検討していますということを、今回、提案をしたいと思っています、提案をしますということをプレス発表の場とかも含めて、広報とか、そういうふうなところでもしっかりと区民に、特に父母の皆さんには、それに対して決まってからでは何も意見も言うこともできないわけですから。","respondent":"金子保育課長","answer":"第１点ですけれども、先ほども申し上げたとおり、基本的な考え方としては６０％に向けてということですが、今年に関しては９％の引き上げということでご審議をいただいているところでありまして、来年、再来年については。","voiceIndex":56,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"議員が区民の代表ということでいつも言われているんですけれども、議員のほうに提案があってからもわずか１カ月もないという、こういうふうな状況ですので、これでは区民のほうに全くこの情報がいかないというふうな状況なんです。自分たちの生活がどうなるかというふうなことに直接かかわってくることなので、これは説明責任を果たしていないというふうに思います。","respondent":"金子保育課長","answer":"２点ほどのお尋ねかと思いますが、まず、値上げが大変であるというようなお声があるというふうにお聞きしていらっしゃるということですが、先ほども新旧対照表のところでご説明しましたとおり、私ども、今回の改定に当たっては、体系そのものをいじってございません。","voiceIndex":58,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区の側からというふうなことだけから考えられていると思いますけれども、その父母の生活実態や、それから今、雇用の実態、それがほんとうに今、こういう社会状況の中で大変な状況になっていると思うんですけれども、正規職員にもつけないで非常勤のまま働いている方ですとか、自営の方なんかもほんとうに売り上げが伸びなくて大変な状況というふうなのがあると思うんですけれども。","respondent":"金子保育課長","answer":"先ほどもご説明申し上げましたかと思いますが、私どもとしましては、この保育園を利用されている方についてのご負担を若干改定するということですけれども、やはり利用されていない方も含めて、現在の不況から少し明るみが見えたというふうな状況にはなっているかと思いますが。","voiceIndex":60,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それからあと、ほんとうに親の皆さんは、保育料値上げのことを知ると、ほんとうに今でもぎりぎりの生活で、これでは２人目が産めないという声がほんとうにたくさんの方から出されていますけれども、品川区は０.８８という、こういう特殊出生率の中で、これをさらに少子化を加速させることにつながるのではないかと思うんですけれども、その点に関してはどう考えられていますか。","respondent":"金子保育課長","answer":"先ほど、明るみが見えたというふうなコメントを申し上げましたけれども、これは最近の新聞に載っている経済情勢ということで私が認識しておりましたので、そのような言葉を使いましたが、全体としては、先ほど申し上げましたとおり。","voiceIndex":62,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"新聞で明るみが見えたと判断したと、新聞報道でということなんですけれども、じゃあ、実際の品川の保育園に預けている親の実態というのに対しては、どう判断されているのかについて、もう１回お聞きしたいと思います。理想の子どもを持ちたいというのが２.３人なんですけれども、実際に……。そういうところにつながっていくということに対してどういうふうに考えられているのか、もう１回お願いします。","respondent":"金子保育課長","answer":"もう１点、少子化の部分ですけれども、これも繰り返しになって恐縮ですけれども、あくまでもやはり今回の保育料というのは、保育園を利用されている方についてのみ応分の負担をお願いしているわけであって、全体的な政策についてはいろいろな施策。","voiceIndex":64,"id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この間、聞いていて、もう１回改めて聞きたいなと思うのは、なぜ保育料の値上げをするのか、その点、明確に。品川区は５００億円以上の基金もありますよね。今日のいただいた表にもどれだけ子どもにお金がかかっているのかという表を示されたわけですけれども、改めてお伺いします。受益者負担という言葉がよく使われますが、この受益者は一体だれなんでしょうか。","respondent":"金子保育課長","answer":"先ほどからるるご説明申し上げているかと思いますが、なぜ今の時期に値上げをするのか、引き上げをするのかですが、私どもとしましては、現行の保育の運営経費、それに保育料のバランスが見合っていないというふうに考えているわけでありまして、先ほども申し上げたとおり。","voiceIndex":66,"id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"なぜ値上げかということで、いろいろご説明をされたんですが、私は納得がいきません。そして、さっきなぜ値上げなのかと言ったところで、原因としては、もちろんお金が子どもたちにかかっているのはあるんですけれども、私は国の負担、国庫負担のところの問題点があると思うんですけれども、その辺、もう１回お答えをいただきたいと思います。","respondent":"金子保育課長","answer":"３点ほどのご質問かと思います。１点目は、今やっていける状況なのに、なぜ改定をするのかというふうなお尋ねかと思いますが、私どもの考えは、今現在やっていけるから何も考えなくていいのかということではないと思います。","voiceIndex":68,"id":"exchange-028"},{"speaker":"飯沼副委員長","kind":"質問","question":"総額だったら大体変わっていないんです。この間、事業的には次々に拡大をして、さまざまな事業を拡大しているわりには総額が変わっていないというところでは、私は決して全体的な財政を圧迫しているとは思えないんですが、その辺はどうでしょうか。","respondent":"金子保育課長","answer":"これは私どもとして待機児が増えることを、待機児の解消に努めるために定員の拡大、あるいは入園の弾力化ということを実施しているがために、やはり経費そのものが徐々にでありますが増大してきております。","voiceIndex":70,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほどから値上げは低所得者は１００円か２００円だというふうなことで言われているんですけれども、区のほうでは平均階層はＤ１０だということで言われていると思うんですけれども、Ｄ１０の方が２７％保育料が値上がったときに、幾らから幾らになって、年間幾らの負担が増えるのか教えていただけないでしょうか。","respondent":"金子保育課長","answer":"今回、９％の引き上げのご提案ですので、２７％については、私どもとしましては、現在、回答しても意味がないのかなというふうに考えてあります。以上です。","voiceIndex":72,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それで、９％というふうなことで、でも、来年も再来年も９％ずつ認められれば値上げを提案していくということではないんですか。ということであれば、一番初めに予算説明のときに、９％ずつ合わせて２７％を３年間で値上げをするという方向だというふうに聞いたんですけれども、これは方針としては変わったんでしょうか。","respondent":"金子保育課長","answer":"先ほどからこれも繰り返しになってしまうかと思いますが、そういった基本的な考え方、つまり、徴収金基準額の現在の４７％から６０％というのが目標であるというふうにはご説明申し上げておりますが。","voiceIndex":74,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"６０％を目標にして２７％ということで言われているわけですから、こういうふうなことで考えざるを得ないわけですね。それで、Ｄ１０で２７％で計算してみると、これ、年間９万５,０００円くらいの新たな負担になるんですね。新たな負担。どんどん不況の中で今、区の職員も私たちもそうですけれども、給料か限られているじゃないですか。このことについてお聞かせいただきたいと思います。","respondent":"金子保育課長","answer":"今、また繰り返しになって恐縮ですけれども、私どもとしましては、今回の提案は９％ということですので、Ｄ１０階層については、３歳未満で８,０００円、３歳児で５,３００円、４歳以上児で４,９００円という引き上げになりますので。","voiceIndex":76,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今回、９％というふうなことであれば、来年、再来年はじゃあ提案しないということで言っていただけますか。来年、再来年についてお答えください。","respondent":"小沼福祉事業部長","answer":"るる保育課長のほうが説明していますけれども、数値的には徴収基準で見ると４７％がたしか４％アップで５１程度になろうかと思います。実額ベースで見ると９.２％で、約９％です。","voiceIndex":78,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そしてまた、そういうふうなすべての状況というふうなものは、出してこないというふうな可能性というふうなところは、どういうところから判断するのか、そこら辺のところを教えてください。","respondent":"金子保育課長","answer":"これも繰り返しになってしまうかと思いますが、現在の段階では、来年のことについて申し上げる段階ではないというふうに考えてあります。以上です。","voiceIndex":81,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"もう１つ、説明責任の問題なんですけれども、決まったことを周知するというふうなところだったんですけれども、やはり父母の状況とかなんかも聞く必要があると思いますし、こういうふうなことで考えているけどというふうなことで、区民にやっぱり知らせてやるべきだと思うんですけれども、そういう考え方に対してはどうでしょうか。","respondent":"金子保育課長","answer":"これも繰り返しになってしまうかと思いますが、私どもとしましては、この条例提案ですので、議会で十分ご審議していただくということを考えてあります。先ほども申し上げましたとおり、所得階層については、私どもとしましては、各層にわたって十分配慮しているつもりです。","voiceIndex":83,"id":"exchange-035"},{"speaker":"三上委員","kind":"質問・要望","question":"幾つかお伺いしたい、こう思います。ですから、その人にとって見ると、年収というのはどれくらいの金額になっているのか、こういうことがある程度見えてこないと、この階層の人はこれくらいの収入が、年収があるんだよ。Ｄ２１というのは、もう最高額ですから、これは無制限までいってしまうわけですよね。それをちょっとお願いしたい。","respondent":"金子保育課長","answer":"これがほんとうに粗い数字で恐縮ですけれども、こういうものです。先ほども申し上げましたとおり、厳密に出すのはちょっと難しいということでご理解いただきたいと思います。","voiceIndex":85,"id":"exchange-036"},{"speaker":"三上委員","kind":"質問","question":"粗い数字で……。これは要するに、お子さんが１人と考えたらいいんですか。２人……。","respondent":"金子保育課長","answer":"１人の場合と２人の場合と、はっきり申し上げて、そう変わりはございません。","voiceIndex":87,"id":"exchange-037"},{"speaker":"三上委員","kind":"質問","question":"平成９年の改正のときにも、これ、１２年間、１３年間ですか、値上げをしてこなかった、このことによって、先ほど冒頭に出てきましたけれども、７０％の目標で３５％上げた。今回も７年間ですか、やっぱりその間、値上げしなかった、なぜしなかったのか。お尋ねしますけれども、保育園の運営経費の中で保護者が負担する費用というところの内容的な部分というのはどういうことになっていますか。","respondent":"金子保育課長","answer":"ですので、これ以降、努力をしなければ、委員ご指摘のとおり、９０億あるいは１００億にも達していたかなというふうには考えられるところだと思います。以上です。","voiceIndex":89,"id":"exchange-038"},{"speaker":"三上委員","kind":"意見","question":"もうちょっと、その保護者が負担する費用というのはどういう部分に使われてきたのかということを、ちょっとそこのところを説明いただけますか。この平成９年のときの改正のときの資料を見ると、一般生活費、それから人件費とか管理費とかという形で、これは保護者が負担する費用ですよとありますよね。現状そのままずっと考え方というのは引き継いできているのか、それとも変更があったのかどうか。","respondent":"小沼福祉事業部長","answer":"ただ、問題は、先ほどるる申し上げてまいりましたけれども、私どもも結果として、この間、それじゃあ、経費の増嵩を防ぐにはどうしたものだということで、例えば、調理代行の問題であるとか、配置基準も時代に合った形での見直しですけれども。","voiceIndex":91,"id":"exchange-039"},{"speaker":"三上委員","kind":"意見","question":"要するに、給食費。品川区は１６年度の施政方針の柱に子育て支援を掲げています。だけど、じゃあ、内容はどうなんだと。お父さん、お母さんたちは、なぜ値上げしなければならないのか、負担をどういうふうに分担して持ってもらわなければならないのかという、こういうきめ細かな説明というものをしていかないとだめですよ。２人目、３人目になったら減額しているでしょう、ちょっとはっきりそこは。","respondent":"金子保育課長","answer":"２人目、３人目につきましては、おおむね２分の１程度、ほとんどの層で２分の１程度減額をしております。","voiceIndex":93,"id":"exchange-040"},{"speaker":"三上委員","kind":"質問・要望","question":"その２人目、３人目、１人預けているから２人目、３人目を何とか預けられるという雰囲気で保育の申請をしたときにそういうふうに預けられた範囲にあるのかわかりませんけれども、いや、それは審査はありますよ。保育料にしたってやっぱり同じことだと私は思いますので、やっぱりそういったきちっとした説明をこれからやっぱりしていっていただきたい、こう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-041"},{"speaker":"飯沼副委員長","kind":"質問","question":"ここでちょっとお話をしたいのが、Ｄ１０階層、有料のところの平均の階層ですけれども、所得税２１万から２４万。年間７０万円弱だと、Ｄ１０階層だと、３年働けばおおむね保育料、ご提示いただいた１７１万何がしの部分は、３年働けば、お母さんが働いた分でまずお返しはできる。保育園を利用されている方はすぐやめません。この辺の評価をお伺いしたいんですが。","respondent":"金子保育課長","answer":"私ども考えますには、この部分といいますのは、もちろん控除等々ありますが、働いている方の多くのところにかかっているものであって、保育料というのはあくまでも保育園を利用している方の問題でありますので。","voiceIndex":96,"id":"exchange-042"},{"speaker":"飯沼副委員長","kind":"意見","question":"一言で終わりますけれども、保育料は保育を利用している人の問題だ、そうやって狭い範囲で考えるから、ほんとうに子育て支援にならない。女性が働いてもなおかつ子どもを産んで楽しく育てたい、この思いを縮めてしまうからこそ、今、日本の、また品川の少子化に歯どめがかからないと思うんですよ。これは意見で終わりますが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"説明責任のところでどうしてもちょっと納得がいかないので、もう１回質問したいんですが、議会が区民の代表だということで、区民のほうには知らせるということは必要ない。議会にさえ知らせていればいいんだということで、それでも条例が議会に提案される前にプレス発表なんかで、品川区がアピールしたいものに対してはどんどんアピールしていますよね。でも、そのときは口頭で聞いただけだったんですね……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ごめんなさい、２月。２月３日の会派の説明会で口頭で聞いただけだったんですよ。条例が出されたのが１７日でした。そして、議会が代表ということであれば、議員が区民の状況や、それから区民の思いというのを聞いてここに反映しようというふうなことで考えられているんでしょうか。それにしても、あまりにも時間がなさ過ぎると思うんですけれども、そこら辺のところについてどう考えるのか。","respondent":"金子保育課長","answer":"先ほどから申しましたとおりですが、議会で議決をいただいた暁には、区民、利用されている保護者あるいは区民全体に向けてきちっと説明をしていきたいというふうに考えてあります。以上です。","voiceIndex":101,"id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"答弁がしっかりと、私の質問に対しての答弁が返ってこないので聞かざるを得ないという状況があるんですけれども、そこら辺のところを……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-046"},{"speaker":"飯沼副委員長","kind":"意見","question":"反対の意見表明をします。４点。２点目は、経済的な状況が厳しい中に、さらに家計に圧迫をしてしまうといった面では少子化に拍車をかけていくものであるといった点。３点目は、受益者の問題ですけれども、やはり子どもは社会の宝といった面で、税金でみんなで安心して育てられる、そういった応援をしてほしいといった面。４点目は、責任、説明責任を果たしていないということで、この４点で反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-047"}]},{"id":"topic-03","title":"早速議題の審査に入ります。第１８号議案 品川区立保育所における延長夜間保育に関する条例の一部を改正する条例","agenda":"早速議題の審査に入ります。第１８号議案 品川区立保育所における延長夜間保育に関する条例の一部を改正する条例","exchanges":[{"speaker":"若林委員","kind":"質問","question":"午前中の保育料に関してＡ・Ｂ階層、保育料がそのまま０円ということで、こちらの延長夜間になりますと負担が出てくると。ここら辺の整合性というんでしょうか、バランスというんでしょうか、受益者負担の考え方、ちょっと教えてもらえますでしょうか。","respondent":"金子保育課長","answer":"特にＡ・Ｂ階層については、月額の場合、従来から無料でしたけれども、これもいただくことによって、全階層にわたって適正でない利用については抑制していきたいという思いで、極めて低額ですけれども、いただくように今回は考えてあります。","voiceIndex":123,"id":"exchange-048"},{"speaker":"若林委員","kind":"質問","question":"適正でないケースがままあったということで、特にこのＡ・Ｂの方にそういうことがあったという意味ではないんでしょうか。","respondent":"金子保育課長","answer":"正直申し上げまして、適正に利用されている方、明らかに適正でない方、それについては当然現場としてもご注意申し上げているわけですが、それと、どうもちょっと疑わしい方、大きく分けると３つの層に分かれるとは思いますが。","voiceIndex":125,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"Ａ階層の方は生活保護世帯ということなんですけど、この方が今度月額利用というのがなくなるわけですけど、たくさん働いて結構たくさんな額になると思うんですけども、これは生活保護費がプラスとして出るのかどうかということを１つお聞きしたいのと。それともう一つ、適正でない、必要のない日も利用してしまうケースというのは、具体的にどういうことなのかも教えてください。","respondent":"金子保育課長","answer":"例えば仕事上で飲食をされる方もあり得るとは思いますが、やはり、かなりアルコールが入って夜お迎えに来るという方が結構いらっしゃるということでは、単に仕事以外にもお飲みになっているということが想定されることが２つの大きな例です。","voiceIndex":127,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここら辺のところを、生活保護というのは最低基準ということで考えられているにもかかわらず、負担をするというのは、そこが守れなくならないかというあたりの考え方について、１つ教えてください。１万５００円を生活保護の方がプラスで支払うというのはすごい大変なことになるかなと思うんですけど、そこら辺のところを教えてください。","respondent":"黒田生活福祉課長","answer":"だから、本来ですと、延長して働いていただければ、こちらはほんとうにありがたいことなんですが、自立に向けて働いているということですので。働かずに延長というのは、その辺はご自分で負担していただくというのは筋ではないかとは思っております。","voiceIndex":129,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"Ｄ４の人、それからＤ１３の人も、私、ちょっと計算してみたんですけど、Ｄ４の人は３.６９倍になって、Ｄ１３の人は３.３倍というふうに計算になって、例えばＤ１３の人が２時間を超えて２０日間利用するとなると、現在６,３００円で済んでいるものが２万１,０００円で、プラス１万４,７００円と、こういう負担増になると、私は計算したところこういうふうな数字が出たんですけど。","respondent":"金子保育課長","answer":"私どもとしましては、従来の日額、例えば１時間４００円を全階層にわたっていただくという考えもありましたが、ただし、やはり所得階層に応じて一定の配慮をしなければならないということで、５割、６割、８割という下の階層。","voiceIndex":131,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"Ｄ４とかいう方は収入がどれぐらいの方なんでしょうか。その方で、例えば２０日間預けていらっしゃる方とか、そういう方も実際に十五、六日間が平均だというので、２０日間ぐらい預けているという方も結構いらっしゃるんじゃないかなと思うんですけど、こういう方がどういうふうな負担増になるのか。そこら辺のところはどう考えられているんでしょうか。","respondent":"金子保育課長","answer":"なおかつ、負担増についてはいろいろな工夫をして抑えるというのが今回のお示ししている案ですので、その辺のところでご理解いただければと考えております。","voiceIndex":133,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほど平均で十五、六回というふうにお聞きしましたけど、１時間以内と１時間を超えた２時間以内と、２時間を超えて３時間３０分というふうに３段階に分かれていますけど、この使っている割合を教えてください。","respondent":"金子保育課長","answer":"８時半までお預かりしている方が８.９人、１０時までお預かりしている方が４.１人ということで、これが平日で１０時までの園での平均になっています。ですので、大体利用されている方の半分近くが７時半までの利用というふうになるかと思います。","voiceIndex":135,"id":"exchange-054"},{"speaker":"須藤委員","kind":"質問・要望","question":"今言ってもらったんですけど、１時間というので。全園ではこの利用者数というのはどのくらいあるんでしょうか。実際の利用者がどういうふうに使われているのかなということを教えていただきたいのと。それから、利用日数、今平均で１５か１６日というようなお話をいただいたんですが、そのあたりをもう一度お願いします。それもあれば教えていただきたいと思います。","respondent":"金子保育課長","answer":"平均の利用日数というのは、利用されている方の平均ということでは大体１５日ちょっとというふうに計算上出しています。３点目の所得階層によった利用日数というのは、申しわけありませんが、そういうデータは持ってございませんので、ご理解いただきたいと思います。","voiceIndex":137,"id":"exchange-055"},{"speaker":"須藤委員","kind":"意見","question":"今お話しして、夜間保育、延長保育、７時半ということで１０ちょっと、３７で割るとというような状況もあると思うんですけれども。今延長保育をされている、あるいは夜間保育されている方向性というのは、そういう地域でこうやり出してきているのか、園の状況によって対応できますよという形でやられているのか、お聞かせ願いたいと思います。","respondent":"金子保育課長","answer":"私どもとしては、確かに今どうしても、先ほど申し上げました五反田、大崎、大井町近辺、あるいは旗の台、源氏前あたりというところが非常に利用が多いわけですけれども、ご指摘の、例えば地域性、７時半までの園で結構利用が少ない園というのも数多くありますので。","voiceIndex":139,"id":"exchange-056"},{"speaker":"大西委員","kind":"質問","question":"この月額をなくして日額にするということですが、先ほど言うように不適正な利用ということでしたが、大体不適正な利用をされている方が今利用されている中で何％ぐらいおられるのかということと、それと、時間外の夜間保育に関して、このＡからずっとＤ２１までありますが、これに何か特徴、例えばＤの数の多いほうが１０時まで利用しているとか、もしくは、Ａとか、Ｂとか。","respondent":"金子保育課長","answer":"所得に応じてこの時間外の利用についての何か特徴ということですけれども、きちっと掌握したわけではないんですが、１０時までの園で夜遅く使っていらっしゃる方で、もちろんすべてではありませんが、職種から見ても、例えば医師であるとか、弁護士であるとか。","voiceIndex":141,"id":"exchange-057"},{"speaker":"大西委員","kind":"質問","question":"ちょっと今、私自身、質問漏れがありましたので。この１項目に関してですね。２項目目の保育サービスと比較して月額の利用料が抑えられているから、サービスに見合ったものとしては相当すると思うんですけど、１の場面のところからすると、どれぐらいの不適正な利用があるかによってこの部分は少し考えられるんじゃないかと思うんですが、その辺はどうでしょう。","respondent":"金子保育課長","answer":"私の知る限りにおいては、そういった方々で１０時まで利用されている方については、できる限り子どもとの触れ合いの時間を大切にしたいと考えていらっしゃる方が結構多いというふうに聞いておりますので、その意味では、そういうふうな安易な利用に走られるという方は。","voiceIndex":143,"id":"exchange-058"},{"speaker":"大西委員","kind":"質問","question":"質問の仕方が悪かったんですが、ご職業の階層ということじゃなしに、不適正だなと思われる人たちはこのＤ１３とか２１とか、そういう階層の人たちに不適正な利用が見られるのか、そういう特徴があるのかどうか。その辺での、不適正なのはこの辺の人に多いとか、もしそういう特徴があれば、若干知りたいということで教えていただければと思います。","respondent":"金子保育課長","answer":"今の委員のご質問なんですけれども、そういうふうな所得階層によってどうかというデータはとってはございませんので、申しわけありませんが、ご理解いただきたいと思います。","voiceIndex":145,"id":"exchange-059"},{"speaker":"大沢委員","kind":"質問・要望","question":"質問と要望と両方ともちょっと話を。そもそも保育の主体というのは子どもだと思うんですが、子どもの睡眠時間について行政の側ではお調べになっているのか、いないのか、お答え願いたい。","respondent":"金子保育課長","answer":"ですが、そういった方もいらっしゃるし、そうでない方ももちろんいらっしゃるということはあるとは思います。","voiceIndex":147,"id":"exchange-060"},{"speaker":"大沢委員","kind":"質問・要望","question":"平均の睡眠時間はそれぐらい。本来子どもにとらせなければいけない睡眠時間から大きく離れております。そういう回りの状況を見て、本区においてはより利用しやすい延長保育の体制を整えていくということは非常にいいことなんですが、主体たるべき子どもの睡眠時間なども、今後運営する上において考慮をしながらやっていっていただきたいなと思います。要望で終わっておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-061"},{"speaker":"飯沼副委員長","kind":"質問","question":"先ほど平均の日数が十五、六日ということで、Ｄ１０のところを計算してみました。日割りを、月の平均十五、六日に直すとどうなるのかと。やっと知られて定着してきたときに値上げというのが、これ、ブレーキがかからないんでしょうか。必ずしもそうではなくて、やはり月々の負担が大きいということでは、これ、大きな負担になると思うんですが、その点に関してはいかがでしょうか。","respondent":"金子保育課長","answer":"委員ご指摘のＤ１０階層ですね。Ｄ１０階層、確かに、例えば１時間以内ですと、今度１５回利用すると４,０００円です。それは例えば３歳未満児ですと２,９００円ですから、延長夜間に限っては月で１,１００円の増になると。","voiceIndex":150,"id":"exchange-062"},{"speaker":"飯沼副委員長","kind":"意見","question":"とにかく保育料と延長夜間保育のこの決まりのところで、私は期待しているお母さんやお父さんの期待を裏切ってしまう、子育ての応援にならないんじゃないかなと、評判を落とすんじゃないかと思うんですけども、その辺はいかがでしょう。","respondent":"金子保育課長","answer":"そういう意味では、私どもの今回の料金体系の変更というのをきちっとご趣旨を説明していただければ、ご理解いただけるのではないかなと考えているところです。","voiceIndex":152,"id":"exchange-063"},{"speaker":"飯沼副委員長","kind":"質問","question":"子どもが遅くまで保育園に預かってもらっているという状況は決していい状態ではないと思います。子育ての一義的な責任は親があるので、早く帰れるような労働条件になればいい。でも、その不適切なことの対応のために、夜遅くまで働かざるを得なくて一生懸命働いていらっしゃる方に私はしわ寄せが行ってしまうものだと考えていますけれども、いかがでしょうか。","respondent":"金子保育課長","answer":"労働時間の関係とそれぞれの収入の関係というのはちょっと難しいところがあるかと思いますが、私ども、今回の利用料の体系から、何度か申し上げてはおりますが、従来の日額とは違って、低所得の方にもそれなりに配慮して減額する措置、また。","voiceIndex":154,"id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほどの質問で、全体が３,９７８人で、７時半までは２６０人が利用しているということだったんですけど、あと、１時間を超えて２時間以内と、２時間を超えて３時間以内、これ、それぞれの数と全部合わせると、この時間延長を利用している方が何人いるのかを教えてください。","respondent":"金子保育課長","answer":"７時半までの利用をされているのが、平日の平均で１日当たり全園で２６０人、８時半までが８２.３人、１０時までが２８.３人です。これらをトータルしまして、何らかの形で延長夜間を利用されている方というのが３７０.５人いらっしゃるです。","voiceIndex":156,"id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中で、さっき言われたＤ４というのは３００万円からの所得ですか、というふうなことで言われましたけど、そういう方が例えば２時間を超えて２０日間利用すると、１カ月１万２,２５０円の負担増になるんです。これを１年間にすると１４万７,０００円になっちゃうんです。６倍とか、３.７倍、３.３倍、これは大き過ぎるんじゃないかと思うんですけど、そこの観点ではどうでしょうか。","respondent":"金子保育課長","answer":"Ｄ４階層、３階層あたりのことでご質問をいただいていますが。先ほどから申し上げているとおり、私どもとしては１日単位でいただくことによって一定の抑止力が働くだろうと見込んでの改定です。","voiceIndex":160,"id":"exchange-066"},{"speaker":"飯沼副委員長","kind":"意見","question":"態度表明、反対の立場でしたいと思います。今論議したように、特に低所得者の方への負担が大きいと思われます。児童福祉法の中には保育料の徴収に関して応能の負担を書かれている部分があるんですけれども、こういった面で特に低所得者に負担がかかる。応能負担から応益負担に変わろうとしている中身を含んでいるので、これに対して反対をしていきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-067"}]},{"id":"topic-04","title":"引き続き、議案(4)、第３１号議案 指定管理者の指定","agenda":"引き続き、議案(4)、第３１号議案 指定管理者の指定","exchanges":[{"speaker":"若林委員","kind":"質問","question":"今のご説明にもありましたが、国のほうから選定に関して複数の申請者の中から選びなさいという指導が確かにありまして、そのような今、今回特別なケースをたどりながら、最後には絞り込んだということとお聞きをいたしました。そのほかに公募はあえてされたのか、されなかったのか。１点お聞きをいたします。","respondent":"日下部障害者福祉課長","answer":"知的だけです。それから、入所施設の新たな運営ということもありますので、そういったことも含めて、福栄会のほうとしては現状では応じることは難しいという、そんなお話もございました。","voiceIndex":169,"id":"exchange-068"},{"speaker":"若林委員","kind":"質問","question":"裏面のほうのエとオとキとありますね。ここを具体的にざっと、例えば第三者委員とかにちょっとお触れになったかと思いますけども、特にエとオとキ、第三者委員制度、旗の台でどのようになるのか、例えば地域とはどういうものかとか、オ、サービス改善向上委員会とはどのようなものか、キ、地域社会との連携の確立。具体的にあれば教えてください。","respondent":"日下部障害者福祉課長","answer":"ということで、会館の運営委員会、これは実は地域の皆さんにもご参加をいただいて、今年に１回ですがこの委員会を開催しておりますが、当然のことながら、この運営委員会も継続をいたします。毎年７月に会館祭りということで会館全体のお祭りをやっております。","voiceIndex":171,"id":"exchange-069"},{"speaker":"若林委員","kind":"質問・要望","question":"具体的にこの苦情をキャッチするのはどういう窓口というか、人というか、現場でキャッチするのか、想像できないのでお教え願いたいと思います。このずれがどういう計算になるのか教えていただきたいと思います。関連して、職員が２５名から、今回栄養士を入れて２０名になるということで、逆に、この人数でサービスの向上をやっていくんだというような見通し、ご決意をお聞かせ願えればと。","respondent":"日下部障害者福祉課長","answer":"こういう取り組みも、おそらく今年いろいろ検討して具体的に進められることになると思います。","voiceIndex":173,"id":"exchange-070"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、今度は我々がいろいろなことをということで、この概要、支援方針で今の質問と同じなんですが、苦情解決に向けた第三者委員制度の活用という表現をされたんですけども、今まででどういった活用がなされたのか、メンバーについてはお聞きしました。そことの整合性。そこの指定管理者も施設の使用許可、取り消し等をということがどういうふうに使われるのか、お聞かせ願いたいと思います。","respondent":"日下部障害者福祉課長","answer":"一方で、私ども区のほうとしましては介護保険に始まって、今では障害者の支援費制度に移りましたから、そういった意味で介護保険と障害者サービスを中心にしてサービスの向上委員会ということで、苦情対応を含めて、苦情対応やサービス評価ということで。","voiceIndex":175,"id":"exchange-071"},{"speaker":"須藤委員","kind":"質問","question":"だんだんこの品川総合福祉センターが大きな仕事をやってきたときに、細かいいろいろなものは、今言ったようにサービス向上に向けた向上委員会に上げてきて、なおかつそこで問題があれば、第三者のそういったところに行くのかなとか、いろいろな考えをしながら質問しているんだけれども、それのとらえ方はいかがなのかなと。その辺、聞かせてください。","respondent":"日下部障害者福祉課長","answer":"これにつきましては、ある意味で、指定管理者として管理代行をする立場からすれば、向上委員会とか第三者委員会が適正に運用されているかどうかというのは非常に重要な関心事でもありますし、これがある意味で施設自体の適切な管理運営。","voiceIndex":177,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここ、指定期間のところが５年間ということになっているんですけども、これは５年間過ぎたら、また条例で指定期間を決めることになるんでしょうか。その場合の年数というのの考え方について教えていただきたいのが１点です。もう一つ、こういうふうに指定管理者で委託された場合、監査についてはどうなるのかについても教えていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"監査の関係ですが、これは前回の委員会で私のほうで改めて確認するというお約束になっておりましたが、自治法の１９９条の中で、公の施設の管理を行わせる者についても、これは監査の対象になるということで法的に明記をされておりますので、対象になってまいります。","voiceIndex":179,"id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"態度を表明させていただきたいと思います。この指定管理者に指定された、前回も言いましたけれども、品川総合福祉センターに関しては実績も経験も十分に評価するところですけれども、この心身障害者福祉者会館が唯一品川区直営の心身障害者の施設であるので、その直営の施設をしっかりと区として運営して、その中で政策化をしていくべきだという考えで反対することを述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-074"}]},{"id":"topic-05","title":"では、次に移ります。(5)の第３２号議案 指定管理者の指定、同じでございますけれども、中身は違います。第３２号議案","agenda":"では、次に移ります。(5)の第３２号議案 指定管理者の指定、同じでございますけれども、中身は違います。第３２号議案","exchanges":[{"speaker":"若林委員","kind":"確認","question":"初めに、これは一般か代表質問でもあったと思いますが、幼保一元化のいわゆる特区の問題、認定がいただいていないという部分がありました。ちょっと確認をします。","respondent":"金子保育課長","answer":"特区の提案につきましては、企画部のほうで所管しておりますが、私の聞く範囲、あるいはホームページ等で国の考え方などを見ておりますと、今回の幼稚園、高校の部分についての運営の委託というのは検討されたようですが、実現には至っていませんで。","voiceIndex":189,"id":"exchange-075"},{"speaker":"若林委員","kind":"質問","question":"中身のほうですが、大きな３の(3)の3)、子育て支援センターが入ります。これも、今回のいわゆるＮＰＯ法人で子育て支援センターを運営するということでしょうか。それから、子育てひろば事業という新しい言葉だと思いますが、これの内容、中身、その根拠をお示し願います。","respondent":"辻田児童課長","answer":"子育て支援センターは児童課のほうの所管になりますので、私のほうからお答えいたします。初め、子育て支援センターも、このぷりすくーるの中の私立幼稚園のノウハウをいろいろ生かした中でこれを運営していきたいというぐあいに、今進めているところです。","voiceIndex":191,"id":"exchange-076"},{"speaker":"大沢委員","kind":"質問","question":"実施事業の２のところで、私、勉強不足で申しわけないんですが、1)と2)のところで、ぷりすくーる西五反田保育園はいいんですが、私はこれは西五反田幼稚園とばかり思っていたんですけれども、これは西五反田幼児教育施設、幼稚園教育要領に準じた教育を提供する施設と書いてあって、なぜこれは西五反田幼稚園ではないんでしょうか。ちょっとお教え願いたいと思います。","respondent":"金子保育課長","answer":"そもそも今回の施設はこういった保育園部分と、幼稚園的な部分、さらに子育て支援センター、これを１つの運営主体で運営をお願いしようと思っておりましたし、この運営については直営ではなくて委託ということを考えておりましたので、その意味で。","voiceIndex":195,"id":"exchange-077"},{"speaker":"大沢委員","kind":"意見","question":"これも、周りの入ってこられるお母さん方に対する告知の方法だと思うんですが、入ってくる方はそこまで要領はよくわからないで、されど名称、たかが名称と思うんですが、このところは幼稚園ではなくて、そういう形のもののご説明は徹底させていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":197,"id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そしてまた、報告書について、また、監査についても同じことをお聞きしたいと思います、１点。先ほどの2)の参加とセレクト型の保育というところで、セレクトの中身は給食か弁当かを選ぶということと、２時までか預かり保育かを選ぶという説明があったんですけど、ここでは保育内容の選択と書いてあるんですけど、そこら辺のところがどういうものなのかを、まず教えていただきたいと思います。","respondent":"金子保育課長","answer":"保育園関係のところのお尋ねで、幼児教育施設への進級を見据えたというところは、私どものこの施設の１つのコンセプトとして、０歳から５歳まで一貫した方針で一貫した教育を行っていこうというふうに考えておりますので、保育園とこの幼児教育施設が分断された形で運営。","voiceIndex":198,"id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ＮＰＯ法人の園長、代表理事は書かれているんですけど、副の２人というのもどなたなのかを具体的に教えていただきたいのと。１点です。実際に今日この指定管理者を決めるという状況であるにもかかわらず、議会で決まる前からこういうふうなパンフレットが既に出されているということはどういうことなのか、このことについてお聞かせください。","respondent":"金子保育課長","answer":"このパンフレットの中を開いていただければおわかりになるかと思いますけれども、このぷりすくーる西五反田の運営を行う予定であると。あくまでも予定というふうに断ってすべて記載、あるいは説明をするようにしております。そういうことでご理解をいただきたいと思います。","voiceIndex":200,"id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"中を開くと予定となっていますけど、外にはしっかりと子育て品川というふうに書いてありますので、これは議会軽視じゃないかと思いますので、そのことを１つ指摘をさせていただきたいと思います。もう一つ、支出のほうの人件費なんですけど、給料、手当、社会保険料としか書いていないんですが、職員はどういう資格の人がどれぐらい、経験年数がどれぐらい、そこら辺のところを教えていただけますでしょうか。","respondent":"金子保育課長","answer":"というのは、先ほど来説明しているとおり、あくまでもこの施設は法制度上は３つの施設になるわけですけれども、一体的な運営を考えておりますので、大まかな区分にすぎないというふうに考えているところです。","voiceIndex":202,"id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"経験年数のところはまだわからないというところなんですけれども、他の区でやはりこういう民間に委託をした保育園で、ふたをあけて見たら、新卒の人が半分以上だったというところで、父母の中から大きな問題になっているという園があるということも聞きましたので、そこら辺のところはしっかりと見ていただいて、ご報告もいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-082"},{"speaker":"飯沼副委員長","kind":"質問","question":"特にこの保育内容、教育内容について、この間全く中身が示されなかったので、その中身を知らせてほしいとずっと質問を続けてきたわけですけれども、１１月２５日のところまで中身の具体性はなかったわけです。その辺の進め方について、まずお伺いしたいと思います。","respondent":"金子保育課長","answer":"パンフレットの作成、設置の経過ですが、私どもとしましては、今回通常の管理委託ではなくて、指定管理者制度の新しい活用ということで、一般的に例えば４月から委託を予定しているということで進めてしまうわけにもいかず。","voiceIndex":205,"id":"exchange-083"},{"speaker":"飯沼副委員長","kind":"質問","question":"私が言っているのは、なぜこの委員会に中身を報告しないのか。１月２０日にできたはずです。もう一つは、今日、せめてこのパンフレットを委員に配ってもよかったのではないでしょうか。私たちはたまたま保育課を訪ねて発見をしたので、いただいてきて中身を見ましたけれども。できたばっかりで実績がないといったところでは、このような報告でいいんでしょうか。姿勢が問われると思いますけど。","respondent":"金子保育課長","answer":"委員のいろいろなご指摘ですけれども、全く新しく、そこでの構成メンバーも全く知らない人たちによるＮＰＯの法人、あるいはそのほかの法人であれば非常に問題の部分もあるかと思いますが、私ども、従前から申し上げているとおり、今回のこの法人に関しては。","voiceIndex":207,"id":"exchange-084"},{"speaker":"飯沼副委員長","kind":"質問","question":"議会で理解をしてほしいんだったら、もうちょっと今代表者のお１人のお名前があるだけでしたね。出ている書類はこれだけなんですよ。今まで実績がある、実績がある、私立でやってきたと。それだったら、質問する前に、副理事長とか、あと、どういう組織体になって、どういう人たちが絡んでいるのかという図があって、私はしかるべきだったと思うんですけれども、その辺はいかがでしょうか。","respondent":"金子保育課長","answer":"そういう意味では、この３人の実績と、並びに運営の検討経過の中では十分足りるものであるし、この法人というものも新しくできたばかりの法人ではありますが、それなりに実績というものも、例えばこの代表理事の園長については。","voiceIndex":209,"id":"exchange-085"},{"speaker":"飯沼副委員長","kind":"質問","question":"区が実際にこのＮＰＯ法人を立ち上げるに当たってかなり援助をしているわけですね。支援をしながらやっているというところでは、区が審査をしたその中身の公平性というものを区民に示す意味では、私はもっと書類とかをきちんとそろえて、材料を提出して判断をしてもらう、この姿勢が必要と思いますが、いかがでしょうか。","respondent":"金子保育課長","answer":"今、委員のご発言の中に、区が援助しているというふうにお話がございましたが、私どもとしましては、今回の施設のコンセプトと運営の考え方等々についていろいろ協議はしてまいりましたが、区が援助してきたということはございませんので。","voiceIndex":213,"id":"exchange-086"},{"speaker":"飯沼副委員長","kind":"質問","question":"内容のほうに行きたいと思いますけれども。教育とか保育というのはやはり人とのかかわりが大きいと思うんですけれども、質と量にかかわるところで、職員の体制をもう一回改めてきちんと聞きたいんですが。施設ごとに配置をされる。法人でもし固有で職員がいるとしたら、その人数も教えてほしいんですが。","respondent":"金子保育課長","answer":"その意味では、幼稚園の部分と保育園の部分、それから子育て支援センターも併設されるわけですので、２３人から２５人というふうに予定していると聞いておりますが、その人員では十分な運営ができるのではないかと。","voiceIndex":215,"id":"exchange-087"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"資格については問題ないと。ちょっと聞き漏らしているので、その辺をもう一回、再度お答えいただきたいんですが。","respondent":"金子保育課長","answer":"資格については、先ほど申し上げましたとおり、この幼児教育施設と保育園の部分については、幼稚園教諭と保育士の資格を両方を持った職員をそろえるということで考えているというふうにお聞きしておりますので、その意味で問題はないかなと考えております。","voiceIndex":217,"id":"exchange-088"},{"speaker":"飯沼副委員長","kind":"質問","question":"今、最低１２人はというところの、そこの部分のお話でしょうか、今のことは。","respondent":"金子保育課長","answer":"いえ、そういう意味ではなくて、採用する２３から２５人についてという意味です。","voiceIndex":219,"id":"exchange-089"},{"speaker":"飯沼副委員長","kind":"質問","question":"もうあと二点なんですが。今回の中身を見てみますと、選択とかセレクトという言葉が入っていますけれども、実際利用料のところでいろいろな方の保育を選んだ場合に、最終的に親の負担が大きくなるのではないかなと思うんですけれども。その辺が、例えば現在幼稚園で預かり保育をしているところの比較とか、保育園で長時間預けた場合とか、比較した場合のセレクトの中身の比較対象とかはしているんでしょうか。","respondent":"金子保育課長","answer":"そういった利用料関係の設定につきましても、一応運営の側で決定できるわけですが、私どもとしては、それについてきちっと協議をしていただいて、了解の上実施していただきたいと考えているところです。","voiceIndex":221,"id":"exchange-090"},{"speaker":"飯沼副委員長","kind":"質問","question":"もう一点、前回も教育と保育の関係、この指定管理者制度の問題で、非営利を貫いてほしいという発言をしたんですけれども、このＮＰＯ法人、特定非営利活動法人子育て品川とありますけれども、この法人が非営利を貫いていけるというところで、どのようなチェックができるのかお伺いしたいと思います。","respondent":"金子保育課長","answer":"その意味では十分な保育内容を実施していただけるような金額であるし、あるいはもう一方で、余剰が出るような金額ではないというところで、経験的に数字を固めていって、経費で運営をしていただくように努力していただきたいと考えているところです。","voiceIndex":223,"id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"この施設が特区の提案をして、それの許可が出ないまま品川区独自にやるということなんですけど、特区申請の提案を見ると、幼保一元化施設について、これからも他の区立幼稚園も経年のため大規模改修の時期が迫っており、この時点においては保育所機能を取り込み、運営は株式会社等の民間活力を導入する予定であるということで書かれているんですけれども。","respondent":"金子保育課長","answer":"そこの文言というのは、今後の区立幼稚園のあり方、あるいは運営主体はどうするかというのは、さまざまな選択肢がある中で広く考えていくという趣旨であるというふうに、私どもとしては考えてあります。","voiceIndex":225,"id":"exchange-092"},{"speaker":"飯沼副委員長","kind":"意見","question":"このぷりすくーる西五反田、新しく待機児の受け皿としての１つの施設であるという意味で、前回の条例のときは賛成をさせていただいたんですけれども、今回、このＮＰＯ法人子育て品川について検討させていただいたんですけれども、中身がまだ不明確、不透明であるという不安定な状況では賛成しかねるということで、反対をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":228,"id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"説明をします。今回で乳幼児医療費助成制度の改正提案は８回目となります。今回所得制限をなくし、ぜひ小学校６年生まで所得制限のない医療費助成制度としていただきたいと思って、今回提案をさせていただきました。やはり子どもは社会の宝、かけがえのない子どもの命と健康を大事にということで、どの子もお金の心配をせずに医療にかかれるようにということで、今回も所得制限の撤廃を求めるものです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":233,"id":"exchange-094"},{"speaker":"須藤委員","kind":"提案","question":"今の表のところで理事者にお尋ねしたいんですけれども、数字で独自の所得制限、所得６１４万円以下という数字があるんだけど、この辺の出方が、こういう数字だったかなという気がするんだけど、それが１つ。それから、提案者のほうで、前にもお話しさせていただいたんですが、全額制限なしでいった場合の予算的な差額というのはどうなってくるのか。そのあたりを聞かせてください。","respondent":"辻田児童課長","answer":"間違いであるかということであれば、これは２００２年８月１日ですので間違いではないんですけど、資料としては、品川区のところの独自の所得制限というところが、６１４万円以下・扶養ゼロということになっております。","voiceIndex":235,"id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"新たに対象になる方が１,５００人ぐらいということなんですけれども、それにかかる費用というのが６,８００万円というのは、これは前にも区のほうから質問したときにご答弁いただいていますし、今回改めて問い合わせをして確認をしている数字です。予算修正も提案する予定なんですけれども、それは予算委員会のほうで修正をさせていただきたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":237,"id":"exchange-096"},{"speaker":"須藤委員","kind":"意見","question":"それがちょっとつかみ切れませんというと、なかなか経営的な税のあり方というものを今後どういうふうに考えていくかというのは、先ほど来いろいろ出てくる子育て支援全体で、いろいろな面で考えましょうというような状況になってはいかがかなという感じです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":238,"id":"exchange-097"},{"speaker":"三上委員","kind":"意見","question":"１つだけ。これは私の意見という形になるかもわかりませんが、今の東京２３区の制度一覧、２００２年８月１日のこういう古い資料を出して、これはやっぱり不誠実ですね。現段階でこの書類１枚だけどうにでもつくって出そうと思えばできることであって、現段階のことをきちっと出していかないと、これは判断を間違っていってしまう。一言だけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":239,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区のホームページに２月１３日から３月１２日まで意見を求めるということで掲載しているということなんですけど、これ、保健高齢事業部を開いて、そこから行かないと全然わからないんです。これを知っている人はこうやって行けますけど、ぱっと品川区のホームページを開いたところでわかるというふうになっていないので、そういうふうにしていただけないでしょうかということが１点です。","respondent":"田中健康課長","answer":"関係団体というのは、いろいろな事業の関係の方がありますので、それぞれの会議です。例えばすし屋さん等、業態の関係の組合ですとか、いろいろな方がありますので、そういう方にご案内を差し上げるです。","voiceIndex":246,"id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃ、ホームページのほうはぜひよろしくお願いします。それと、衛生推進委員ですか、どういう方がメンバーになっているのかも教えてください。","respondent":"島袋品川区保健所衛生課長","answer":"食品衛生推進委員というのは、区長から委託して１８名なんですが、実際は１６名なんですけど、お店の衛生指導をしていく指導者的な立場の方。今参事がおっしゃいましたけど、品川食品衛生協会というのがございまして、そちらの各業種の代表者の方がやっているところです。","voiceIndex":248,"id":"exchange-100"},{"speaker":"飯沼副委員長","kind":"質問","question":"１点だけ。よく読んでいないので、どこかに出ているのかなと思いつつも、遺伝子組みかえ食品についての消費者の選択といおうか、表示の問題とか、その辺に関しては、含まれるとしたらどこの項目に入るのでしょうか。","respondent":"島袋品川区保健所衛生課長","answer":"２ページの輸入食品のところと、６番目の適正食品表示のところが、大体遺伝子組みかえも含めまして対応しようと考えているところです。","voiceIndex":250,"id":"exchange-101"},{"speaker":"飯沼副委員長","kind":"質問","question":"あえて文言が入っていないということは、この中に含まれているということで入っていないのでしょうか。","respondent":"島袋品川区保健所衛生課長","answer":"その遺伝子組みかえ食品も含めまして、例えば表示等につきましては、最近よくあるのにはアレルギー表示とか、添加物とか、そういう表示全体の中に含まれていると考えていただきたいと思います。","voiceIndex":252,"id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この精密検診の公費負担廃止によって予算額がどれぐらい区の負担が削減されるのかを１つ、教えていただきたいのと。それから、胃がん、肺がん、大腸がん、乳がん、３割の分を負担していたということなんですけど、３割の分というのがそれぞれ幾らぐらいなのか教えていただきたいと思います。そのことについて教えてください。","respondent":"田中健康課長、寺西品川区保健所保健サービス課長","answer":"ちなみに大体のラインで私ども、予算上立てている計算でいきますと、胃がんが５,０００円程度、乳がんが３,８００円程度、肺がんが６,７００円程度。保健所の間接撮影の件数ですが、１４年度は８２４件、１１年度から１３年度にかけましては保健センターも行っておりますので、両所を合わせまして約１,０００件ぐらい行っておりました。","voiceIndex":258,"id":"exchange-103"},{"speaker":"飯沼副委員長","kind":"質問","question":"２番目の保健所等区民健康診査についてなんですけれども、先ほどのご説明だと、健康診査を健康相談にシフトしていくというご説明だったので、そこの中身をお伺いしたいのと。新たに日曜健診を実施する。これはとても歓迎されると思うんですが、年３回は余りにも回数が少ないので、せめて月１回ぐらい行ったらどうかなと思うんですが、いかがでしょうか。","respondent":"田中健康課長","answer":"保健所等で補完的にという形でご説明申し上げましたが、区民健診等、今件数を申し上げましたとおり保健所等で現在行っている比率というのは１割満たないところです。","voiceIndex":263,"id":"exchange-104"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった面では、受診する方が減るような傾向にはないと受けとめてよろしいのでしょうか。年３回、試みでということで日曜を始めるということなんですけれども、年３回だと、そこにぶつかるのが、うまく当てはまるのはなかなか難しいかなと思うので、ぜひこの回数を多くしていただきたいなと思います。いかがでしょうか。","respondent":"田中健康課長","answer":"このニーズは、例えば予約制にしますので、どのくらいの予約の数がある等、十分把握をいたしましてまた検討してみたいと思います。","voiceIndex":265,"id":"exchange-105"},{"speaker":"塚本委員長","kind":"質問","question":"ないようでしたら、本件を終わります。引き続き、その他ですが、委員のほうから指摘すべきこと、ありますか。ございませんか。恒例となっております本会議で一般質問があった事項の中で、理事者に問い合わせたいことがありましたら、きょう通告いただきまして、あすまでに準備できるですので、何か所管調査事項の中で本会議で指摘のあったこと、質問通告がありましたら願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":268,"id":"exchange-106"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3070#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":99397,"voices":269}}]);
